/// Get the current mission (if any).
pub async fn get_current_mission(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
) -> Result<Json<Option<Mission>>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    let current_id = *control.current_mission.read().await;

    match current_id {
        Some(id) => {
            let mission = control
                .mission_store
                .get_mission(id)
                .await
                .map_err(internal_error)?;
            Ok(Json(mission))
        }
        None => Ok(Json(None)),
    }
}

/// Get tree for a specific mission.
/// For currently running mission, returns the live tree from memory.
/// For completed missions, returns the saved final_tree from the database.
pub async fn get_mission_tree(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
) -> Result<Json<Option<AgentTreeNode>>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    // Check if this is the current active mission
    let current_id = *control.current_mission.read().await;
    if current_id == Some(mission_id) {
        // Return live tree from memory
        let tree = control.current_tree.read().await.clone();
        return Ok(Json(tree));
    }
    let tree = control
        .mission_store
        .get_mission_tree(mission_id)
        .await
        .map_err(internal_error)?;
    if tree.is_some() {
        return Ok(Json(tree));
    }

    let mission_exists = control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?;
    if mission_exists.is_some() {
        Ok(Json(None))
    } else {
        Err((StatusCode::NOT_FOUND, "Mission not found".to_string()))
    }
}

/// Get current execution progress (for progress indicator).
pub async fn get_progress(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
) -> Json<ExecutionProgress> {
    let control = control_for_user(&state, &user).await;
    let progress = control.progress.read().await.clone();
    Json(progress)
}

/// Query params for the unified mission events endpoint (P3-#18).
///
/// `GET /api/control/missions/:id/events` is the canonical cursor
/// endpoint for fetching persisted events. With `since_seq=N` it returns
/// events strictly after sequence N. With `before_seq=N` it pages backwards.
/// Use `view=transcript|trace|history|all` or explicit `types=` filters.
#[derive(Debug, Clone, Deserialize)]
pub struct GetEventsQuery {
    /// Comma-separated event types to filter (e.g., "tool_call,tool_result")
    #[serde(default)]
    pub types: Option<String>,
    /// Preset event type view. `transcript` returns user/assistant rows,
    /// `trace` returns intermediate activity, and `all` disables filtering.
    #[serde(default)]
    pub view: Option<String>,
    /// Maximum number of events to return
    #[serde(default)]
    pub limit: Option<usize>,
    /// If set, return only events with `sequence > since_seq`, ordered
    /// by sequence ASC. Used by the client for delta reconnect to
    /// avoid redownloading the full event tail on every focus/reopen.
    #[serde(default)]
    pub since_seq: Option<i64>,
    /// If set, return only events with `sequence < before_seq`, ordered
    /// by sequence ASC (oldest first). Used by the client for backwards
    /// pagination — pass the lowest sequence already seen to fetch the
    /// next page of older events. Takes precedence over `since_seq`
    /// when provided.
    #[serde(default)]
    pub before_seq: Option<i64>,
    /// Whether to include total/count headers. Delta polling only needs
    /// `X-Max-Sequence`; skipping counts avoids an extra indexed DB scan.
    #[serde(default = "default_include_event_counts")]
    pub include_counts: bool,
    /// Optional response profile. `conversation` keeps the recent transcript
    /// hydrated while collapsing older tool payloads into lazy stubs.
    #[serde(default)]
    pub profile: Option<String>,
    /// Number of recent tool call/result pairs to keep fully hydrated for
    /// `profile=conversation`.
    #[serde(default)]
    pub trace_tail: Option<usize>,
}

fn default_include_event_counts() -> bool {
    true
}

const INACTIVE_EVENT_SUMMARY_AFTER: chrono::Duration = chrono::Duration::minutes(5);
const CONVERSATION_PROFILE_TRACE_TAIL: usize = 10;

#[derive(Debug, Clone)]
struct EventSummary {
    events: Vec<mission_store::StoredEvent>,
    original_count: usize,
    summarized_count: usize,
}

impl EventSummary {
    fn unchanged(events: Vec<mission_store::StoredEvent>) -> Self {
        let count = events.len();
        Self {
            events,
            original_count: count,
            summarized_count: count,
        }
    }
}

/// Gate for the event-logger task: which broadcast events get persisted.
///
/// Incremental thinking deltas (`done: false`) are broadcast-only — they
/// exist for live streaming and each carries the cumulative block buffer, so
/// persisting them is O(n²) in storage (some missions accumulated 100k+ rows).
/// Only the block-final `done: true` event, which carries the full block
/// content, is persisted.
fn should_persist_event(event: &AgentEvent) -> bool {
    !matches!(event, AgentEvent::Thinking { done: false, .. })
}

fn thinking_event_is_done(event: &mission_store::StoredEvent) -> bool {
    event
        .metadata
        .get("done")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
}

fn should_summarize_events(mission: &Mission) -> bool {
    if mission.status == MissionStatus::Active {
        return false;
    }

    let Ok(updated_at) = chrono::DateTime::parse_from_rfc3339(&mission.updated_at) else {
        return false;
    };
    chrono::Utc::now().signed_duration_since(updated_at.with_timezone(&chrono::Utc))
        > INACTIVE_EVENT_SUMMARY_AFTER
}

fn summarize_inactive_stream_events(events: Vec<mission_store::StoredEvent>) -> EventSummary {
    if events.len() < 2 {
        return EventSummary::unchanged(events);
    }

    let original_count = events.len();
    let mut summarized = Vec::with_capacity(events.len());
    // text_delta keeps the legacy last-wins collapse: deltas are cumulative
    // snapshots and only the latest matters.
    let mut pending_text: Option<mission_store::StoredEvent> = None;
    // Thinking collapses per *block*, not per run: a `done: true` row is a
    // block boundary and rows are never merged across it. Within a block we
    // keep one row carrying the last non-empty content (legacy data persisted
    // cumulative snapshots followed by an empty `done: true` finalizer;
    // current data persists exactly one full-content `done: true` row per
    // block, which passes through unchanged).
    let mut pending_thinking: Option<mission_store::StoredEvent> = None;
    let mut thinking_last_nonempty: Option<String> = None;

    fn flush_thinking(
        pending: &mut Option<mission_store::StoredEvent>,
        last_nonempty: &mut Option<String>,
        out: &mut Vec<mission_store::StoredEvent>,
    ) {
        if let Some(mut event) = pending.take() {
            if event.content.trim().is_empty() {
                if let Some(content) = last_nonempty.take() {
                    event.content = content;
                } else {
                    // A block that never produced content (legacy empty
                    // finalizer with no preceding deltas) — drop it.
                    return;
                }
            }
            // Force the kept row to close its block so the frontend renders
            // it as a finished thought.
            event.metadata["done"] = serde_json::Value::Bool(true);
            out.push(event);
        }
        *last_nonempty = None;
    }

    for event in events {
        if event.event_type == "thinking" {
            // Preserve interleaving: an open text_delta run ends here.
            if let Some(pending) = pending_text.take() {
                summarized.push(pending);
            }
            let is_boundary = thinking_event_is_done(&event);
            if !event.content.trim().is_empty() {
                thinking_last_nonempty = Some(event.content.clone());
            }
            pending_thinking = Some(event);
            if is_boundary {
                flush_thinking(
                    &mut pending_thinking,
                    &mut thinking_last_nonempty,
                    &mut summarized,
                );
            }
            continue;
        }

        // Any non-thinking event closes an open thinking run first to
        // preserve ordering.
        flush_thinking(
            &mut pending_thinking,
            &mut thinking_last_nonempty,
            &mut summarized,
        );

        if event.event_type == "text_delta" {
            pending_text = Some(event);
            continue;
        }

        if let Some(pending) = pending_text.take() {
            summarized.push(pending);
        }
        summarized.push(event);
    }

    flush_thinking(
        &mut pending_thinking,
        &mut thinking_last_nonempty,
        &mut summarized,
    );
    if let Some(pending) = pending_text {
        summarized.push(pending);
    }

    EventSummary {
        original_count,
        summarized_count: summarized.len(),
        events: summarized,
    }
}

fn conversation_profile_enabled(profile: Option<&str>) -> bool {
    matches!(profile, Some("conversation"))
}

/// Interactive/frontend tools whose call args (the question payload) must
/// survive history projection so the dashboard can render the item — even
/// after it's answered. Mirrors the dashboard's `isUiTool` check.
fn is_interactive_ui_tool(name: &str) -> bool {
    name == "question" || name == "AskUserQuestion" || name.starts_with("ui_")
}

fn project_conversation_events(
    events: Vec<mission_store::StoredEvent>,
    keep_full_tool_call_ids: &HashSet<String>,
    tool_summaries: &HashMap<String, mission_store::ToolCallSummary>,
) -> Vec<mission_store::StoredEvent> {
    if events.is_empty() {
        return events;
    }

    #[derive(Default)]
    struct ToolPair {
        latest_sequence: i64,
        has_result: bool,
        result_sequence: Option<i64>,
        result_timestamp: Option<String>,
        call_content_bytes: usize,
        result_content_bytes: usize,
    }

    let mut pairs: HashMap<String, ToolPair> = HashMap::new();
    for event in &events {
        if !matches!(event.event_type.as_str(), "tool_call" | "tool_result") {
            continue;
        }
        let Some(tool_call_id) = event.tool_call_id.as_ref() else {
            continue;
        };
        let pair = pairs.entry(tool_call_id.clone()).or_default();
        pair.latest_sequence = pair.latest_sequence.max(event.sequence);
        if event.event_type == "tool_call" {
            pair.call_content_bytes = event.content.len();
        } else {
            pair.has_result = true;
            pair.result_sequence = Some(event.sequence);
            pair.result_timestamp = Some(event.timestamp.clone());
            pair.result_content_bytes = event.content.len();
        }
    }

    let mut projected = Vec::with_capacity(events.len());
    for mut event in events {
        if !matches!(event.event_type.as_str(), "tool_call" | "tool_result") {
            projected.push(event);
            continue;
        }
        let Some(tool_call_id) = event.tool_call_id.clone() else {
            projected.push(event);
            continue;
        };
        if keep_full_tool_call_ids.contains(&tool_call_id) {
            projected.push(event);
            continue;
        }
        // Interactive UI tools (question / AskUserQuestion / ui_*) carry the
        // question payload the dashboard needs to render the item even after
        // it's answered. Stubbing them drops the args, so an answered question
        // would reload as an empty "reply below" prompt. Never stub them or
        // their results, regardless of the recency window.
        if event
            .tool_name
            .as_deref()
            .is_some_and(is_interactive_ui_tool)
        {
            projected.push(event);
            continue;
        }
        if event.event_type == "tool_result" {
            continue;
        }

        if let Some(pair) = pairs.get(&tool_call_id) {
            let persisted = tool_summaries.get(&tool_call_id);
            let has_result = persisted.map_or(pair.has_result, |summary| summary.has_result);
            if !has_result {
                projected.push(event);
                continue;
            }
            event.event_type = "tool_stub".to_string();
            event.content.clear();
            let mut metadata = event.metadata.as_object().cloned().unwrap_or_default();
            metadata.insert("lazy".to_string(), serde_json::json!(true));
            metadata.insert("has_result".to_string(), serde_json::json!(has_result));
            metadata.insert(
                "call_sequence".to_string(),
                serde_json::json!(event.sequence),
            );
            metadata.insert(
                "result_sequence".to_string(),
                serde_json::json!(persisted
                    .and_then(|summary| summary.result_sequence)
                    .or(pair.result_sequence)),
            );
            metadata.insert(
                "result_timestamp".to_string(),
                serde_json::json!(persisted
                    .and_then(|summary| summary.result_timestamp.clone())
                    .or_else(|| pair.result_timestamp.clone())),
            );
            metadata.insert(
                "call_content_bytes".to_string(),
                serde_json::json!(persisted.map_or(pair.call_content_bytes, |summary| {
                    summary.call_content_bytes
                })),
            );
            metadata.insert(
                "result_content_bytes".to_string(),
                serde_json::json!(persisted.map_or(pair.result_content_bytes, |summary| {
                    summary.result_content_bytes
                })),
            );
            event.metadata = serde_json::Value::Object(metadata);
        }
        projected.push(event);
    }

    projected
}

/// Get events for a mission (for debugging/replay).
///
/// Response includes `X-Total-Events` (total count matching the type
/// filter) and `X-Max-Sequence` (highest sequence stored for this
/// mission) headers so the client can decide whether it's caught up
/// without issuing a second request.
pub async fn get_mission_events(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
    axum::extract::Query(query): axum::extract::Query<GetEventsQuery>,
) -> Result<Response, (StatusCode, String)> {
    state.control_metrics.record_events_request();
    let metrics_start = Instant::now();
    let control = control_for_user(&state, &user).await;

    // Check mission exists
    let mission = control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
        .ok_or((StatusCode::NOT_FOUND, "Mission not found".to_string()))?;

    let type_names = event_types_for_query(&query);
    let types: Option<Vec<&str>> = type_names
        .as_ref()
        .map(|t| t.iter().map(String::as_str).collect());

    let events = if let Some(before_seq) = query.before_seq {
        control
            .mission_store
            .get_events_before(mission_id, before_seq, types.as_deref(), query.limit)
            .await
            .map_err(internal_error)?
    } else if let Some(since_seq) = query.since_seq {
        control
            .mission_store
            .get_events_since(mission_id, since_seq, types.as_deref(), query.limit)
            .await
            .map_err(internal_error)?
    } else {
        // No cursor: default to the NEWEST `limit` events (the tail), returned
        // ascending within the page — i.e. behave as `before_seq=MAX`. "Latest
        // activity" is the overwhelmingly common need (dashboards, debugging a
        // live mission), so paging from the oldest row by default is a footgun.
        // Callers that genuinely want a forward replay from the start pass
        // `since_seq=0` explicitly, which is handled above and is unaffected.
        control
            .mission_store
            .get_events_before(mission_id, i64::MAX, types.as_deref(), query.limit)
            .await
            .map_err(internal_error)?
    };
    let mut summary = if should_summarize_events(&mission) {
        summarize_inactive_stream_events(events)
    } else {
        EventSummary::unchanged(events)
    };
    if conversation_profile_enabled(query.profile.as_deref()) {
        let keep_full_tool_call_ids: HashSet<String> = control
            .mission_store
            .get_recent_tool_call_ids(
                mission_id,
                query.trace_tail.unwrap_or(CONVERSATION_PROFILE_TRACE_TAIL),
            )
            .await
            .map_err(internal_error)?
            .into_iter()
            .collect();
        let tool_call_ids = summary
            .events
            .iter()
            .filter_map(|event| event.tool_call_id.clone())
            .collect::<HashSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let tool_summaries = control
            .mission_store
            .get_tool_call_summaries(mission_id, &tool_call_ids)
            .await
            .map_err(internal_error)?;
        summary.events =
            project_conversation_events(summary.events, &keep_full_tool_call_ids, &tool_summaries);
        summary.summarized_count = summary.events.len();
    }

    // Metadata headers let the client decide whether it's caught up
    // without a second round-trip. Failures here are non-fatal — we just
    // skip the header rather than breaking the whole response.
    let total = if query.include_counts {
        control
            .mission_store
            .count_events(mission_id, types.as_deref())
            .await
            .ok()
    } else {
        None
    };
    let max_seq = control
        .mission_store
        .max_event_sequence(mission_id)
        .await
        .ok();

    let payload_bytes = serde_json::to_vec(&summary.events)
        .map(|bytes| bytes.len())
        .unwrap_or(0);
    state.control_metrics.record_events_response(
        metrics_start.elapsed(),
        payload_bytes,
        summary.original_count,
        summary.summarized_count,
    );

    let mut response = Json(summary.events).into_response();
    let headers = response.headers_mut();
    if let Some(total) = total {
        if let Ok(v) = header::HeaderValue::from_str(&total.to_string()) {
            headers.insert("X-Total-Events", v);
        }
    }
    if let Some(max_seq) = max_seq {
        if let Ok(v) = header::HeaderValue::from_str(&max_seq.to_string()) {
            headers.insert("X-Max-Sequence", v);
        }
    }
    if summary.summarized_count < summary.original_count {
        if let Ok(v) = header::HeaderValue::from_str(&summary.original_count.to_string()) {
            headers.insert("X-Original-Event-Count", v);
        }
        if let Ok(v) = header::HeaderValue::from_str(&summary.summarized_count.to_string()) {
            headers.insert("X-Summarized-Event-Count", v);
        }
    }
    // CORS exposure so browsers can read these headers from JS.
    headers.insert(
        header::ACCESS_CONTROL_EXPOSE_HEADERS,
        header::HeaderValue::from_static(
            "X-Total-Events, X-Max-Sequence, X-Original-Event-Count, X-Summarized-Event-Count",
        ),
    );

    Ok(response)
}

#[derive(Debug, Deserialize)]
pub struct AlertsFeedQuery {
    /// Comma-separated mission statuses to keep (e.g. `awaiting_user,failed`).
    pub statuses: Option<String>,
    /// Timestamp cursor: return alerts strictly older than this.
    pub before: Option<String>,
    pub limit: Option<usize>,
}

#[derive(Debug, Serialize)]
pub struct AlertFeedDelivery {
    pub channel: &'static str,
    pub status: String,
    pub sent_at: Option<String>,
    pub acknowledged_at: Option<String>,
    pub last_error: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct AlertFeedEntry {
    pub mission_id: Uuid,
    pub status: String,
    pub summary: String,
    pub timestamp: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub mission: Option<mission_store::MissionSummary>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub delivery: Option<AlertFeedDelivery>,
}

#[derive(Debug, Serialize)]
pub struct AlertsFeedResponse {
    pub alerts: Vec<AlertFeedEntry>,
    pub next_cursor: Option<String>,
}

/// Cross-mission feed of status-change alerts, newest first. Source of truth
/// is `mission_events` (`mission_status_changed`), decorated best-effort with
/// mission summaries and Telegram delivery state.
pub async fn get_alerts_feed(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    axum::extract::Query(query): axum::extract::Query<AlertsFeedQuery>,
) -> Result<Json<AlertsFeedResponse>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    let limit = query.limit.unwrap_or(50).clamp(1, 200);

    let events = control
        .mission_store
        .get_status_events_global(query.before.as_deref(), limit)
        .await
        .map_err(internal_error)?;

    // Cursor comes from the raw (unfiltered) page so pagination never stalls
    // even when a status filter empties a page.
    let next_cursor = if events.len() == limit {
        events.last().map(|e| e.timestamp.clone())
    } else {
        None
    };

    let wanted: Option<Vec<String>> = query.statuses.as_deref().map(|s| {
        s.split(',')
            .map(|p| p.trim().to_string())
            .filter(|p| !p.is_empty())
            .collect()
    });

    let mut entries: Vec<AlertFeedEntry> = events
        .into_iter()
        .filter_map(|e| {
            let status = e.metadata.get("status")?.as_str()?.to_string();
            if let Some(wanted) = &wanted {
                if !wanted.contains(&status) {
                    return None;
                }
            }
            Some(AlertFeedEntry {
                mission_id: e.mission_id,
                status,
                summary: e.content,
                timestamp: e.timestamp,
                mission: None,
                delivery: None,
            })
        })
        .collect();

    let mission_ids: Vec<Uuid> = {
        let mut ids: Vec<Uuid> = entries.iter().map(|e| e.mission_id).collect();
        ids.sort();
        ids.dedup();
        ids
    };

    let summaries = control
        .mission_store
        .get_mission_summaries(&mission_ids)
        .await
        .map_err(internal_error)?;
    let telegram_alerts = control
        .mission_store
        .list_telegram_alerts_for_missions(&mission_ids)
        .await
        .unwrap_or_default();

    for entry in &mut entries {
        entry.mission = summaries.get(&entry.mission_id).cloned();
        // Loose join: telegram_alerts has no FK to the event row; match the
        // alert class (`mission_<status>` before any `:` suffix). The list is
        // ordered created_at DESC, so the first match is the most recent.
        let class = format!("mission_{}", entry.status);
        entry.delivery = telegram_alerts
            .iter()
            .find(|a| {
                a.mission_id == Some(entry.mission_id)
                    && a.event_kind.split(':').next().unwrap_or(&a.event_kind) == class
            })
            .map(|a| AlertFeedDelivery {
                channel: "telegram",
                status: a.status.clone(),
                sent_at: a.sent_at.clone(),
                acknowledged_at: a.acknowledged_at.clone(),
                last_error: a.last_error.clone(),
            });
    }

    Ok(Json(AlertsFeedResponse {
        alerts: entries,
        next_cursor,
    }))
}

pub async fn get_mission_tool_call_events(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path((mission_id, tool_call_id)): Path<(Uuid, String)>,
) -> Result<Json<Vec<mission_store::StoredEvent>>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    let mission_exists = control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?;
    if mission_exists.is_none() {
        return Err((StatusCode::NOT_FOUND, "Mission not found".to_string()));
    }

    let events = control
        .mission_store
        .get_events_for_tool_call(mission_id, &tool_call_id)
        .await
        .map_err(internal_error)?;
    if events.is_empty() {
        return Err((StatusCode::NOT_FOUND, "Tool call not found".to_string()));
    }
    Ok(Json(events))
}

const TRANSCRIPT_EVENT_TYPES: &[&str] = &[
    "user_message",
    "assistant_message",
    "assistant_message_canonical",
];
const TRACE_EVENT_TYPES: &[&str] = &[
    "thinking",
    "tool_call",
    "tool_result",
    "text_delta",
    "text_op",
    "error",
    "phase",
    "status",
];
const HISTORY_EVENT_TYPES: &[&str] = &[
    "user_message",
    "assistant_message",
    "assistant_message_canonical",
    "tool_call",
    "tool_result",
    "text_delta",
    "text_op",
    "thinking",
    "goal_iteration",
    "goal_status",
];
/// Conversation message types used to anchor the snapshot tail. The snapshot
/// guarantees the most recent `SNAPSHOT_CONVERSATIONAL_MESSAGES` of these are
/// loaded (plus every tool call between them), so a tool-heavy mission opens
/// on the actual conversation instead of a wall of tool output.
const SNAPSHOT_ANCHOR_TYPES: &[&str] = &[
    "user_message",
    "assistant_message",
    "assistant_message_canonical",
];
/// How many recent conversation messages the snapshot guarantees.
const SNAPSHOT_CONVERSATIONAL_MESSAGES: usize = 10;
/// Hard cap on snapshot size. Bounds payload if the recent conversation
/// happens to span an unusually large number of tool calls; the rest stays
/// reachable via backwards pagination ("Load older messages").
const SNAPSHOT_MAX_EVENTS: usize = 1500;

fn event_types_for_query(query: &GetEventsQuery) -> Option<Vec<String>> {
    if let Some(types) = query.types.as_ref() {
        return Some(
            types
                .split(',')
                .map(str::trim)
                .filter(|t| !t.is_empty())
                .map(ToString::to_string)
                .collect(),
        );
    }

    match query.view.as_deref() {
        Some("transcript") => Some(
            TRANSCRIPT_EVENT_TYPES
                .iter()
                .map(|s| s.to_string())
                .collect(),
        ),
        Some("trace") => Some(TRACE_EVENT_TYPES.iter().map(|s| s.to_string()).collect()),
        Some("history") => Some(HISTORY_EVENT_TYPES.iter().map(|s| s.to_string()).collect()),
        Some("all") | None => None,
        Some(_) => None,
    }
}

fn event_visibility(event_type: &str) -> &'static str {
    match event_type {
        "user_message"
        | "assistant_message"
        | "assistant_message_canonical"
        | "mission_status_changed" => "transcript",
        "thinking" | "tool_call" | "tool_result" | "text_delta" | "text_op" | "phase"
        | "status" | "error" => "trace",
        _ => "debug",
    }
}

#[derive(Debug, Serialize)]
pub struct MissionSnapshotResponse {
    pub mission: Mission,
    pub execution: Option<serde_json::Value>,
    pub events: Vec<mission_store::StoredEvent>,
    pub event_counts: HashMap<String, usize>,
    pub counts: HashMap<String, usize>,
    pub visibility_counts: HashMap<String, usize>,
    pub total_events: usize,
    pub latest_sequence: i64,
    pub child_missions: Vec<Mission>,
    pub running: Option<super::mission_runner::RunningMissionInfo>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SnapshotQuery {
    #[serde(default)]
    pub profile: Option<String>,
    #[serde(default)]
    pub trace_tail: Option<usize>,
}

/// Single first-paint payload for clients. It returns the latest visible event
/// tail plus metadata needed to avoid the old transcript-then-trace redraw.
pub async fn get_mission_snapshot(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
    axum::extract::Query(query): axum::extract::Query<SnapshotQuery>,
) -> Result<Json<MissionSnapshotResponse>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    let mut mission = control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
        .ok_or((StatusCode::NOT_FOUND, "Mission not found".to_string()))?;

    if let Some(workspace) = state.workspaces.get(mission.workspace_id).await {
        mission.workspace_name = Some(workspace.name);
    }

    // Conversation-anchored snapshot tail: load everything from the
    // Nth-most-recent conversation message to the head, so the recent
    // back-and-forth is always present even when tool calls dominate the
    // raw event stream. Falls back to a plain recent-events tail when the
    // mission has fewer than N conversation messages, or (degenerate) when
    // the anchored span would exceed the hard cap.
    let anchor_seq = control
        .mission_store
        .nth_recent_event_sequence(
            mission_id,
            SNAPSHOT_ANCHOR_TYPES,
            SNAPSHOT_CONVERSATIONAL_MESSAGES,
        )
        .await
        .map_err(internal_error)?;
    let events = match anchor_seq {
        Some(anchor) => {
            // `get_events_since` is `sequence > since`, so subtract one to
            // include the anchor itself. Fetch one past the cap to detect
            // overflow without a separate count query.
            let anchored = control
                .mission_store
                .get_events_since(
                    mission_id,
                    anchor.saturating_sub(1),
                    Some(HISTORY_EVENT_TYPES),
                    Some(SNAPSHOT_MAX_EVENTS + 1),
                )
                .await
                .map_err(internal_error)?;
            if anchored.len() > SNAPSHOT_MAX_EVENTS {
                // The recent conversation spans more than the cap of tool
                // calls. `get_events_since` returned the OLDEST events after
                // the anchor (ASC), which would miss the newest — so fall
                // back to the most-recent capped tail instead.
                control
                    .mission_store
                    .get_events_before(
                        mission_id,
                        i64::MAX,
                        Some(HISTORY_EVENT_TYPES),
                        Some(SNAPSHOT_MAX_EVENTS),
                    )
                    .await
                    .map_err(internal_error)?
            } else {
                anchored
            }
        }
        None => control
            .mission_store
            .get_events_before(
                mission_id,
                i64::MAX,
                Some(HISTORY_EVENT_TYPES),
                Some(SNAPSHOT_MAX_EVENTS),
            )
            .await
            .map_err(internal_error)?,
    };
    let mut summary = if should_summarize_events(&mission) {
        summarize_inactive_stream_events(events)
    } else {
        EventSummary::unchanged(events)
    };
    if conversation_profile_enabled(query.profile.as_deref()) {
        let keep_full_tool_call_ids: HashSet<String> = control
            .mission_store
            .get_recent_tool_call_ids(
                mission_id,
                query.trace_tail.unwrap_or(CONVERSATION_PROFILE_TRACE_TAIL),
            )
            .await
            .map_err(internal_error)?
            .into_iter()
            .collect();
        let tool_call_ids = summary
            .events
            .iter()
            .filter_map(|event| event.tool_call_id.clone())
            .collect::<HashSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let tool_summaries = control
            .mission_store
            .get_tool_call_summaries(mission_id, &tool_call_ids)
            .await
            .map_err(internal_error)?;
        summary.events =
            project_conversation_events(summary.events, &keep_full_tool_call_ids, &tool_summaries);
        summary.summarized_count = summary.events.len();
    }
    let event_counts = control
        .mission_store
        .count_events_by_type(mission_id, Some(HISTORY_EVENT_TYPES))
        .await
        .map_err(internal_error)?;
    let total = event_counts.values().copied().sum();
    let mut visibility_counts: HashMap<String, usize> = HashMap::new();
    for (event_type, count) in &event_counts {
        *visibility_counts
            .entry(event_visibility(event_type).to_string())
            .or_insert(0) += *count;
    }
    let latest_sequence = control
        .mission_store
        .max_event_sequence(mission_id)
        .await
        .map_err(internal_error)?;
    let child_missions = control
        .mission_store
        .get_child_missions(mission_id)
        .await
        .unwrap_or_default();
    let running = get_running_missions(&control)
        .await?
        .into_iter()
        .find(|info| info.mission_id == mission_id);
    let execution = control
        .mission_store
        .get_active_mission_run(mission_id)
        .await
        .map_err(internal_error)?
        .as_ref()
        .map(|run| mission_execution_projection(run, mission.status));

    Ok(Json(MissionSnapshotResponse {
        mission,
        execution,
        events: summary.events,
        counts: event_counts.clone(),
        event_counts,
        visibility_counts,
        total_events: total,
        latest_sequence,
        child_missions,
        running,
    }))
}

// ==================== Parallel Mission Endpoints ====================

/// List currently running missions.
pub async fn list_running_missions(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
) -> Result<Json<Vec<super::mission_runner::RunningMissionInfo>>, (StatusCode, String)> {
    state.control_metrics.record_running_request();
    let control = control_for_user(&state, &user).await;
    let running = get_running_missions(&control).await?;
    Ok(Json(running))
}

/// P0-#3: in-process metrics snapshot for perf validation.
pub async fn get_control_metrics(
    State(state): State<Arc<AppState>>,
    Extension(_user): Extension<AuthUser>,
) -> Json<super::control_metrics::MetricsSnapshot> {
    Json(state.control_metrics.snapshot())
}

/// P5-#25: client telemetry sink. Dashboard POSTs here when its 5-second
/// longtask budget breaches the 2s threshold so we can correlate freezes
/// with mission shape (event count, heap).
pub async fn post_control_telemetry_perf(
    State(state): State<Arc<AppState>>,
    Extension(_user): Extension<AuthUser>,
    Json(report): Json<super::control_metrics::HealthReport>,
) -> StatusCode {
    state.control_metrics.record_health_report(report);
    StatusCode::ACCEPTED
}

/// Request body for starting a mission in parallel.
#[derive(Debug, Deserialize)]
pub struct StartParallelRequest {
    pub content: String,
}

/// Start a mission in parallel (if capacity allows).
pub async fn start_mission_parallel(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
    Json(req): Json<StartParallelRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let (tx, rx) = oneshot::channel();

    let control = control_for_user(&state, &user).await;
    control
        .cmd_tx
        .send(ControlCommand::StartParallel {
            mission_id,
            content: req.content,
            respond: tx,
        })
        .await
        .map_err(session_unavailable)?;

    rx.await
        .map_err(recv_failed)?
        .map(|_| Json(serde_json::json!({ "ok": true, "mission_id": mission_id })))
        .map_err(|e| (StatusCode::CONFLICT, e))
}

/// Cancel a specific mission.
pub async fn cancel_mission(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let (tx, rx) = oneshot::channel();

    let control = control_for_user(&state, &user).await;
    control
        .cmd_tx
        .send(ControlCommand::CancelMission {
            mission_id,
            min_idle: None,
            respond: tx,
        })
        .await
        .map_err(session_unavailable)?;

    rx.await
        .map_err(recv_failed)?
        .map(|_| Json(serde_json::json!({ "ok": true, "cancelled": mission_id })))
        .map_err(|e| (StatusCode::NOT_FOUND, e))
}

/// Settle a durable run after the control actor has proved that no live main
/// or parallel runner owns it. This covers parked remote waits left behind by
/// a completed harness turn. Returning an idempotent cancel response without
/// closing this row would permanently block the next generation.
async fn finish_detached_run_for_cancel(
    mission_store: &Arc<dyn MissionStore>,
    mission_id: Uuid,
) -> Result<bool, String> {
    let Some(run) = mission_store.get_active_mission_run(mission_id).await? else {
        return Ok(false);
    };
    mission_store
        .heartbeat_mission_run(
            run.run_id,
            run.generation,
            MissionExecutionState::Stopping,
            None,
        )
        .await?;
    mission_store
        .finish_mission_run(
            run.run_id,
            run.generation,
            Some("operator_cancelled_detached_run"),
        )
        .await?;
    Ok(true)
}

/// Optional body for the pause endpoint (FLEET-004). Carries attribution only.
#[derive(Debug, Default, Deserialize)]
pub struct PauseMissionRequest {
    /// Optional attribution override (e.g. `"system:fleet-watcher"`).
    #[serde(default)]
    pub actor: Option<String>,
}

/// Pause a mission (FLEET-004). Sets the mission to `Paused`, a non-terminal
/// state the dispatcher deliberately skips when selecting the next runnable
/// mission. Resume via `POST /missions/:id/resume`, which transitions a
/// `Paused` mission back to `Pending` so the dispatcher re-queues it.
///
/// Rejects missions that are already terminal (nothing to pause) or already
/// paused (no-op kept explicit for the operator).
pub async fn pause_mission(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
    body: Option<Json<PauseMissionRequest>>,
) -> Result<Json<Mission>, (StatusCode, String)> {
    let actor = resolve_actor(body.and_then(|b| b.0.actor), &user);
    let control = control_for_user(&state, &user).await;
    let mission = control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                format!("Mission {} not found", mission_id),
            )
        })?;

    if mission.status == MissionStatus::Paused {
        return Err((
            StatusCode::CONFLICT,
            "Mission is already paused".to_string(),
        ));
    }
    if mission_status_is_terminal(mission.status) {
        return Err((
            StatusCode::CONFLICT,
            format!(
                "Cannot pause a terminal mission (status: {})",
                mission.status
            ),
        ));
    }

    // Route through the control loop so any in-flight runner is actually
    // stopped before the mission is parked. A bare store update would leave the
    // active turn executing and let its completion overwrite `Paused`.
    let (tx, rx) = oneshot::channel();
    control
        .cmd_tx
        .send(ControlCommand::PauseMission {
            mission_id,
            respond: tx,
        })
        .await
        .map_err(session_unavailable)?;
    rx.await
        .map_err(recv_failed)?
        .map_err(|e| (StatusCode::CONFLICT, e))?;
    tracing::info!(mission_id = %mission_id, actor = %actor, "FLEET-004 mission paused");

    let updated = control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                format!("Mission {} not found", mission_id),
            )
        })?;
    Ok(Json(updated))
}

/// Resolve the acting principal for a FLEET control action. An explicit
/// `actor` override (e.g. `"system:fleet-watcher"`) wins; otherwise we attribute
/// it to the authenticated user. Recorded in structured logs so a post-mortem
/// can answer "who paused/cloned/resumed this mission?".
fn resolve_actor(explicit: Option<String>, user: &AuthUser) -> String {
    explicit
        .map(|a| a.trim().to_string())
        .filter(|a| !a.is_empty())
        .unwrap_or_else(|| {
            let who = if user.username.is_empty() {
                &user.id
            } else {
                &user.username
            };
            format!("user:{}", who)
        })
}

/// Overrides accepted when cloning a mission (FLEET-002). Any field left unset
/// inherits from the source mission.
#[derive(Debug, Default, Deserialize)]
pub struct CloneMissionRequest {
    #[serde(default)]
    pub title: Option<String>,
    #[serde(default)]
    pub backend: Option<String>,
    #[serde(default)]
    pub model_effort: Option<String>,
    #[serde(default)]
    pub model_override: Option<String>,
    /// When true, copy the source mission's conversation history into the clone
    /// (retry-with-context). Default false — the clone starts fresh.
    #[serde(default)]
    pub clone_messages: bool,
    /// Optional parent to record on the clone for lineage tracing in the UI.
    /// Left unset, the clone has no parent (independent mission).
    #[serde(default)]
    pub parent_mission_id: Option<Uuid>,
    /// Optional attribution override (e.g. `"system:fleet-watcher"`).
    #[serde(default)]
    pub actor: Option<String>,
}

/// Clone an existing mission's configuration into a fresh `Pending` mission
/// (FLEET-002). Copies title, workspace, agent, config profile, working
/// directory and model settings; the optional body overrides
/// title/backend/model_effort/model_override. Conversation history is **not**
/// copied — the clone starts fresh. Reuses the standard create path so all
/// backend/agent/model validation applies identically.
pub async fn clone_mission(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
    body: Option<Json<CloneMissionRequest>>,
) -> Result<Json<Mission>, (StatusCode, String)> {
    let overrides = body.map(|b| b.0).unwrap_or_default();
    let actor = resolve_actor(overrides.actor.clone(), &user);
    let clone_messages = overrides.clone_messages;
    let parent_mission_id = overrides.parent_mission_id;

    let control = control_for_user(&state, &user).await;
    let source = control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                format!("Mission {} not found", mission_id),
            )
        })?;

    let req = CreateMissionRequest {
        title: overrides.title.or_else(|| source.title.clone()),
        workspace_id: Some(source.workspace_id),
        agent: source.agent.clone(),
        model_override: overrides
            .model_override
            .or_else(|| source.model_override.clone()),
        model_effort: overrides
            .model_effort
            .or_else(|| source.model_effort.clone()),
        fast_mode: source.fast_mode,
        config_profile: source.config_profile.clone(),
        backend: overrides.backend.or_else(|| Some(source.backend.clone())),
        parent_mission_id,
        working_directory: source.working_directory.clone(),
        priority: None,
        not_before: None,
        deadline: None,
        // Inherit project tagging from the source mission so clones stay
        // grouped under the same project/track/intent.
        project: source.project.project.clone(),
        track: source.project.track.clone(),
        intent: source.project.intent.clone(),
        github_pr: source.project.github_pr.clone(),
        writer: None,
        tags: if source.project.tags.is_empty() {
            None
        } else {
            Some(source.project.tags.clone())
        },
        desired_state: source.project.desired_state.clone(),
        next_check_at: source.project.next_check_at.clone(),
        prompt: None,
        remote_node_id: None,
        remote_requirements: None,
        remote_command: None,
        remote_async: None,
        estimated_disk_gib: None,
        // A clone is the same work retried, so it belongs to the same
        // conversation. Dropping the origin here orphaned the retry: it
        // vanished from the worker strip of the session that asked for it.
        origin: source.origin.clone(),
        origin_session_id: source.origin_session_id.clone(),
        extra: Default::default(),
    };

    let (_headers, cloned) = create_mission(State(state), Extension(user), Some(Json(req))).await?;
    let clone_id = cloned.0.id;

    // Optionally seed the clone with the source's conversation history
    // (retry-with-context). `control` still holds the store handle after the
    // create above moved `state`.
    if clone_messages && !source.history.is_empty() {
        control
            .mission_store
            .update_mission_history(clone_id, &source.history)
            .await
            .map_err(internal_error)?;
    }

    tracing::info!(
        source_mission = %mission_id,
        clone_mission = %clone_id,
        actor = %actor,
        clone_messages,
        parent = ?parent_mission_id,
        "FLEET-002 mission cloned"
    );

    Ok(cloned)
}

/// Request body for resuming a mission
#[derive(Debug, Deserialize, Default)]
pub struct ResumeMissionRequest {
    /// If true, clean the mission's work directory before resuming
    #[serde(default)]
    pub clean_workspace: bool,
    /// If true, do not send the automatic resume message.
    /// Useful when the user is about to send their own custom message.
    #[serde(default)]
    pub skip_message: bool,
    /// Optional attribution override (e.g. `"system:fleet-watcher"`).
    #[serde(default)]
    pub actor: Option<String>,
}

/// Resume an interrupted mission.
/// This reconstructs context from history and work directory, then restarts execution.
pub async fn resume_mission(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
    body: Option<Json<ResumeMissionRequest>>,
) -> Result<Json<Mission>, (StatusCode, String)> {
    let (clean_workspace, skip_message, actor_override) = body
        .map(|b| {
            let r = b.0;
            (r.clean_workspace, r.skip_message, r.actor)
        })
        .unwrap_or((false, false, None));
    let actor = resolve_actor(actor_override, &user);

    let control = control_for_user(&state, &user).await;
    tracing::info!(mission_id = %mission_id, actor = %actor, "FLEET-004 mission resume requested");

    let outcome: Result<Mission, (StatusCode, String)> = async {
        let (tx, rx) = oneshot::channel();
        control
            .cmd_tx
            .send(ControlCommand::ResumeMission {
                mission_id,
                clean_workspace,
                skip_message,
                respond: tx,
            })
            .await
            .map_err(session_unavailable)?;
        rx.await
            .map_err(recv_failed)?
            .map_err(|e| (StatusCode::BAD_REQUEST, e))
    }
    .await;

    outcome.map(Json)
}

/// Delete a mission by ID.
/// Only allows deleting missions that are not currently running.
pub async fn delete_mission(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    let running = get_running_missions(&control).await?;

    let deleted_workspace_dirs = cleanup_mission_workspace_dirs_for_delete(
        &control.mission_store,
        &state.workspaces,
        mission_id,
        &running,
    )
    .await?;

    let deleted_ids =
        delete_mission_with_children(&control.mission_store, mission_id, &running).await?;

    for id in &deleted_ids {
        clear_mission_metadata_refresh_state(*id);
    }

    let deleted_workspace_dir_count = deleted_workspace_dirs.len();
    Ok(Json(serde_json::json!({
        "ok": true,
        "deleted": mission_id,
        "deleted_ids": deleted_ids,
        "deleted_count": deleted_ids.len(),
        "deleted_workspace_dirs": deleted_workspace_dirs,
        "deleted_workspace_dir_count": deleted_workspace_dir_count
    })))
}

async fn collect_child_mission_ids(
    mission_store: &Arc<dyn MissionStore>,
    parent_id: Uuid,
) -> Result<Vec<Uuid>, (StatusCode, String)> {
    let mut visited = HashSet::new();
    let mut stack = vec![parent_id];
    let mut child_ids = Vec::new();

    while let Some(id) = stack.pop() {
        let children = mission_store
            .get_child_missions(id)
            .await
            .map_err(internal_error)?;

        for child in children {
            if visited.insert(child.id) {
                child_ids.push(child.id);
                stack.push(child.id);
            }
        }
    }

    Ok(child_ids)
}

async fn delete_mission_with_children(
    mission_store: &Arc<dyn MissionStore>,
    mission_id: Uuid,
    running: &[super::mission_runner::RunningMissionInfo],
) -> Result<Vec<Uuid>, (StatusCode, String)> {
    let Some(target) = mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
    else {
        return Err((StatusCode::NOT_FOUND, "Mission not found".to_string()));
    };

    // FLEET-004: a Paused mission is deliberately parked for later resume —
    // deleting it would silently discard work the operator chose to keep. Require
    // an explicit resume-or-cancel first (mirrors the pause endpoint's 409s).
    if target.status == MissionStatus::Paused {
        return Err((
            StatusCode::CONFLICT,
            format!(
                "Cannot delete a paused mission ({}). Resume or cancel it first.",
                mission_id
            ),
        ));
    }

    let child_ids = collect_child_mission_ids(mission_store, mission_id).await?;
    let mut ids_to_delete = Vec::with_capacity(child_ids.len() + 1);
    ids_to_delete.push(mission_id);
    ids_to_delete.extend(child_ids.iter().copied());

    if let Some(running_mission) = running
        .iter()
        .find(|m| ids_to_delete.contains(&m.mission_id))
    {
        return Err((
            StatusCode::CONFLICT,
            format!(
                "Cannot delete a running mission or worker ({}). Cancel it first.",
                running_mission.mission_id
            ),
        ));
    }

    for child_id in child_ids.iter().rev() {
        mission_store
            .delete_mission(*child_id)
            .await
            .map_err(internal_error)?;
    }

    let deleted = mission_store
        .delete_mission(mission_id)
        .await
        .map_err(internal_error)?;
    if !deleted {
        return Err((StatusCode::NOT_FOUND, "Mission not found".to_string()));
    }

    Ok(ids_to_delete)
}

async fn cleanup_mission_workspace_dirs_for_delete(
    mission_store: &Arc<dyn MissionStore>,
    workspaces: &workspace::SharedWorkspaceStore,
    mission_id: Uuid,
    running: &[super::mission_runner::RunningMissionInfo],
) -> Result<Vec<String>, (StatusCode, String)> {
    let Some(root_mission) = mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
    else {
        return Err((StatusCode::NOT_FOUND, "Mission not found".to_string()));
    };

    let child_ids = collect_child_mission_ids(mission_store, mission_id).await?;
    let mut ids_to_delete = Vec::with_capacity(child_ids.len() + 1);
    ids_to_delete.push(mission_id);
    ids_to_delete.extend(child_ids.iter().copied());

    if let Some(running_mission) = running
        .iter()
        .find(|m| ids_to_delete.contains(&m.mission_id))
    {
        return Err((
            StatusCode::CONFLICT,
            format!(
                "Cannot delete a running mission or worker ({}). Cancel it first.",
                running_mission.mission_id
            ),
        ));
    }

    let mut missions = Vec::with_capacity(ids_to_delete.len());
    missions.push(root_mission);
    for child_id in child_ids {
        if let Some(child) = mission_store
            .get_mission(child_id)
            .await
            .map_err(internal_error)?
        {
            missions.push(child);
        }
    }

    let mut deleted_dirs = Vec::new();
    for mission in missions {
        let Some(ws) = workspaces.get(mission.workspace_id).await else {
            continue;
        };
        let dir = workspace::mission_workspace_dir_for_root(&ws.path, mission.id);
        if !dir.exists() {
            continue;
        }
        match tokio::fs::remove_dir_all(&dir).await {
            Ok(()) => {}
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => continue,
            Err(err) => {
                return Err((
                    StatusCode::INTERNAL_SERVER_ERROR,
                    format!(
                        "Failed to delete mission workspace directory {}: {}",
                        dir.display(),
                        err
                    ),
                ));
            }
        }
        tracing::info!(
            mission_id = %mission.id,
            workspace_id = %mission.workspace_id,
            path = %dir.display(),
            "removed mission workspace directory during explicit delete",
        );
        deleted_dirs.push(dir.to_string_lossy().to_string());
    }

    Ok(deleted_dirs)
}

/// Delete all empty "Untitled" missions.
/// Returns the count of deleted missions.
/// Note: This excludes any currently running missions to prevent data loss.
pub async fn cleanup_empty_missions(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    let running = get_running_missions(&control).await?;
    let running_ids: Vec<Uuid> = running.iter().map(|m| m.mission_id).collect();

    let count = control
        .mission_store
        .delete_empty_untitled_missions_excluding(&running_ids)
        .await
        .map_err(internal_error)?;

    if count > 0 {
        clear_stale_mission_metadata_refresh_state(&control.mission_store).await;
    }

    Ok(Json(serde_json::json!({
        "ok": true,
        "deleted_count": count
    })))
}

/// Stream control session events via SSE.
#[derive(Debug, Deserialize)]
pub struct StreamQuery {
    /// Optional mission filter. When set, the server only emits events whose
    /// `mission_id` matches (plus the connection-scoped `status` /
    /// `stream_lagged` events the dashboard relies on). Cuts cross-mission
    /// noise to zero for a focused tab. Omit the param to receive every
    /// event the user can see (used by the mission list / debug overlay).
    #[serde(default)]
    pub mission: Option<Uuid>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum ControlWsClientMessage {
    Resume { since_seq: i64 },
}

#[derive(Debug, Serialize)]
struct ControlWsHeartbeat {
    seq: i64,
}

fn suffix_prefix_overlap_len(existing: &str, incoming: &str) -> usize {
    let max_overlap = existing.chars().count().min(incoming.chars().count());
    for overlap_chars in (1..=max_overlap).rev() {
        let existing_start = existing
            .char_indices()
            .nth(existing.chars().count() - overlap_chars)
            .map(|(idx, _)| idx)
            .unwrap_or(0);
        let incoming_end = incoming
            .char_indices()
            .nth(overlap_chars)
            .map(|(idx, _)| idx)
            .unwrap_or(incoming.len());
        if existing[existing_start..] == incoming[..incoming_end] {
            return incoming_end;
        }
    }
    0
}

fn merge_text_stream_fragment(buffer: &mut String, fragment: &str) {
    if fragment.is_empty() {
        return;
    }
    if buffer.is_empty() || fragment.starts_with(buffer.as_str()) {
        *buffer = fragment.to_string();
        return;
    }
    if buffer.starts_with(fragment) {
        return;
    }

    let overlap = suffix_prefix_overlap_len(buffer, fragment);
    buffer.push_str(&fragment[overlap..]);
}

fn text_op_events_for_stream(
    ev: AgentEvent,
    text_buffers: &mut HashMap<Uuid, String>,
) -> Vec<AgentEvent> {
    match ev {
        AgentEvent::TextDelta {
            content,
            mission_id: Some(mission_id),
        } => {
            let previous = text_buffers.entry(mission_id).or_default();
            let previous_len = previous.chars().count();
            let mut next = previous.clone();
            merge_text_stream_fragment(&mut next, &content);
            let ops = if previous.is_empty() {
                vec![TextOp::Insert {
                    pos: 0,
                    text: next.clone(),
                }]
            } else {
                vec![TextOp::Replace {
                    range: (0, previous_len),
                    text: next.clone(),
                }]
            };
            *previous = next;
            vec![AgentEvent::TextOp {
                mission_id,
                bubble_id: "text_delta_latest".to_string(),
                ops,
            }]
        }
        AgentEvent::AssistantMessage {
            mission_id: Some(mission_id),
            ..
        } if text_buffers.remove(&mission_id).is_some() => {
            vec![
                AgentEvent::TextOp {
                    mission_id,
                    bubble_id: "text_delta_latest".to_string(),
                    ops: vec![TextOp::Finalize],
                },
                ev,
            ]
        }
        _ => vec![ev],
    }
}

fn stored_event_to_agent_event(event: &mission_store::StoredEvent) -> Option<AgentEvent> {
    let mission_id = Some(event.mission_id);
    match event.event_type.as_str() {
        "user_message" => Some(AgentEvent::UserMessage {
            id: event
                .event_id
                .as_deref()
                .and_then(|id| Uuid::parse_str(id).ok())
                .unwrap_or_else(Uuid::new_v4),
            content: event.content.clone(),
            queued: false,
            mission_id,
            source: event
                .metadata
                .get("source")
                .and_then(|v| v.as_str())
                .map(str::to_string),
        }),
        "assistant_message" => {
            let meta = event.metadata.as_object();
            Some(AgentEvent::AssistantMessage {
                id: event
                    .event_id
                    .as_deref()
                    .and_then(|id| Uuid::parse_str(id).ok())
                    .unwrap_or_else(Uuid::new_v4),
                content: event.content.clone(),
                success: meta
                    .and_then(|m| m.get("success"))
                    .and_then(|v| v.as_bool())
                    .unwrap_or(true),
                cost_cents: meta
                    .and_then(|m| m.get("cost_cents"))
                    .and_then(|v| v.as_u64())
                    .unwrap_or(0),
                cost_source: crate::agents::CostSource::Unknown,
                usage: None,
                model: meta
                    .and_then(|m| m.get("model"))
                    .and_then(|v| v.as_str())
                    .map(ToString::to_string),
                model_normalized: meta
                    .and_then(|m| m.get("model_normalized"))
                    .and_then(|v| v.as_str())
                    .map(ToString::to_string),
                mission_id,
                shared_files: None,
                resumable: meta
                    .and_then(|m| m.get("resumable"))
                    .and_then(|v| v.as_bool())
                    .unwrap_or(false),
                completion_evidence: meta
                    .and_then(|m| m.get("completion_evidence"))
                    .and_then(|v| serde_json::from_value(v.clone()).ok()),
            })
        }
        "thinking" => Some(AgentEvent::Thinking {
            content: event.content.clone(),
            done: event
                .metadata
                .as_object()
                .and_then(|m| m.get("done"))
                .and_then(|v| v.as_bool())
                .unwrap_or(false),
            mission_id,
        }),
        "text_delta" => Some(AgentEvent::TextDelta {
            content: event.content.clone(),
            mission_id,
        }),
        "text_op" => Some(AgentEvent::TextOp {
            mission_id: event.mission_id,
            bubble_id: event
                .metadata
                .as_object()
                .and_then(|m| m.get("bubble_id"))
                .and_then(|v| v.as_str())
                .map(ToString::to_string)
                .or_else(|| event.event_id.clone())
                .unwrap_or_else(|| format!("event-{}", event.id)),
            ops: serde_json::from_str(&event.content).unwrap_or_default(),
        }),
        "assistant_message_canonical" => Some(AgentEvent::AssistantMessage {
            id: event
                .event_id
                .as_deref()
                .and_then(|id| Uuid::parse_str(id).ok())
                .unwrap_or_else(Uuid::new_v4),
            content: event.content.clone(),
            success: true,
            cost_cents: 0,
            cost_source: crate::agents::CostSource::Unknown,
            usage: None,
            model: None,
            model_normalized: None,
            mission_id,
            shared_files: None,
            resumable: false,
            completion_evidence: None,
        }),
        "tool_call" => Some(AgentEvent::ToolCall {
            tool_call_id: event
                .tool_call_id
                .clone()
                .unwrap_or_else(|| format!("event-{}", event.id)),
            name: event
                .tool_name
                .clone()
                .unwrap_or_else(|| "unknown".to_string()),
            args: serde_json::from_str(&event.content).unwrap_or(serde_json::Value::Null),
            mission_id,
        }),
        "tool_result" => Some(AgentEvent::ToolResult {
            tool_call_id: event.tool_call_id.clone().unwrap_or_default(),
            name: event
                .tool_name
                .clone()
                .unwrap_or_else(|| "unknown".to_string()),
            result: serde_json::from_str(&event.content)
                .unwrap_or_else(|_| serde_json::Value::String(event.content.clone())),
            mission_id,
        }),
        "error" => Some(AgentEvent::Error {
            message: event.content.clone(),
            mission_id,
            resumable: event
                .metadata
                .as_object()
                .and_then(|m| m.get("resumable"))
                .and_then(|v| v.as_bool())
                .unwrap_or(false),
        }),
        "mission_status_changed" => {
            let status = event
                .metadata
                .as_object()
                .and_then(|m| m.get("status"))
                .and_then(|v| v.as_str())
                .and_then(|s| serde_json::from_value::<MissionStatus>(serde_json::json!(s)).ok())?;
            Some(AgentEvent::MissionStatusChanged {
                mission_id: event.mission_id,
                status,
                summary: None,
            })
        }
        "agent_phase" | "phase" => Some(AgentEvent::AgentPhase {
            phase: event.content.clone(),
            detail: event
                .metadata
                .as_object()
                .and_then(|m| m.get("detail"))
                .and_then(|v| v.as_str())
                .map(ToString::to_string),
            agent: event
                .metadata
                .as_object()
                .and_then(|m| m.get("agent"))
                .and_then(|v| v.as_str())
                .map(ToString::to_string),
            mission_id,
        }),
        "goal_iteration" => Some(AgentEvent::GoalIteration {
            iteration: event
                .metadata
                .as_object()
                .and_then(|m| m.get("iteration"))
                .and_then(|v| v.as_u64())
                .unwrap_or(0) as u32,
            objective: event.content.clone(),
            mission_id,
        }),
        "goal_status" => Some(AgentEvent::GoalStatus {
            status: event
                .metadata
                .as_object()
                .and_then(|m| m.get("status"))
                .and_then(|v| v.as_str())
                .unwrap_or("active")
                .to_string(),
            objective: event.content.clone(),
            mission_id,
        }),
        _ => None,
    }
}

async fn send_ws_json<T: Serialize>(
    sender: &mut futures::stream::SplitSink<WebSocket, WsMessage>,
    value: &T,
) -> bool {
    match serde_json::to_string(value) {
        Ok(payload) => sender.send(WsMessage::Text(payload)).await.is_ok(),
        Err(err) => {
            tracing::warn!(error = %err, "Failed to serialize control WebSocket payload");
            true
        }
    }
}

pub async fn control_ws(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    axum::extract::Query(query): axum::extract::Query<StreamQuery>,
    ws: WebSocketUpgrade,
) -> Response {
    ws.on_upgrade(move |socket| control_ws_loop(state, user, query.mission, socket))
}

async fn control_ws_loop(
    state: Arc<AppState>,
    user: AuthUser,
    mission_filter: Option<Uuid>,
    socket: WebSocket,
) {
    let control = control_for_user(&state, &user).await;
    let mut rx = control.events_tx.subscribe();
    let mut mission_rx = if let Some(mid) = mission_filter {
        let mut map = control.mission_channels.write().await;
        let entry = map.entry(mid).or_insert_with(|| {
            let (tx, _rx) = broadcast::channel::<AgentEvent>(8192);
            tx
        });
        Some(entry.subscribe())
    } else {
        None
    };
    let ws_id = Uuid::new_v4();
    tracing::info!(
        ws_id = %ws_id,
        user_id = %user.id,
        username = %user.username,
        mission_filter = ?mission_filter,
        "Control WebSocket opened"
    );

    let initial = control.status.read().await.clone();
    let (mut sender, mut receiver) = socket.split();
    let mut latest_seq = match mission_filter {
        Some(mid) => control
            .mission_store
            .max_event_sequence(mid)
            .await
            .unwrap_or(0),
        None => 0,
    };
    let mut text_op_buffers: HashMap<Uuid, String> = HashMap::new();
    let initial_status = AgentEvent::Status {
        state: initial.state,
        queue_len: initial.queue_len,
        mission_id: initial.mission_id,
    };
    if !send_ws_json(&mut sender, &initial_status).await {
        return;
    }

    let mut heartbeat_interval = tokio::time::interval(std::time::Duration::from_secs(15));
    heartbeat_interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
    let mut shutdown_check_interval = tokio::time::interval(std::time::Duration::from_secs(1));
    shutdown_check_interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);

    loop {
        tokio::select! {
            _ = shutdown_check_interval.tick() => {
                if super::routes::is_shutdown_initiated() {
                    break;
                }
            }
            _ = heartbeat_interval.tick() => {
                if let Some(mid) = mission_filter {
                    latest_seq = control.mission_store.max_event_sequence(mid).await.unwrap_or(latest_seq);
                }
                if !send_ws_json(&mut sender, &ControlWsHeartbeat { seq: latest_seq }).await {
                    break;
                }
            }
            client_msg = receiver.next() => {
                match client_msg {
                    Some(Ok(WsMessage::Text(text))) => {
                        match serde_json::from_str::<ControlWsClientMessage>(&text) {
                            Ok(ControlWsClientMessage::Resume { since_seq }) => {
                                if let Some(mid) = mission_filter {
                                    match control.mission_store.get_events_since(mid, since_seq, None, None).await {
                                        Ok(events) => {
                                            for event in events {
                                                latest_seq = latest_seq.max(event.sequence);
                                                if let Some(agent_event) = stored_event_to_agent_event(&event) {
                                                    let outbound = text_op_events_for_stream(agent_event, &mut text_op_buffers);
                                                    for agent_event in outbound {
                                                        if !send_ws_json(&mut sender, &agent_event).await {
                                                            return;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        Err(err) => {
                                            let error = AgentEvent::Error {
                                                message: format!("Failed to resume stream: {err}"),
                                                mission_id: Some(mid),
                                                resumable: true,
                                            };
                                            if !send_ws_json(&mut sender, &error).await {
                                                return;
                                            }
                                        }
                                    }
                                }
                            }
                            Err(err) => {
                                tracing::debug!(ws_id = %ws_id, error = %err, "Ignoring malformed control WebSocket client message");
                            }
                        }
                    }
                    Some(Ok(WsMessage::Close(_))) | None => break,
                    Some(Ok(_)) => {}
                    Some(Err(err)) => {
                        tracing::warn!(ws_id = %ws_id, error = %err, "Control WebSocket receive error");
                        break;
                    }
                }
            }
            ev_result = async {
                match mission_rx.as_mut() {
                    Some(rx) => rx.recv().await,
                    None => std::future::pending().await,
                }
            }, if mission_rx.is_some() => {
                match ev_result {
                    Ok(ev) => {
                        if let Some(mid) = ev.mission_id() {
                            latest_seq = control.mission_store.max_event_sequence(mid).await.unwrap_or(latest_seq);
                        }
                        let outbound = text_op_events_for_stream(ev, &mut text_op_buffers);
                        for ev in outbound {
                            if !send_ws_json(&mut sender, &ev).await {
                                return;
                            }
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => {}
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
            result = rx.recv() => {
                match result {
                    Ok(ev) => {
                        let mission_id = ev.mission_id();
                        if mission_rx.is_some() {
                            let is_status = matches!(&ev, AgentEvent::Status { .. });
                            let is_fido = matches!(&ev, AgentEvent::FidoSignRequest { .. });
                            if !is_status && !is_fido {
                                continue;
                            }
                        } else if let Some(filter) = mission_filter {
                            let is_status = matches!(&ev, AgentEvent::Status { .. });
                            if !is_status && mission_id != Some(filter) {
                                continue;
                            }
                        }
                        if let Some(mid) = mission_id {
                            latest_seq = control.mission_store.max_event_sequence(mid).await.unwrap_or(latest_seq);
                        }
                        let outbound = text_op_events_for_stream(ev, &mut text_op_buffers);
                        for ev in outbound {
                            if !send_ws_json(&mut sender, &ev).await {
                                return;
                            }
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => {}
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
        }
    }

    tracing::info!(
        ws_id = %ws_id,
        user_id = %user.id,
        username = %user.username,
        "Control WebSocket closed"
    );
}

pub async fn stream(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    axum::extract::Query(query): axum::extract::Query<StreamQuery>,
) -> Result<Sse<impl Stream<Item = Result<Event, Infallible>>>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;
    let mission_filter = query.mission;
    // P3-#20: when a mission filter is set, subscribe to that mission's
    // dedicated channel — the fan-out task in spawn_control_session
    // mirrors events from the global tx into per-mission txs. Avoids
    // every connected SSE client iterating all events for missions
    // they don't care about. Status events are connection-scoped so we
    // *also* subscribe to the global channel and merge both streams
    // for the duration of the connection.
    let mut rx = control.events_tx.subscribe();
    let mut mission_rx = if let Some(mid) = mission_filter {
        let mut map = control.mission_channels.write().await;
        let entry = map.entry(mid).or_insert_with(|| {
            let (tx, _rx) = broadcast::channel::<AgentEvent>(8192);
            tx
        });
        Some(entry.subscribe())
    } else {
        None
    };
    let stream_id = Uuid::new_v4();
    tracing::info!(
        stream_id = %stream_id,
        user_id = %user.id,
        username = %user.username,
        mission_filter = ?mission_filter,
        "Control SSE stream opened"
    );

    // Emit an initial status snapshot immediately.
    let initial = control.status.read().await.clone();

    struct StreamDropGuard {
        stream_id: Uuid,
        user_id: String,
        username: String,
    }

    impl Drop for StreamDropGuard {
        fn drop(&mut self) {
            tracing::info!(
                stream_id = %self.stream_id,
                user_id = %self.user_id,
                username = %self.username,
                "Control SSE stream closed"
            );
        }
    }

    let drop_guard = StreamDropGuard {
        stream_id,
        user_id: user.id.clone(),
        username: user.username.clone(),
    };

    // Clone the metrics Arc into the stream closure so we can record
    // each delivered chunk + per-mission broadcast count (P0-#3).
    let metrics = state.control_metrics.clone();

    let stream = async_stream::stream! {
        let _guard = drop_guard;
        match Event::default().event("status").json_data(AgentEvent::Status {
            state: initial.state,
            queue_len: initial.queue_len,
            mission_id: initial.mission_id,
        }) {
            Ok(init_ev) => yield Ok(init_ev),
            Err(e) => {
                tracing::error!("Failed to serialize initial SSE status event: {e}");
            }
        }

        // Keepalive interval to prevent connection timeouts during long LLM calls.
        let mut keepalive_interval = tokio::time::interval(std::time::Duration::from_secs(15));
        keepalive_interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        let mut shutdown_check_interval = tokio::time::interval(std::time::Duration::from_secs(1));
        shutdown_check_interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        let mut text_op_buffers: HashMap<Uuid, String> = HashMap::new();

        loop {
            tokio::select! {
                _ = shutdown_check_interval.tick() => {
                    if super::routes::is_shutdown_initiated() {
                        tracing::info!(
                            stream_id = %stream_id,
                            user_id = %user.id,
                            username = %user.username,
                            "Control SSE stream closing for graceful shutdown"
                        );
                        break;
                    }
                }
                // P3-#20: read from either the per-mission channel (when
                // a mission filter is set) or the global broadcast (when
                // it isn't). The select arm using `as_mut().unwrap()` is
                // guarded by the `if mission_rx.is_some()` precondition
                // so the unwrap can't panic; tokio::select treats false
                // preconditions as disabled arms.
                ev_result = async {
                    match mission_rx.as_mut() {
                        Some(rx) => rx.recv().await,
                        None => std::future::pending().await,
                    }
                }, if mission_rx.is_some() => {
                    match ev_result {
                        Ok(ev) => {
                            let mission_id = ev.mission_id();
                            // Per-mission channel only carries events that
                            // already match the filter (the fan-out task
                            // is the gate); no further filtering needed.
                            match &ev {
                                AgentEvent::Thinking { .. } => {
                                    tracing::trace!(
                                        stream_id = %stream_id,
                                        event = %ev.event_name(),
                                        mission_id = ?mission_id,
                                        "Control SSE event (per-mission)"
                                    );
                                }
                                _ => {
                                    tracing::debug!(
                                        stream_id = %stream_id,
                                        event = %ev.event_name(),
                                        mission_id = ?mission_id,
                                        "Control SSE event (per-mission)"
                                    );
                                }
                            }
                            let outbound = text_op_events_for_stream(ev, &mut text_op_buffers);
                            for ev in outbound {
                                match serde_json::to_string(&ev) {
                                    Ok(payload) => {
                                        metrics.record_sse_chunk(payload.len());
                                        metrics.record_broadcast(ev.mission_id());
                                        yield Ok(Event::default()
                                            .event(ev.event_name())
                                            .data(payload));
                                    }
                                    Err(e) => {
                                        tracing::error!(
                                            stream_id = %stream_id,
                                            event = %ev.event_name(),
                                            error = %e,
                                            "Failed to serialize SSE event; dropping"
                                        );
                                    }
                                }
                            }
                        }
                        Err(broadcast::error::RecvError::Lagged(dropped)) => {
                            metrics.record_broadcast_lag(dropped);
                            tracing::warn!(stream_id = %stream_id, dropped, "Per-mission SSE lagged");
                            match Event::default()
                                .event("stream_lagged")
                                .json_data(serde_json::json!({ "dropped": dropped }))
                            {
                                Ok(sse) => yield Ok(sse),
                                Err(_) => {}
                            }
                        }
                        Err(broadcast::error::RecvError::Closed) => break,
                    }
                }
                result = rx.recv() => {
                    match result {
                        Ok(ev) => {
                            let mission_id = ev.mission_id();
                            // When a per-mission channel is active, the
                            // global arm only forwards connection-scoped
                            // events (Status, FidoSignRequest). Per-mission
                            // payloads are delivered above via the dedicated
                            // channel.
                            if mission_rx.is_some() {
                                let is_status = matches!(&ev, AgentEvent::Status { .. });
                                let is_fido = matches!(&ev, AgentEvent::FidoSignRequest { .. });
                                if !is_status && !is_fido {
                                    continue;
                                }
                            } else if let Some(filter) = mission_filter {
                                // Fallback: per-mission channel not present
                                // (e.g. first-event race). Apply the P1-#4
                                // filter directly.
                                let is_status = matches!(&ev, AgentEvent::Status { .. });
                                if !is_status && mission_id != Some(filter) {
                                    continue;
                                }
                            }
                            match &ev {
                                AgentEvent::Thinking { .. } => {
                                    tracing::trace!(
                                        stream_id = %stream_id,
                                        event = %ev.event_name(),
                                        mission_id = ?mission_id,
                                        "Control SSE event"
                                    );
                                }
                                _ => {
                                    tracing::debug!(
                                        stream_id = %stream_id,
                                        event = %ev.event_name(),
                                        mission_id = ?mission_id,
                                        "Control SSE event"
                                    );
                                }
                            }
                            // Serialize once so we can both ship the SSE
                            // frame and record an accurate byte count for
                            // the metrics endpoint (P0-#3). The payload
                            // size approximates the on-the-wire chunk
                            // length closely enough for p50/p99 use.
                            let outbound = text_op_events_for_stream(ev, &mut text_op_buffers);
                            for ev in outbound {
                                match serde_json::to_string(&ev) {
                                    Ok(payload) => {
                                        metrics.record_sse_chunk(payload.len());
                                        metrics.record_broadcast(ev.mission_id());
                                        yield Ok(Event::default()
                                            .event(ev.event_name())
                                            .data(payload));
                                    }
                                    Err(e) => {
                                        tracing::error!(
                                            stream_id = %stream_id,
                                            event = %ev.event_name(),
                                            error = %e,
                                            "Failed to serialize SSE event; dropping"
                                        );
                                    }
                                }
                            }
                        }
                        Err(broadcast::error::RecvError::Lagged(dropped)) => {
                            metrics.record_broadcast_lag(dropped);
                            // This receiver's cursor slipped behind the
                            // broadcast buffer's tail by `dropped` events.
                            // The stream itself is still alive — `recv()`
                            // will keep yielding fresh events on the next
                            // tick — so we deliberately don't emit an
                            // `error` event here. The dashboard treats
                            // `error` as fatal (red toast + system-error
                            // row in the chat) and it caused a confusing
                            // user-facing alert every time a chatty
                            // mission (text_delta burst, big tool result)
                            // outpaced the browser tab's event handler.
                            //
                            // Instead, emit a distinct `stream_lagged`
                            // event with the dropped count. The dashboard
                            // reacts by silently refetching the viewing
                            // mission via the existing `since_seq` path
                            // so any dropped events are recovered from
                            // the database. No user toast, no chat
                            // pollution.
                            tracing::warn!(
                                stream_id = %stream_id,
                                dropped = dropped,
                                "Control SSE stream lagged; signalling client refetch"
                            );
                            match Event::default()
                                .event("stream_lagged")
                                .json_data(serde_json::json!({ "dropped": dropped }))
                            {
                                Ok(sse) => yield Ok(sse),
                                Err(e) => {
                                    tracing::error!(
                                        stream_id = %stream_id,
                                        error = %e,
                                        "Failed to serialize SSE stream_lagged event"
                                    );
                                }
                            }
                        }
                        Err(broadcast::error::RecvError::Closed) => break,
                    }
                }
                _ = keepalive_interval.tick() => {
                    // Send SSE comment as keepalive (: comment\n\n)
                    let sse = Event::default().comment("keepalive");
                    yield Ok(sse);
                }
            }
        }
    };

    Ok(Sse::new(stream).keep_alive(
        axum::response::sse::KeepAlive::new()
            .interval(std::time::Duration::from_secs(15))
            .text("keepalive"),
    ))
}

/// Statuses worth forwarding to an external consumer (Paloma/Hermes): a mission
/// that FINISHED, hit a terminal failure, now needs the user, or was
/// acknowledged. We still skip the live churn (pending→active→paused) so a
/// callback means "something actionable happened", not "the status field moved".
///
/// `Interrupted` is included (P#1 asks for it) even though it can be emitted
/// transiently as resume-prep when a paused mission resumes — consumers dedupe
/// on the `event_id`/`sequence` carried in the payload and can treat a quickly
/// superseded interrupted→active as a no-op.
fn webhook_forwardable_status(status: MissionStatus) -> bool {
    matches!(
        status,
        MissionStatus::Completed
            | MissionStatus::Failed
            | MissionStatus::NotFeasible
            | MissionStatus::Blocked
            | MissionStatus::AwaitingUser
            | MissionStatus::Interrupted
            | MissionStatus::Acknowledged
    )
}

async fn paloma_webhook_forwarder_loop(
    mut events_rx: broadcast::Receiver<AgentEvent>,
    mission_store: Arc<dyn MissionStore>,
    workspaces: workspace::SharedWorkspaceStore,
    working_dir: PathBuf,
    url: String,
    secret: Option<String>,
    http: reqwest::Client,
) {
    tracing::info!(webhook_url = %url, "Paloma mission-status webhook forwarder started");
    // The dedupe record is DURABLE and success-gated: a marker means "this
    // status has been fully processed" — trivially on observation for
    // non-forwardable statuses, only after a successful POST for forwardable
    // ones. That closes the two loss windows the in-memory map had: a restart
    // blanking history, and delivery failure counting as delivery. Divergence
    // store-vs-marker is exactly the set of undelivered transitions, and the
    // sweep retries them until they land.
    let markers = super::webhook_markers::MarkerStore::load(&working_dir);
    let first_boot = !markers.loaded_from_disk;
    let markers = Arc::new(tokio::sync::Mutex::new(markers));
    if first_boot {
        // Adopt current history without forwarding any of it: pre-feature
        // missions have long-settled statuses, and replaying them as fresh
        // events would flood every bound conversation exactly once.
        let mut adopted = 0usize;
        let mut offset = 0usize;
        let mut guard = markers.lock().await;
        while offset < 5_000 {
            let page = match mission_store.list_missions(500, offset).await {
                Ok(page) => page,
                Err(_) => break,
            };
            if page.is_empty() {
                break;
            }
            let len = page.len();
            for mission in page {
                guard.set(mission.id, mission.status);
                adopted += 1;
            }
            if len < 500 {
                break;
            }
            offset += 500;
        }
        drop(guard);
        tracing::info!(
            adopted,
            "webhook markers: first boot, adopted current mission statuses"
        );
    }
    // Transitions currently being POSTed, so the sweep cannot double-send what
    // the broadcast arm already has in flight (and vice versa).
    let in_flight: Arc<tokio::sync::Mutex<std::collections::HashSet<(Uuid, MissionStatus)>>> =
        Arc::new(tokio::sync::Mutex::new(std::collections::HashSet::new()));
    // Bound concurrent in-flight callbacks (each does a get_mission + HTTP POST).
    let sem = Arc::new(tokio::sync::Semaphore::new(8));
    // Process-monotonic sequence so the consumer can order events and dedupe
    // (at-least-once delivery: a single logical event keeps one `event_id`
    // across retries). Resets on restart — `event_id` is the durable key.
    let sequence = Arc::new(std::sync::atomic::AtomicU64::new(0));
    // One forwarding path shared by the live broadcast arm and the
    // reconcile sweep below, so a transition can never be forwardable in
    // one and skipped by the other.
    let http_c = http.clone();
    let url_c = url.clone();
    let secret_c = secret.clone();
    let mission_store_c = Arc::clone(&mission_store);
    let workspaces_c = workspaces.clone();
    let working_dir_c = working_dir.clone();
    let sem_c = Arc::clone(&sem);
    let sequence_c = Arc::clone(&sequence);
    let markers_c = Arc::clone(&markers);
    let in_flight_c = Arc::clone(&in_flight);
    let forward = move |mission_id: Uuid,
                        status: MissionStatus,
                        old_status: Option<MissionStatus>| {
        let http = http_c.clone();
        let url = url_c.clone();
        let secret = secret_c.clone();
        let mission_store = Arc::clone(&mission_store_c);
        let workspaces = workspaces_c.clone();
        let working_dir = working_dir_c.clone();
        let sem = Arc::clone(&sem_c);
        let sequence = Arc::clone(&sequence_c);
        let markers = Arc::clone(&markers_c);
        let in_flight = Arc::clone(&in_flight_c);
        // Stable per-logical-event identity for idempotent consumers.
        let event_id = Uuid::new_v4();
        let seq = sequence.fetch_add(1, std::sync::atomic::Ordering::SeqCst);

        // The mission load + POST run in a spawned, concurrency-bounded
        // task so neither a slow DB read nor a slow webhook can stall the
        // caller.
        tokio::spawn(async move {
            let _permit = sem.acquire_owned().await;
            let mission = mission_store.get_mission(mission_id).await.ok().flatten();
            let title = mission
                .as_ref()
                .and_then(|mission| mission.title.clone())
                .unwrap_or_else(|| mission_id.to_string());
            let project = mission.as_ref().map(|m| &m.project);
            let run = mission_store
                .get_active_mission_run(mission_id)
                .await
                .ok()
                .flatten();
            let mut remote_jobs = crate::remote_node::job_ledger::load(&working_dir)
                .await
                .unwrap_or_default()
                .into_iter()
                .filter(|handle| handle.mission_id == mission_id)
                .map(|handle| {
                    serde_json::json!({
                        "job_id": handle.job_id,
                        "node_id": handle.node_id,
                        "kind": handle.kind,
                        "accepted_at": handle.accepted_at,
                        "heartbeat_at": handle.heartbeat_at,
                        "identity": handle.identity,
                    })
                })
                .collect::<Vec<_>>();
            remote_jobs.extend(
                crate::remote_node::job_ledger::terminal_receipts_for_mission(
                    &working_dir,
                    mission_id,
                )
                .await
                .unwrap_or_default()
                .into_iter()
                .rev()
                .take(16)
                .map(|receipt| {
                    serde_json::json!({
                        "job_id": receipt.job_id,
                        "node_id": receipt.node_id,
                        "kind": "remote_build_receipt",
                        "state": receipt.state,
                        "started_at": receipt.started_at,
                        "finished_at": receipt.finished_at,
                        "exit_status": receipt.exit_status,
                        "identity": receipt.identity,
                        "artifacts": receipt.artifacts,
                    })
                }),
            );
            let terminal_reason = mission
                .as_ref()
                .and_then(|mission| mission.terminal_reason.as_deref());
            let recommended_action = match terminal_reason {
                Some("server_shutdown" | "orphan_no_runner") => "resume_once",
                Some("auth_error") => "disable_provider_and_reroute",
                Some("rate_limited" | "capacity_limited") => "reroute_or_queue",
                Some("watchdog_stalled" | "cancelled") => "inspect_artifacts",
                _ if status == MissionStatus::Interrupted => "reconcile_then_resume",
                _ if status == MissionStatus::Failed => "classify_failure",
                _ if status == MissionStatus::AwaitingUser => "inspect_result",
                _ => "notify",
            };
            // Resolve workspace_name from the registry (the store row
            // usually leaves it null), so the payload is self-contained.
            let workspace_name = match mission.as_ref() {
                Some(m) => match m.workspace_name.clone() {
                    Some(name) => Some(name),
                    None => workspaces.get(m.workspace_id).await.map(|ws| ws.name),
                },
                None => None,
            };
            // The mission's ACTUAL final output — not just status metadata — so
            // a mission-backed delegation returns a real work product to the
            // delegating Hermes agent (the fold prefers `result_summary`).
            // Fetched only for terminal (forwardable) transitions; best-effort.
            let result_summary: Option<String> = if webhook_forwardable_status(status) {
                mission_store
                    .latest_assistant_text(mission_id)
                    .await
                    .ok()
                    .flatten()
            } else {
                None
            };
            let wake = mission
                .as_ref()
                .map(|m| super::mission_horizon::wake_fields_for_mission(m, &working_dir));
            let body = serde_json::json!({
                // Idempotency / ordering (P#6): consumers dedupe on
                // `event_id` and may order by `sequence`.
                "event_id": event_id,
                // The mission's final assistant output on terminal transitions.
                "result_summary": result_summary,
                "sequence": seq,
                "mission_id": mission_id,
                "old_status": old_status,
                "status": status,
                // Event-type mirror of `status` so consumers with
                // route-level event filters (e.g. the Hermes webhook
                // platform reads `payload.type`) can drop unwanted
                // transitions like `acknowledged` before spawning an
                // agent run.
                "type": status,
                "title": title,
                "short_description": mission
                    .as_ref()
                    .and_then(|m| m.short_description.clone()),
                "workspace_id": mission.as_ref().map(|m| m.workspace_id),
                "workspace_name": workspace_name,
                "backend": mission.as_ref().map(|m| m.backend.clone()),
                "terminal_reason": terminal_reason,
                // What the terminating guard OBSERVED. Without it, consumers
                // invent causes: "transport bug", "GitHub is disabled",
                // "pool needs re-provisioning" — all measured this week.
                "terminal_evidence": mission
                    .as_ref()
                    .and_then(|mission| mission.terminal_evidence.as_deref()),
                "resumable": matches!(status, MissionStatus::Interrupted | MissionStatus::Failed | MissionStatus::Blocked),
                "recommended_action": recommended_action,
                "execution": run.as_ref().map(|run| serde_json::json!({
                    "run_id": run.run_id,
                    "generation": run.generation,
                    "state": run.execution_state,
                    "heartbeat_at": run.heartbeat_at,
                    "scope_unit": run.scope_unit,
                })),
                "remote_jobs": remote_jobs,
                "updated_at": mission.as_ref().map(|m| m.updated_at.clone()),
                // When the status itself last changed (P#5) — the most
                // relevant staleness anchor for a status-change webhook.
                "last_status_change_at": mission
                    .as_ref()
                    .and_then(|m| m.activity.last_status_change_at.clone()),
                // Project tagging so Paloma can route by project/track/
                // intent/PR instead of parsing titles.
                "project": project.and_then(|p| p.project.clone()),
                "track": project.and_then(|p| p.track.clone()),
                "intent": project.and_then(|p| p.intent.clone()),
                "github_pr": project.and_then(|p| p.github_pr.clone()),
                "tags": project.map(|p| p.tags.clone()).unwrap_or_default(),
                // Creation provenance. Without these, a status webhook
                // lands in an isolated consumer session with no way
                // back to the conversation that started the mission —
                // results then sit acknowledged and unreported. The
                // consumer routes the completion into `origin_session`.
                //
                // TRUST: `origin_session` is a routing HINT, not
                // authority. It is declared by the creating client and
                // the MCP transport carries no per-call session
                // context to verify it against, so a delivery handler
                // MUST confirm the target conversation actually
                // references this mission_id before delivering there,
                // and fall back to its default notification path
                // otherwise.
                "origin": mission.as_ref().and_then(|m| m.origin.clone()),
                "origin_session": mission
                    .as_ref()
                    .and_then(|m| m.origin_session_id.clone()),
                // Producer-resolved wake tip: the bound project conversation
                // if one exists, else the creating origin. Hermes prefers
                // this over opening an isolated webhook session.
                "wake_session": wake.as_ref().and_then(|w| w.session.clone()),
                "wake_source": wake.as_ref().map(|w| w.source),
                // Track state so a watchdog can tell "intentionally
                // waiting (CI/review/external)" from "no worker = stuck".
                "desired_state": project.and_then(|p| p.desired_state.clone()),
                "next_check_at": project.and_then(|p| p.next_check_at.clone()),
                // For awaiting_user, whether the agent needs a decision
                // or is just waiting to be acked/merged.
                "awaiting_kind": mission
                    .as_ref()
                    .and_then(|m| m.awaiting_kind)
                    .map(|k| k.as_str()),
            });

            // Serialize once so the signature is computed over the
            // exact bytes sent (consumers verify HMAC over the raw
            // body, e.g. the Hermes webhook platform's GitHub-style
            // `X-Hub-Signature-256` check).
            let payload = match serde_json::to_vec(&body) {
                Ok(bytes) => bytes,
                Err(err) => {
                    tracing::warn!(
                        mission_id = %mission_id,
                        "Failed to serialize Paloma webhook payload: {}",
                        err
                    );
                    return;
                }
            };
            let signature = secret.as_ref().and_then(|secret| {
                use hmac::{Hmac, Mac};
                let mut mac = Hmac::<sha2::Sha256>::new_from_slice(secret.as_bytes()).ok()?;
                mac.update(&payload);
                Some(format!(
                    "sha256={}",
                    hex::encode(mac.finalize().into_bytes())
                ))
            });

            // At-least-once: retry transient failures with the SAME
            // event_id so the consumer can dedupe. Bounded so a dead
            // endpoint can't pile up tasks.
            const MAX_ATTEMPTS: u32 = 3;
            for attempt in 1..=MAX_ATTEMPTS {
                let mut request = http
                    .post(&url)
                    .header(reqwest::header::CONTENT_TYPE, "application/json")
                    .body(payload.clone());
                if let Some(signature) = signature.as_deref() {
                    request = request.header("X-Hub-Signature-256", signature);
                }
                match request.send().await {
                    Ok(resp) if resp.status().is_success() => {
                        // Only a delivered event earns its durable marker. An
                        // exhausted retry leaves it unset, so the 60s sweep
                        // re-sends until the consumer is reachable again.
                        markers.lock().await.set(mission_id, status);
                        break;
                    }
                    Ok(resp) => {
                        tracing::warn!(
                            mission_id = %mission_id,
                            webhook_url = %url,
                            attempt,
                            status = %resp.status(),
                            "Paloma webhook returned non-success status"
                        );
                    }
                    Err(err) => {
                        tracing::warn!(
                            mission_id = %mission_id,
                            webhook_url = %url,
                            attempt,
                            "Failed to forward Paloma mission status webhook: {}",
                            err
                        );
                    }
                }
                if attempt < MAX_ATTEMPTS {
                    tokio::time::sleep(std::time::Duration::from_millis(250 * attempt as u64))
                        .await;
                }
            }
            in_flight.lock().await.remove(&(mission_id, status));
        });
    };
    // The broadcast channel is lossy under bursts, and not every status
    // writer broadcasts. Measured 2026-08-06: mission 45e54e0b reached
    // awaiting_user and acknowledged at 09:35:42Z, its origin conversation
    // was adopted and waiting, and neither transition was ever forwarded --
    // no lag warning, nothing to retry, the conversation simply never woke.
    // The sweep reconciles from the store: any mission whose CURRENT status
    // is forwardable, differs from what we last forwarded, and changed
    // recently is forwarded now. Older divergences are adopted silently so
    // a fresh map after restart cannot replay history.
    let mut reconcile = tokio::time::interval(std::time::Duration::from_secs(60));
    reconcile.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
    loop {
        let recv = tokio::select! {
            result = events_rx.recv() => Some(result),
            _ = reconcile.tick() => None,
        };
        let Some(result) = recv else {
            let missions = match mission_store.list_missions(400, 0).await {
                Ok(missions) => missions,
                Err(_) => continue,
            };
            for mission in missions {
                let status = mission.status;
                let prior = markers.lock().await.get(mission.id);
                if prior == Some(status) {
                    continue;
                }
                if !webhook_forwardable_status(status) {
                    // Nothing to deliver; recording it keeps re-entry
                    // detection exact (A -> B -> A must forward A again).
                    markers.lock().await.set(mission.id, status);
                    continue;
                }
                if !in_flight.lock().await.insert((mission.id, status)) {
                    continue;
                }
                // No recency window: the marker file is the durable authority,
                // so a divergence IS an undelivered transition, however old --
                // that is the whole lossless-across-outages property. First
                // boot cannot replay history because adoption above marked it.
                tracing::info!(
                    mission_id = %mission.id,
                    ?status,
                    "webhook reconcile: forwarding a status transition the \
                     broadcast never delivered"
                );
                forward(mission.id, status, prior);
            }
            continue;
        };
        match result {
            Ok(AgentEvent::MissionStatusChanged {
                mission_id, status, ..
            }) => {
                let old_status = markers.lock().await.get(mission_id);
                if old_status == Some(status) {
                    continue;
                }
                if !webhook_forwardable_status(status) {
                    markers.lock().await.set(mission_id, status);
                    continue;
                }
                if !in_flight.lock().await.insert((mission_id, status)) {
                    continue;
                }
                forward(mission_id, status, old_status);
            }
            Ok(_) => {}
            Err(broadcast::error::RecvError::Lagged(dropped)) => {
                tracing::warn!(
                    dropped,
                    webhook_url = %url,
                    "Paloma webhook forwarder lagged; continuing with latest event"
                );
            }
            Err(broadcast::error::RecvError::Closed) => break,
        }
    }
}

/// Spawn the global control session actor.
#[allow(clippy::too_many_arguments)]
fn spawn_control_session(
    control_hub: ControlHub,
    config: Config,
    root_agent: AgentRef,
    mcp: Arc<McpRegistry>,
    workspaces: workspace::SharedWorkspaceStore,
    library: SharedLibrary,
    mission_store: Arc<dyn MissionStore>,
    secrets: Option<Arc<SecretsStore>>,
    telegram_bridge: Option<super::telegram::SharedTelegramBridge>,
    user_id: String,
) -> ControlState {
    let (cmd_tx, cmd_rx) = mpsc::channel::<ControlCommand>(256);
    // 8 192 slots ≈ ~8 s of headroom even for chatty missions (text_delta
    // bursts during long completions push ~1 k events / sec). The previous
    // 1 024 cap regularly overflowed for any tab whose JS event handler
    // momentarily slowed (large React reducer work, tab backgrounded by
    // Chrome). Per-receiver cursor + Arc<AgentEvent> internal layout keeps
    // the memory cost bounded.
    let (events_tx, events_rx) = broadcast::channel::<AgentEvent>(8192);
    let tool_hub = Arc::new(FrontendToolHub::new());
    let status = Arc::new(RwLock::new(ControlStatus {
        state: ControlRunState::Idle,
        queue_len: 0,
        mission_id: None,
    }));
    let current_mission = Arc::new(RwLock::new(None));

    // Channel for agent-initiated mission control commands
    let (mission_cmd_tx, mission_cmd_rx) =
        mpsc::channel::<crate::tools::mission::MissionControlCommand>(64);

    let current_tree = Arc::new(RwLock::new(None));
    let progress = Arc::new(RwLock::new(ExecutionProgress::default()));
    let running_missions = Arc::new(RwLock::new(Vec::new()));
    let mission_search_cache = Arc::new(RwLock::new(HashMap::new()));
    let max_parallel =
        crate::settings::max_parallel_missions_cached_or(config.max_parallel_missions);

    let mission_channels: Arc<
        RwLock<std::collections::HashMap<Uuid, broadcast::Sender<AgentEvent>>>,
    > = Arc::new(RwLock::new(std::collections::HashMap::new()));

    // P3-#20 fan-out task: subscribe to the global channel and mirror
    // every event into its per-mission channel. Lives for the process
    // lifetime; closes cleanly when the channel ends. Keeps the cost
    // out of every send-site so existing `events_tx.send()` calls
    // don't need to know about the per-mission split.
    {
        let mut rx = events_tx.subscribe();
        let mission_channels = Arc::clone(&mission_channels);
        tokio::spawn(async move {
            loop {
                match rx.recv().await {
                    Ok(ev) => {
                        let Some(mid) = ev.mission_id() else { continue };
                        let sender = {
                            let map = mission_channels.read().await;
                            map.get(&mid).cloned()
                        };
                        if let Some(sender) = sender {
                            let _ = sender.send(ev);
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
        });
    }

    let state = ControlState {
        cmd_tx,
        events_tx: events_tx.clone(),
        mission_channels,
        tool_hub: Arc::clone(&tool_hub),
        status: Arc::clone(&status),
        current_mission: Arc::clone(&current_mission),
        current_tree: Arc::clone(&current_tree),
        progress: Arc::clone(&progress),
        running_missions: Arc::clone(&running_missions),
        max_parallel,
        mission_store: Arc::clone(&mission_store),
        mission_search_cache,
    };

    // Mission-status alerts are event-driven for low latency. The existing
    // Paloma scheduler poll still runs as a restart/missed-event backstop and
    // continues to own the other periodic Paloma jobs.
    if let Some(bridge) = telegram_bridge.as_ref() {
        bridge.start_event_alert_loop(events_tx.subscribe());
    }

    if let Some(url) = config
        .paloma_webhook_forward_url
        .as_ref()
        .filter(|url| !url.is_empty())
    {
        tokio::spawn(paloma_webhook_forwarder_loop(
            events_tx.subscribe(),
            Arc::clone(&state.mission_store),
            workspaces.clone(),
            config.working_dir.clone(),
            url.clone(),
            config.paloma_webhook_secret.clone(),
            reqwest::Client::builder()
                .connect_timeout(std::time::Duration::from_secs(5))
                .timeout(std::time::Duration::from_secs(10))
                .build()
                .unwrap_or_else(|_| reqwest::Client::new()),
        ));
    }

    // Event-driven scope teardown: stop a mission's exec scopes as soon as
    // its status stops needing a live harness. The periodic scope reaper
    // (scope_reaper::spawn) backstops events missed across restarts.
    super::scope_reaper::spawn_status_listener(
        events_tx.subscribe(),
        Arc::clone(&state.mission_store),
    );

    // Shared registry of in-flight Claude Code background shell tasks. Written
    // by the control actor's ToolResult arm; read by the auto-resume watcher.
    let background_tasks: super::mission_runner::BackgroundTaskRegistry =
        Arc::new(RwLock::new(std::collections::HashMap::new()));

    // Spawn the main control actor
    tokio::spawn(control_actor_loop(
        control_hub,
        config.clone(),
        root_agent,
        mcp,
        workspaces.clone(),
        library.clone(),
        cmd_rx,
        mission_cmd_rx,
        mission_cmd_tx,
        state.cmd_tx.clone(),
        events_tx.clone(),
        events_rx,
        tool_hub.clone(),
        status,
        current_mission,
        current_tree,
        progress,
        mission_store,
        secrets,
        user_id,
        Arc::clone(&background_tasks),
    ));

    // Recover missions stopped by the previous backend process. Graceful
    // shutdown marks live runners as `interrupted/server_shutdown`; a hard
    // stop can leave task-mode missions as `active`.
    if state.mission_store.is_persistent() {
        let store = Arc::clone(&state.mission_store);
        let tx = events_tx.clone();
        let cmd = state.cmd_tx.clone();
        tokio::spawn(async move {
            recover_server_shutdown_missions(store, tx, cmd).await;
        });
    }

    // Spawn background stale mission cleanup task (if enabled)
    if config.stale_mission_hours > 0 && state.mission_store.is_persistent() {
        tokio::spawn(stale_mission_cleanup_loop(
            Arc::clone(&state.mission_store),
            config.stale_mission_hours,
            state.cmd_tx.clone(),
            events_tx.clone(),
        ));
    }

    // Spawn in-process orphan detector. Every 60 s it asks the control
    // actor for the live running list and marks any mission whose
    // `seconds_since_activity` exceeds the silence threshold as
    // interrupted. This covers two failure modes the existing recovery
    // didn't:
    //  1. mission_runner task died mid-flight (backend alive, codex
    //     orphaned in its container). Boot-time recovery only catches
    //     this across a full restart.
    //  2. codex hung — process alive in `futex_wait_queue` with no
    //     events flowing. Stale-mission cleanup eventually catches this
    //     after `stale_hours` (default 24 h); 10 min is a much closer
    //     match for "agent may be stuck" UX.
    if state.mission_store.is_persistent() {
        tokio::spawn(stuck_mission_watchdog_loop(
            Arc::clone(&state.mission_store),
            state.cmd_tx.clone(),
            events_tx.clone(),
            Arc::clone(&tool_hub),
            workspaces.clone(),
        ));
        tokio::spawn(ack_promotion_loop(
            Arc::clone(&state.mission_store),
            events_tx.clone(),
        ));
    }

    // Spawn the background-task auto-resume watcher. When a mission agent
    // launches a `Bash` job with `run_in_background: true` and then ends its
    // turn, the mission parks in `AwaitingUser` with nothing to wake it when the
    // job finishes. This watcher polls captured background tasks, detects
    // completion inside the workspace, and resumes the agent with the output.
    // Uses an in-memory registry (no persistent store required). Gated by
    // `BACKGROUND_TASK_AUTORESUME` (default enabled).
    // Settle any mission left in `WaitingBackground` by a previous process:
    // the in-memory background-task registry is empty at boot, so those jobs are
    // no longer tracked and the mission would be stranded outside every terminal
    // path. Runs regardless of whether the watcher below is enabled.
    if state.mission_store.is_persistent() {
        let store = Arc::clone(&state.mission_store);
        let tx = events_tx.clone();
        tokio::spawn(async move {
            reset_waiting_background_on_boot(store, tx).await;
        });
    }

    if super::mission_runner::background_task_autoresume_enabled() {
        tokio::spawn(background_task_autoresume_loop(
            Arc::clone(&state.mission_store),
            state.cmd_tx.clone(),
            events_tx.clone(),
            workspaces.clone(),
            Arc::clone(&background_tasks),
        ));
    } else {
        tracing::info!(
            "Background-task auto-resume watcher not started (BACKGROUND_TASK_AUTORESUME disabled)"
        );
    }

    // Spawn event logger task (logs all events to SQLite for debugging/replay)
    if state.mission_store.is_persistent() {
        let store = Arc::clone(&state.mission_store);
        let mut event_rx = events_tx.subscribe();
        tokio::spawn(async move {
            // Per-mission lag counter so we can spot a single noisy mission
            // dragging the global SQLite write path. Without this, the
            // generic "Event logger lagged by N events" warning can't tell
            // us which mission's event stream is the culprit — critical
            // when investigating incidents like the ab260b2e 50-minute
            // "Yielding." turn where 396 events streamed to the SSE but
            // never landed in the database.
            let mut lag_total: u64 = 0;
            let lag_per_mission: std::collections::HashMap<Uuid, u64> =
                std::collections::HashMap::new();
            let mut processed_total: u64 = 0;
            let mut processed_per_type: std::collections::HashMap<&'static str, u64> =
                std::collections::HashMap::new();
            let mut last_stats_at = std::time::Instant::now();
            let stats_interval = std::time::Duration::from_secs(60);
            loop {
                match event_rx.recv().await {
                    Ok(event) => {
                        let ev_name = event.event_name();
                        *processed_per_type.entry(ev_name).or_insert(0) += 1;
                        // Extract mission_id from event
                        if let Some(mid) = event.mission_id() {
                            if should_persist_event(&event) {
                                processed_total += 1;
                                if let Err(e) = store.log_event(mid, &event).await {
                                    tracing::warn!(
                                        mission_id = %mid,
                                        event_type = ev_name,
                                        "Failed to log event: {}",
                                        e
                                    );
                                }
                            }
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(n)) => {
                        lag_total = lag_total.saturating_add(n);
                        tracing::warn!(
                            dropped = n,
                            lag_total = lag_total,
                            processed_total = processed_total,
                            "Event logger lagged by {} events (next recv() resumes after the gap)",
                            n
                        );
                        // Best-effort: record the lag against any missions
                        // that emitted events immediately after the gap. We
                        // don't know which mission the missed events belonged
                        // to, but the next successful recv() tells us who
                        // was active when we caught up. The Map is cleared
                        // on every status snapshot to bound memory.
                        let _ = lag_per_mission; // keep the field alive for the stats block
                    }
                    Err(broadcast::error::RecvError::Closed) => break,
                }

                // Periodic stats: even on the happy path we want a heartbeat
                // confirming the logger is keeping up. If the gap between
                // processed and broadcast grows, the next Lagged warning
                // gets actionable context.
                if last_stats_at.elapsed() >= stats_interval {
                    if processed_total > 0 || lag_total > 0 {
                        tracing::debug!(
                            processed_total,
                            lag_total,
                            by_type = ?processed_per_type,
                            "Event logger heartbeat"
                        );
                    }
                    last_stats_at = std::time::Instant::now();
                }
            }
            // Drain stats on shutdown so the next restart can see whether
            // the previous process lost events.
            if lag_total > 0 || processed_total > 0 {
                tracing::info!(
                    processed_total,
                    lag_total,
                    by_type = ?processed_per_type,
                    "Event logger task stopped"
                );
            } else {
                tracing::info!("Event logger task stopped");
            }
        });
    }

    // Spawn native-loop observer: turns harness goal events into
    // Automation rows + AutomationExecution iterations so the
    // automations panel shows /goal alongside scheduled automations.
    if state.mission_store.is_persistent() && config.automations_enabled {
        let store = Arc::clone(&state.mission_store);
        let tx = state.events_tx.clone();
        tokio::spawn(async move {
            super::native_loop_observer::run(store, tx).await;
        });
    }

    // Spawn automation scheduler task
    if state.mission_store.is_persistent() && config.automations_enabled {
        tokio::spawn(automation_scheduler_loop(
            Arc::clone(&state.mission_store),
            library.clone(),
            state.cmd_tx.clone(),
            workspaces.clone(),
            state.events_tx.clone(),
            telegram_bridge.clone(),
            config.working_dir.clone(),
        ));
    } else if state.mission_store.is_persistent() {
        tracing::info!("Automation scheduler disabled by config");
    }

    state
}

/// Resolve an IANA timezone string to a chrono::FixedOffset at a given UTC instant.
///
/// Falls back to UTC if the timezone is unknown.  We use a simple lookup table for
/// common timezones to avoid pulling in chrono-tz (heavy dependency).  The offset is
/// evaluated at `now_utc` to account for DST — though the lookup table doesn't model
/// DST transitions, the most common use-case (Europe/Paris, America/New_York, etc.)
/// is close enough for a 5-second poll cadence.
/// Map a timezone string to a `chrono_tz::Tz`, handling common abbreviations
/// and IANA names.  Returns `None` for fixed-offset strings like "+02:00".
fn resolve_tz(tz: &str) -> Option<chrono_tz::Tz> {
    // Fixed-offset strings ("+02:00", "-05:00") are not IANA timezones.
    if tz.starts_with('+') || tz.starts_with('-') {
        return None;
    }

    // Handle common abbreviations that chrono-tz doesn't know about.
    let canonical = match tz {
        "UTC" | "GMT" => "Etc/UTC",
        "EST" => "America/New_York",
        "CST" => "America/Chicago",
        "MST" => "America/Denver",
        "PST" => "America/Los_Angeles",
        "CET" => "Europe/Paris",
        "JST" => "Asia/Tokyo",
        "AEST" => "Australia/Sydney",
        other => other,
    };

    match canonical.parse::<chrono_tz::Tz>() {
        Ok(timezone) => Some(timezone),
        Err(_) => {
            tracing::warn!(timezone = %tz, "Unknown timezone, rejecting");
            None
        }
    }
}

fn resolve_tz_offset(tz: &str, now_utc: chrono::DateTime<chrono::Utc>) -> chrono::FixedOffset {
    // Try to parse as a fixed offset first (e.g. "+02:00", "-05:00").
    if let Ok(fo) = tz.parse::<chrono::FixedOffset>() {
        return fo;
    }

    use chrono::Offset;
    match resolve_tz(tz) {
        Some(timezone) => {
            let local_dt = now_utc.with_timezone(&timezone);
            local_dt.offset().fix()
        }
        None => chrono::FixedOffset::east_opt(0).unwrap(),
    }
}

/// Background task that checks for automations and triggers them at their intervals.
async fn automation_scheduler_loop(
    mission_store: Arc<dyn MissionStore>,
    library: SharedLibrary,
    cmd_tx: mpsc::Sender<ControlCommand>,
    workspaces: workspace::SharedWorkspaceStore,
    events_tx: broadcast::Sender<AgentEvent>,
    telegram_bridge: Option<super::telegram::SharedTelegramBridge>,
    working_dir: PathBuf,
) {
    use super::automation_variables::{substitute_variables, SubstitutionContext};
    use super::mission_store::{AutomationExecution, CommandSource, ExecutionStatus, TriggerType};

    // Check every 5 seconds for automations that need to run
    let check_interval = std::time::Duration::from_secs(5);

    tracing::info!(
        telegram_bridge_available = telegram_bridge.is_some(),
        "Automation scheduler task started"
    );

    let mut logged_unsupported = false;
    let mut tick_count: u64 = 0;

    loop {
        tokio::time::sleep(check_interval).await;
        tick_count += 1;

        // Every ~60 seconds (12 ticks × 5s), run housekeeping sweeps.
        if tick_count.is_multiple_of(12) {
            // Timeout stale WaitingExternal workflows (older than 30 minutes).
            match mission_store
                .timeout_stale_telegram_workflows(30 * 60)
                .await
            {
                Ok(n) if n > 0 => {
                    tracing::info!("Timed out {} stale WaitingExternal Telegram workflows", n);
                }
                Err(e) => {
                    tracing::warn!("Failed to timeout stale Telegram workflows: {}", e);
                }
                _ => {}
            }

            // Recover stale 'sending' scheduled messages (stuck >5 min after crash).
            match mission_store
                .recover_stale_sending_scheduled_messages(5 * 60)
                .await
            {
                Ok(n) if n > 0 => {
                    tracing::info!(
                        "Recovered {} stale 'sending' scheduled messages back to 'pending'",
                        n
                    );
                }
                Err(e) => {
                    tracing::warn!("Failed to recover stale sending messages: {}", e);
                }
                _ => {}
            }

            // Clean up old webhook dedup entries (older than 15 minutes).
            match mission_store.cleanup_webhook_dedup(15 * 60).await {
                Ok(n) if n > 0 => {
                    tracing::debug!("Cleaned up {} expired webhook dedup entries", n);
                }
                Err(e) => {
                    tracing::warn!("Failed to cleanup webhook dedup entries: {}", e);
                }
                _ => {}
            }
        }

        let automations = match mission_store.list_active_automations().await {
            Ok(automations) => automations,
            Err(e) => {
                if !logged_unsupported {
                    tracing::warn!("Automation scheduler disabled: {}", e);
                    logged_unsupported = true;
                }
                continue;
            }
        };

        for automation in automations {
            // Only trigger interval-based and cron-based automations.
            // Webhooks are triggered via HTTP, agent_finished via turn completion,
            // Telegram via the Telegram bridge.
            enum ScheduleKind {
                Interval(u64),
                Cron {
                    expression: String,
                    timezone: String,
                },
                DurableJobTerminal(Uuid),
            }
            let schedule = match &automation.trigger {
                TriggerType::Interval { seconds } => ScheduleKind::Interval(*seconds),
                TriggerType::Cron {
                    expression,
                    timezone,
                } => ScheduleKind::Cron {
                    expression: expression.clone(),
                    timezone: timezone.clone(),
                },
                TriggerType::Webhook { .. } => continue,
                TriggerType::AgentFinished => continue,
                TriggerType::Telegram { .. } => continue,
                TriggerType::DurableJobTerminal { job_id } => {
                    ScheduleKind::DurableJobTerminal(*job_id)
                }
            };

            let mission = match mission_store.get_mission(automation.mission_id).await {
                Ok(Some(mission)) => mission,
                Ok(None) => {
                    tracing::debug!(
                        "Automation {} references missing mission {}",
                        automation.id,
                        automation.mission_id
                    );
                    continue;
                }
                Err(e) => {
                    tracing::warn!(
                        "Failed to load mission {} for automation {}: {}",
                        automation.mission_id,
                        automation.id,
                        e
                    );
                    continue;
                }
            };

            let consecutive_failures =
                consecutive_failure_count_for_automation(&mission_store, &automation).await;
            let has_fired = if matches!(
                automation.stop_policy,
                mission_store::StopPolicy::AfterFirstFire
            ) {
                automation_has_fired(&mission_store, automation.id).await
            } else {
                false
            };

            if stop_policy_matches_status(
                &automation.stop_policy,
                mission.status,
                consecutive_failures,
                has_fired,
            )
            .await
            {
                tracing::info!(
                    "Disabling automation {} due to stop policy {:?} (mission {} status {:?})",
                    automation.id,
                    automation.stop_policy,
                    mission.id,
                    mission.status
                );
                let mut updated = automation.clone();
                updated.active = false;
                if let Err(e) = mission_store.update_automation(updated).await {
                    tracing::warn!(
                        "Failed to disable automation {} after stop policy match: {}",
                        automation.id,
                        e
                    );
                }
                continue;
            }

            // Check if it's time to trigger based on schedule type.
            let should_trigger = match &schedule {
                ScheduleKind::Interval(interval_seconds) => {
                    if let Some(ref last_triggered) = automation.last_triggered_at {
                        match chrono::DateTime::parse_from_rfc3339(last_triggered) {
                            Ok(last_time) => {
                                let elapsed = chrono::Utc::now()
                                    .signed_duration_since(last_time.with_timezone(&chrono::Utc));
                                elapsed.num_seconds() >= *interval_seconds as i64
                            }
                            Err(_) => true,
                        }
                    } else {
                        true // Never triggered before
                    }
                }
                ScheduleKind::Cron {
                    expression,
                    timezone,
                } => {
                    match croner::Cron::new(expression).parse() {
                        Ok(cron) => {
                            // Determine "now" in the configured timezone.
                            let now_utc = chrono::Utc::now();

                            // If we've never triggered (start_immediately=true sets
                            // last_triggered_at to None), fire right away.
                            let reference = if let Some(ref lt) = automation.last_triggered_at {
                                match chrono::DateTime::parse_from_rfc3339(lt) {
                                    Ok(t) => t.with_timezone(&chrono::Utc),
                                    Err(_) => now_utc - chrono::Duration::seconds(10),
                                }
                            } else {
                                // Never triggered → fire immediately on next tick.
                                // Using a very large lookback ensures the next cron
                                // occurrence after this reference is in the past.
                                now_utc - chrono::Duration::days(366)
                            };

                            // Find the next occurrence after the last trigger.
                            // If that occurrence is <= now, it's time to fire.
                            // Use real timezone (not a FixedOffset snapshot) so DST
                            // transitions are evaluated correctly by croner.
                            if let Some(tz) = resolve_tz(timezone) {
                                let ref_with_tz = reference.with_timezone(&tz);
                                match cron.find_next_occurrence(&ref_with_tz, false) {
                                    Ok(next) => {
                                        let next_utc = next.with_timezone(&chrono::Utc);
                                        next_utc <= now_utc
                                    }
                                    Err(_) => false,
                                }
                            } else {
                                // Fixed-offset timezone string (e.g. "+02:00")
                                let tz_offset = resolve_tz_offset(timezone, now_utc);
                                let ref_with_tz = reference.with_timezone(&tz_offset);
                                match cron.find_next_occurrence(&ref_with_tz, false) {
                                    Ok(next) => {
                                        let next_utc = next.with_timezone(&chrono::Utc);
                                        next_utc <= now_utc
                                    }
                                    Err(_) => false,
                                }
                            }
                        }
                        Err(e) => {
                            tracing::warn!(
                                automation_id = %automation.id,
                                expression = %expression,
                                "Invalid cron expression, skipping: {}", e
                            );
                            false
                        }
                    }
                }
                ScheduleKind::DurableJobTerminal(job_id) => {
                    match super::durable_jobs::terminal_for_mission(
                        &working_dir,
                        *job_id,
                        mission.id,
                    )
                    .await
                    {
                        Ok(terminal) => terminal,
                        Err(error) => {
                            tracing::debug!(
                                automation_id = %automation.id,
                                mission_id = %mission.id,
                                durable_job_id = %job_id,
                                %error,
                                "Durable-job automation is not ready"
                            );
                            false
                        }
                    }
                }
            };

            if !should_trigger {
                continue;
            }

            // Check if the mission is currently busy (has a running task or queued messages)
            let is_busy = {
                let (tx, rx) = tokio::sync::oneshot::channel();
                if cmd_tx
                    .send(ControlCommand::ListRunning { respond: tx })
                    .await
                    .is_err()
                {
                    tracing::warn!("Failed to send ListRunning command for automation busy check");
                    continue;
                }
                match rx.await {
                    Ok(running) => running.iter().any(|r| {
                        r.mission_id == mission.id
                            && (r.queue_len > 0
                                || matches!(r.state.as_str(), "running" | "waiting_for_tool"))
                    }),
                    Err(_) => {
                        tracing::warn!(
                            "Failed to receive ListRunning response for automation busy check"
                        );
                        continue;
                    }
                }
            };

            if is_busy {
                tracing::debug!(
                    "Mission {} is busy, skipping automation trigger",
                    mission.id
                );
                continue;
            }

            // Get workspace for reading local files
            let workspace = workspaces.get(mission.workspace_id).await;

            // Fetch the command content based on the command source
            let command_content = match &automation.command_source {
                CommandSource::Library { name } => {
                    if let Some(lib) = library.read().await.as_ref() {
                        match lib.get_command(name).await {
                            Ok(command) => automation_library_command_body(&command.content),
                            Err(e) => {
                                tracing::warn!(
                                    "Failed to fetch command '{}' for automation {}: {}",
                                    name,
                                    automation.id,
                                    e
                                );
                                continue;
                            }
                        }
                    } else {
                        tracing::debug!("Library not initialized, skipping automation trigger");
                        continue;
                    }
                }
                CommandSource::LocalFile { path } => {
                    // Read file from mission workspace
                    let file_path = if let Some(ws) = workspace.as_ref() {
                        ws.path.join(path)
                    } else {
                        tracing::warn!(
                            "Workspace {} not found for automation {}",
                            mission.workspace_id,
                            automation.id
                        );
                        continue;
                    };

                    match tokio::fs::read_to_string(&file_path).await {
                        Ok(content) => content,
                        Err(e) => {
                            tracing::warn!(
                                "Failed to read file '{}' for automation {}: {}",
                                file_path.display(),
                                automation.id,
                                e
                            );
                            continue;
                        }
                    }
                }
                CommandSource::Inline { content } => content.clone(),
                CommandSource::NativeLoop { .. } => {
                    // Harness-driven loops iterate via the harness CLI itself,
                    // not the OA scheduler. Skip — the native_loop_observer
                    // records executions when the harness emits goal events.
                    continue;
                }
            };

            // Build substitution context for variable replacement
            let mut context = SubstitutionContext::new(mission.id);
            if let Some(ref title) = mission.title {
                context = context.with_mission_name(title.clone());
            }
            if let Some(ws) = workspace.as_ref() {
                context = context.with_working_directory(ws.path.to_string_lossy().to_string());
            }
            context = context.with_custom_variables(automation.variables.clone());

            // Apply variable substitution
            let substituted_content = substitute_variables(&command_content, &context);

            // Create execution record before execution
            let execution_id = Uuid::new_v4();
            let execution = AutomationExecution {
                id: execution_id,
                automation_id: automation.id,
                mission_id: mission.id,
                triggered_at: mission_store::now_string(),
                trigger_source: match &schedule {
                    ScheduleKind::Interval(_) => "interval",
                    ScheduleKind::Cron { .. } => "cron",
                    ScheduleKind::DurableJobTerminal(_) => "durable_job_terminal",
                }
                .to_string(),
                status: ExecutionStatus::Pending,
                webhook_payload: None,
                variables_used: automation.variables.clone(),
                completed_at: None,
                error: None,
                retry_count: 0,
            };

            let execution = match mission_store.create_automation_execution(execution).await {
                Ok(exec) => exec,
                Err(e) => {
                    tracing::warn!(
                        "Failed to create execution record for automation {}: {}",
                        automation.id,
                        e
                    );
                    continue;
                }
            };

            tracing::info!(
                "Triggering automation {} (execution {}) for mission {}",
                automation.id,
                execution_id,
                mission.id
            );

            // Update execution status to Running
            let mut exec = execution.clone();
            exec.status = ExecutionStatus::Running;
            if let Err(e) = mission_store.update_automation_execution(exec).await {
                tracing::warn!(
                    "Failed to update execution status to running for {}: {}",
                    execution_id,
                    e
                );
            }

            // Send the message to the mission with retry logic
            let mut retry_attempt = 0;
            let max_retries = automation.retry_config.max_retries;
            let base_delay = automation.retry_config.retry_delay_seconds;
            let backoff_multiplier = automation.retry_config.backoff_multiplier;

            loop {
                let message_id = Uuid::new_v4();
                let (respond_tx, _respond_rx) = tokio::sync::oneshot::channel();

                let send_result = cmd_tx
                    .send(ControlCommand::UserMessage {
                        id: message_id,
                        content: substituted_content.clone(),
                        agent: None,
                        target_mission_id: Some(mission.id),
                        strict: false,
                        source: None,
                        respond: respond_tx,
                    })
                    .await;

                match send_result {
                    Ok(_) => {
                        // Message queued successfully – keep execution in Running
                        // status. The actual success/failure will be determined
                        // when the agent finishes processing and
                        // complete_running_executions_for_mission is called.
                        let mut exec = execution.clone();
                        exec.retry_count = retry_attempt;
                        if let Err(e) = mission_store.update_automation_execution(exec).await {
                            tracing::warn!(
                                "Failed to update execution retry count for {}: {}",
                                execution_id,
                                e
                            );
                        }

                        // Update last triggered time
                        if let Err(e) = mission_store
                            .update_automation_last_triggered(automation.id)
                            .await
                        {
                            tracing::warn!(
                                "Failed to update automation last triggered time: {}",
                                e
                            );
                        }

                        // Route response to Telegram if this mission has an
                        // associated Telegram chat (proactive messaging).
                        if let Some(ref bridge) = telegram_bridge {
                            let mission_id = mission.id;
                            let store = Arc::clone(&mission_store);
                            let bridge = Arc::clone(bridge);
                            let tg_events_rx = events_tx.subscribe();
                            tokio::spawn(async move {
                                // Look up the Telegram chat for this mission
                                let chat_mapping = store
                                    .get_telegram_chat_mission_by_mission_id(mission_id)
                                    .await;
                                if let Ok(Some(mapping)) = chat_mapping {
                                    // Find the channel context to get the bot token
                                    if let Some(ctx) =
                                        bridge.get_channel_context(mapping.channel_id).await
                                    {
                                        tracing::info!(
                                            "Routing automation response for mission {} to Telegram chat {}",
                                            mission_id,
                                            mapping.chat_id
                                        );
                                        if let Err(e) = super::telegram::stream_response(
                                            tg_events_rx,
                                            bridge.http(),
                                            &ctx.channel.bot_token,
                                            mapping.chat_id,
                                            0, // no reply_to for proactive messages
                                            None,
                                            mission_id,
                                            Some(Arc::clone(&bridge)),
                                            Some(mapping.channel_id),
                                            Some(Arc::clone(&store)),
                                        )
                                        .await
                                        {
                                            tracing::warn!(
                                                "Failed to stream automation response to Telegram: {}",
                                                e
                                            );
                                        }
                                    }
                                }
                            });
                        }

                        break;
                    }
                    Err(e) => {
                        if retry_attempt < max_retries {
                            // Calculate exponential backoff delay
                            let delay_seconds =
                                base_delay as f64 * backoff_multiplier.powi(retry_attempt as i32);

                            tracing::warn!(
                                "Failed to send automation message (attempt {}/{}): {}. Retrying in {:.1}s",
                                retry_attempt + 1,
                                max_retries + 1,
                                e,
                                delay_seconds
                            );

                            retry_attempt += 1;

                            // Wait before retry
                            tokio::time::sleep(std::time::Duration::from_secs_f64(delay_seconds))
                                .await;
                        } else {
                            // Max retries exceeded - mark as failed
                            tracing::error!(
                                "Failed to send automation message after {} attempts: {}",
                                max_retries + 1,
                                e
                            );

                            let mut exec = execution.clone();
                            exec.status = ExecutionStatus::Failed;
                            exec.completed_at = Some(mission_store::now_string());
                            exec.error =
                                Some(format!("Failed after {} retries: {}", max_retries + 1, e));
                            exec.retry_count = retry_attempt;

                            if let Err(e) = mission_store.update_automation_execution(exec).await {
                                tracing::warn!(
                                    "Failed to update execution status to failed for {}: {}",
                                    execution_id,
                                    e
                                );
                            }

                            break;
                        }
                    }
                }
            }
        }
    }
}

/// Keep automation library command execution consistent with `/command` usage:
/// frontmatter is metadata and should never be injected into model prompts.
fn automation_library_command_body(command_content: &str) -> String {
    let (_frontmatter, body) = crate::library::types::parse_frontmatter(command_content);
    body.trim().to_string()
}

/// Resolve the command content for a single automation, applying variable
/// substitution.  Returns `None` if the command cannot be resolved (e.g.
/// library unavailable, file not found).
async fn resolve_automation_command(
    automation: &mission_store::Automation,
    mission_id: Uuid,
    state: &Arc<AppState>,
    store: &Arc<dyn MissionStore>,
) -> Option<String> {
    use super::automation_variables::{substitute_variables, SubstitutionContext};
    use super::mission_store::CommandSource;

    let mission = store.get_mission(mission_id).await.ok()??;
    let workspace = state.workspaces.get(mission.workspace_id).await;

    let command_content = match &automation.command_source {
        CommandSource::Library { name } => {
            let lib = state.library.read().await;
            let lib = lib.as_ref()?;
            lib.get_command(name)
                .await
                .ok()
                .map(|c| automation_library_command_body(&c.content))?
        }
        CommandSource::LocalFile { path } => {
            let ws = workspace.as_ref()?;
            tokio::fs::read_to_string(ws.path.join(path)).await.ok()?
        }
        CommandSource::Inline { content } => content.clone(),
        CommandSource::NativeLoop { .. } => return None,
    };

    let mut context = SubstitutionContext::new(mission.id);
    if let Some(ref title) = mission.title {
        context = context.with_mission_name(title.clone());
    }
    if let Some(ws) = workspace.as_ref() {
        context = context.with_working_directory(ws.path.to_string_lossy().to_string());
    }
    context = context.with_custom_variables(automation.variables.clone());

    Some(substitute_variables(&command_content, &context))
}

#[derive(Debug, Clone)]
struct RoutedAutomationMessage {
    content: String,
    target_mission_id: Uuid,
}

fn enqueue_agent_finished_messages(
    queue: &mut VecDeque<ControlQueueEntry>,
    messages: Vec<RoutedAutomationMessage>,
) {
    for message in messages {
        queue.push_back((
            Uuid::new_v4(),
            message.content,
            None,
            Some(message.target_mission_id),
            Some("automation".to_string()),
        ));
    }
}

/// Backend id for a mission, or `None` if the mission isn't found.
///
/// Used by [`maybe_begin_grok_goal`] / [`post_turn_handle_grok_goal`] to
/// gate the `/goal` loop behavior on backend identity without having to
/// thread the backend id through every queue-dispatch path.
async fn lookup_mission_backend(
    mission_store: &Arc<dyn MissionStore>,
    mission_id: Uuid,
) -> Option<String> {
    match mission_store.get_mission(mission_id).await {
        Ok(Some(m)) => Some(m.backend),
        _ => None,
    }
}

/// Outcome of [`maybe_begin_grok_goal`]: either a rewritten first-turn
/// prompt (the message should now carry this content) or a user-facing
/// error to surface in the message ack.
pub(crate) enum GrokGoalKickoff {
    /// Not a grok-goal request; queue the original content unchanged.
    Passthrough,
    /// `/goal X` accepted; queue `prompt` (the wrapped first-turn prompt)
    /// in place of the original message content.
    Rewritten { prompt: String },
    /// `/goal X` rejected — surface this string to the user.
    Rejected { reason: String },
}

/// Detect `/goal <objective>` for a grok mission and, if recognised,
/// create the AgentFinished-driven automation row that will iterate the
/// loop. Returns the wrapped first-turn prompt to use in place of the
/// raw `/goal X` message.
///
/// Non-grok backends fall through unchanged — claudecode and codex have
/// their own `/goal` handling (CLI-native and `thread/goal/set`
/// respectively); only grok needs sandboxed.sh to drive iteration.
async fn maybe_begin_grok_goal(
    mission_store: &Arc<dyn MissionStore>,
    events_tx: &broadcast::Sender<AgentEvent>,
    mission_id: Option<Uuid>,
    content: &str,
) -> GrokGoalKickoff {
    let (is_goal, objective) = super::grok_goal::parse_goal_prefix(content);
    if !is_goal {
        return GrokGoalKickoff::Passthrough;
    }
    let Some(mid) = mission_id else {
        // No target mission resolved yet (auto-create path) — let the
        // normal flow create a mission, then we'll catch the next turn.
        // For now treat as passthrough; the user can re-send `/goal X`
        // once the mission exists. This avoids a chicken/egg with
        // mission creation happening *after* this hook.
        return GrokGoalKickoff::Passthrough;
    };
    if !matches!(
        lookup_mission_backend(mission_store, mid).await.as_deref(),
        Some("grok")
    ) {
        return GrokGoalKickoff::Passthrough;
    }
    if objective.is_empty() {
        return GrokGoalKickoff::Rejected {
            reason: "/goal requires an objective (e.g. `/goal write the docs`)".to_string(),
        };
    }
    if super::grok_goal::active_goal_for_mission(mission_store, mid)
        .await
        .is_some()
    {
        return GrokGoalKickoff::Rejected {
            reason: "this mission already has an active /goal loop — wait for it to finish or cancel before starting a new one".to_string(),
        };
    }
    if let Err(e) = super::grok_goal::create_goal_automation(mission_store, mid, &objective).await {
        tracing::warn!(
            "grok_goal: failed to create automation for mission {}: {}",
            mid,
            e
        );
        return GrokGoalKickoff::Rejected {
            reason: format!("failed to set up /goal loop: {}", e),
        };
    }
    tracing::info!(
        mission_id = %mid,
        objective_len = objective.len(),
        "grok_goal: started loop"
    );
    let _ = events_tx.send(AgentEvent::GoalIteration {
        iteration: 1,
        objective: objective.clone(),
        mission_id: Some(mid),
    });
    GrokGoalKickoff::Rewritten {
        prompt: super::grok_goal::first_turn_prompt(&objective),
    }
}

/// Post-turn hook for grok-goal missions. Parses the sentinel from the
/// assistant's final text and either ends the loop (terminal sentinel,
/// budget exhausted, sentinel-missing streak, or explicit cancellation)
/// or bumps the iteration counter so the existing AgentFinished hook
/// re-fires the continuation prompt.
///
/// `terminal_reason` is the runner's structured exit reason. A `Cancelled`
/// turn ends the loop immediately with status `aborted:cancelled` —
/// otherwise the cancelled output (typically the literal string
/// `"Cancelled"`) would look like a sentinel-missing turn and burn through
/// the missing-count budget before the loop tore down.
async fn post_turn_handle_grok_goal(
    mission_store: &Arc<dyn MissionStore>,
    events_tx: &broadcast::Sender<AgentEvent>,
    mission_id: Uuid,
    assistant_text: &str,
    terminal_reason: Option<TerminalReason>,
) {
    let Some(mut row) = super::grok_goal::active_goal_for_mission(mission_store, mission_id).await
    else {
        return;
    };
    let objective = super::grok_goal::objective_of(&row);
    let iteration = super::grok_goal::iteration_of(&row);
    let prev_missing = super::grok_goal::missing_count_of(&row);

    // Cancellation short-circuits sentinel parsing — there's no agent
    // output to interpret and continuing the loop would re-fire prompts
    // after the user explicitly stopped the mission.
    if matches!(terminal_reason, Some(TerminalReason::Cancelled)) {
        if let Err(e) = super::grok_goal::disable_goal(mission_store, &mut row).await {
            tracing::warn!("grok_goal: disable_goal failed: {}", e);
        }
        let _ = events_tx.send(AgentEvent::GoalStatus {
            status: "aborted:cancelled".to_string(),
            objective,
            mission_id: Some(mission_id),
        });
        return;
    }

    let sentinel = super::grok_goal::parse_goal_sentinel(assistant_text);
    tracing::info!(
        mission_id = %mission_id,
        iteration,
        prev_missing,
        ?sentinel,
        "grok_goal: post-turn sentinel"
    );
    match sentinel {
        super::grok_goal::GoalSentinel::Complete => {
            if let Err(e) = super::grok_goal::record_decision(
                mission_store,
                &mut row,
                &sentinel,
                "complete",
                "high",
            )
            .await
            {
                tracing::warn!("grok_goal: record_decision failed: {}", e);
            }
            if let Err(e) = super::grok_goal::disable_goal(mission_store, &mut row).await {
                tracing::warn!("grok_goal: disable_goal failed: {}", e);
            }
            let _ = events_tx.send(AgentEvent::GoalStatus {
                status: "complete".to_string(),
                objective,
                mission_id: Some(mission_id),
            });
        }
        super::grok_goal::GoalSentinel::Aborted { ref reason } => {
            if let Err(e) = super::grok_goal::record_decision(
                mission_store,
                &mut row,
                &sentinel,
                "aborted",
                "high",
            )
            .await
            {
                tracing::warn!("grok_goal: record_decision failed: {}", e);
            }
            if let Err(e) = super::grok_goal::disable_goal(mission_store, &mut row).await {
                tracing::warn!("grok_goal: disable_goal failed: {}", e);
            }
            let _ = events_tx.send(AgentEvent::GoalStatus {
                status: format!("aborted:{}", reason),
                objective,
                mission_id: Some(mission_id),
            });
        }
        super::grok_goal::GoalSentinel::Continue | super::grok_goal::GoalSentinel::Missing => {
            let was_missing = matches!(sentinel, super::grok_goal::GoalSentinel::Missing);
            let new_missing = if was_missing {
                prev_missing.saturating_add(1)
            } else {
                0
            };
            if new_missing >= super::grok_goal::MAX_MISSING_SENTINELS {
                if let Err(e) = super::grok_goal::record_decision(
                    mission_store,
                    &mut row,
                    &sentinel,
                    "aborted:no_goal_sentinel",
                    "low",
                )
                .await
                {
                    tracing::warn!("grok_goal: record_decision failed: {}", e);
                }
                if let Err(e) = super::grok_goal::disable_goal(mission_store, &mut row).await {
                    tracing::warn!("grok_goal: disable_goal failed: {}", e);
                }
                let _ = events_tx.send(AgentEvent::GoalStatus {
                    status: "aborted:no_goal_sentinel".to_string(),
                    objective,
                    mission_id: Some(mission_id),
                });
                return;
            }
            let next_iter = iteration.saturating_add(1);
            if next_iter > super::grok_goal::MAX_ITERATIONS {
                if let Err(e) = super::grok_goal::record_decision(
                    mission_store,
                    &mut row,
                    &sentinel,
                    "budget_limited",
                    "medium",
                )
                .await
                {
                    tracing::warn!("grok_goal: record_decision failed: {}", e);
                }
                if let Err(e) = super::grok_goal::disable_goal(mission_store, &mut row).await {
                    tracing::warn!("grok_goal: disable_goal failed: {}", e);
                }
                let _ = events_tx.send(AgentEvent::GoalStatus {
                    status: "budget_limited".to_string(),
                    objective,
                    mission_id: Some(mission_id),
                });
                return;
            }
            if let Err(e) =
                super::grok_goal::update_counters(mission_store, &mut row, next_iter, new_missing)
                    .await
            {
                tracing::warn!("grok_goal: update_counters failed: {}", e);
            }
            let decision = if was_missing {
                "continue:missing_sentinel"
            } else {
                "continue"
            };
            if let Err(e) = super::grok_goal::record_decision(
                mission_store,
                &mut row,
                &sentinel,
                decision,
                if was_missing { "low" } else { "high" },
            )
            .await
            {
                tracing::warn!("grok_goal: record_decision failed: {}", e);
            }
            let _ = events_tx.send(AgentEvent::GoalIteration {
                iteration: next_iter,
                objective,
                mission_id: Some(mission_id),
            });
        }
    }
}

fn queue_has_pending_target_mission(queue: &VecDeque<ControlQueueEntry>, mission_id: Uuid) -> bool {
    queue
        .iter()
        .any(|(_id, _msg, _agent, target_mid, _source)| *target_mid == Some(mission_id))
}

fn accept_user_message_id(accepted: &mut HashSet<Uuid>, id: Uuid) -> bool {
    accepted.insert(id)
}

fn mission_status_for_terminal_reason(
    reason: TerminalReason,
    complete_turn_without_follow_up: bool,
) -> Option<(MissionStatus, &'static str)> {
    match reason {
        TerminalReason::TurnComplete if complete_turn_without_follow_up => {
            // Agent finished its turn cleanly and there is no queued follow-up
            // message or scheduled wakeup — the mission is parked waiting for
            // the user to read it. The dashboard / iOS clients surface this in
            // the "Needs You" column. An explicit `TerminalReason::Completed`
            // (the path below) is used when the agent declares the work fully
            // done, not just a turn boundary.
            Some((MissionStatus::AwaitingUser, "turn_complete"))
        }
        TerminalReason::TurnComplete => None,
        TerminalReason::Completed => Some((MissionStatus::Completed, "completed")),
        TerminalReason::Cancelled => Some((MissionStatus::Interrupted, "cancelled")),
        TerminalReason::ServerShutdown => Some((MissionStatus::Interrupted, "server_shutdown")),
        TerminalReason::MaxIterations => Some((MissionStatus::Blocked, "max_iterations")),
        TerminalReason::LlmError => Some((MissionStatus::Failed, "llm_error")),
        TerminalReason::Stalled => Some((MissionStatus::Failed, "stalled")),
        TerminalReason::InfiniteLoop => Some((MissionStatus::Failed, "infinite_loop")),
        TerminalReason::RateLimited => Some((MissionStatus::Failed, "rate_limited")),
        TerminalReason::CapacityLimited => Some((MissionStatus::Failed, "capacity_limited")),
        TerminalReason::AuthError => Some((MissionStatus::Failed, "auth_error")),
    }
}

/// Classify *why* a mission is parking in `AwaitingUser` by inspecting the last
/// assistant message: a trailing question (or interrogative phrasing) means the
/// agent needs a `Decision`; anything else means it finished its turn / work and
/// is waiting for an `Ack`. This is a heuristic — consumers (Paloma) can refine
/// it — but it is far better than the old all-`awaiting_user`-is-the-same signal.
///
/// Prefer [`classify_awaiting_kind_text`] with the just-completed turn's output
/// when available: mission history is derived from the event log, which can lag
/// behind the in-hand turn output at finalization time.
fn classify_awaiting_kind(history: &[MissionHistoryEntry]) -> AwaitingKind {
    match history.iter().rev().find(|entry| entry.role == "assistant") {
        Some(last) => classify_awaiting_kind_text(&last.content),
        // No assistant text to read (e.g. tool-only turn) — default to Ack so a
        // "done" turn doesn't masquerade as an open question.
        None => AwaitingKind::Ack,
    }
}

/// Heuristic core of [`classify_awaiting_kind`], operating on a raw assistant
/// message string (the authoritative turn output).
fn classify_awaiting_kind_text(text: &str) -> AwaitingKind {
    let text = text.trim();
    if text.is_empty() {
        return AwaitingKind::Ack;
    }

    // Only look at the tail of the message — the closing lines carry the intent
    // (a long answer that ends with "Want me to proceed?" is a decision).
    let tail: String = text.chars().rev().take(600).collect::<String>();
    let tail: String = tail.chars().rev().collect();
    let lower = tail.to_lowercase();

    let ends_with_question = tail.trim_end().ends_with('?');
    // Interrogative / approval-seeking lead-ins that signal an open decision even
    // when the literal '?' lands earlier than the very last character.
    const DECISION_CUES: &[&str] = &[
        "should i ",
        "shall i ",
        "do you want",
        "would you like",
        "which option",
        "which one",
        "let me know",
        "how would you like",
        "what would you like",
        "can you confirm",
        "please confirm",
        "your call",
        "proceed?",
        "go ahead?",
    ];
    let has_cue = DECISION_CUES.iter().any(|cue| lower.contains(cue));

    if ends_with_question || has_cue {
        AwaitingKind::Decision
    } else {
        AwaitingKind::Ack
    }
}

fn mission_status_summary_for_terminal_reason(reason: TerminalReason) -> Option<String> {
    match reason {
        TerminalReason::TurnComplete | TerminalReason::Completed => None,
        TerminalReason::MaxIterations => Some("Reached iteration limit".to_string()),
        TerminalReason::Cancelled => Some("Cancelled by user".to_string()),
        TerminalReason::ServerShutdown => {
            Some("Paused for server restart — click Resume to continue".to_string())
        }
        TerminalReason::Stalled => Some("No progress detected".to_string()),
        TerminalReason::InfiniteLoop => Some("Detected repetitive behavior".to_string()),
        TerminalReason::LlmError => Some("Model error".to_string()),
        TerminalReason::RateLimited => Some("Provider rate limited".to_string()),
        TerminalReason::CapacityLimited => Some("Provider capacity limit reached".to_string()),
        TerminalReason::AuthError => Some("Authentication failed".to_string()),
    }
}

fn parse_goal_objective(message: &str) -> Option<String> {
    // Accept any whitespace after the command ("/goal x", "/goal\nx"), but
    // not other slash commands sharing the prefix ("/goals").
    let rest = message.trim_start().strip_prefix("/goal")?;
    if !rest.starts_with(char::is_whitespace) {
        return None;
    }
    let objective = rest.trim();
    (!objective.is_empty()).then(|| objective.to_string())
}

/// Canonical `/goal <objective>` form for a goal message, or `None` when the
/// message is not a goal command. The backend goal drivers (codex
/// `parse_goal_prefix`, grok, opencode) only recognise the space-separated
/// form, while `parse_goal_objective` accepts any whitespace after the
/// command — normalising at the choke points keeps every downstream parser in
/// agreement without teaching each one about `/goal\n`.
fn canonical_goal_message(message: &str) -> Option<String> {
    parse_goal_objective(message).map(|objective| format!("/goal {objective}"))
}

/// If the turn ended with `LlmError` or `AuthError` but the agent produced
/// substantive output, downgrade the reason to `TurnComplete` so the mission
/// stays active and can be picked up by the next automation cycle or user
/// message.  This prevents transient backend errors (e.g. Codex "Failed to
/// shutdown rollout recorder", or Claude Code exiting with code 1 after a
/// successful turn that happens to contain an auth-error string in its
/// output) from killing missions that actually completed their work.
fn maybe_recover_soft_llm_error(result: &mut crate::agents::AgentResult) {
    let is_recoverable = matches!(
        result.terminal_reason,
        Some(
            TerminalReason::LlmError
                | TerminalReason::AuthError
                | TerminalReason::RateLimited
                | TerminalReason::CapacityLimited
        )
    );
    if !is_recoverable {
        return;
    }
    // Structured transport failures are never successful turns. Treating
    // either the Claude marker or the generic/Codex stage as TurnComplete
    // would erase the failure evidence before bounded auto-resume runs.
    let has_transport_failure = result.data.as_ref().is_some_and(|data| {
        data.get("claudecode_transport_failure").is_some()
            || data.get("transport_failure_stage").is_some()
    });
    // A backend that supplied an explicit failure class has already made a
    // structured terminal decision. Its human-readable error text must never
    // be reinterpreted as substantive assistant output by this legacy
    // heuristic (for example, a ChatGPT UI selector compatibility failure).
    let has_structured_failure = result.data.as_ref().is_some_and(|data| {
        data.get("failure_class")
            .is_some_and(|failure_class| !failure_class.is_null())
    });
    if has_transport_failure || has_structured_failure {
        return;
    }
    let output = result.output.trim();
    // Only recover when we have real content — not just an error message.
    // Heuristic: at least 20 chars and doesn't look like a bare error.
    if output.len() >= 20
        && !output.starts_with("Codex produced no output")
        && !output.starts_with("Codex CLI produced no JSON")
        && !output.starts_with("Codex CLI exited before completing the turn")
        && !output.starts_with("No response from")
        && !output.starts_with("Claude Code error:")
        && !output.starts_with("Claude Code produced no")
        && !output.starts_with("Claude Code emitted malformed")
        && !output.starts_with("Claude Code ended before startup")
        && !output.starts_with("Claude Code exited without")
        && !output.starts_with("Claude Code stopped producing output")
        && !output.starts_with("No Claude Code credentials detected")
        && !super::mission_runner::is_rate_limited_error(output)
        && !super::mission_runner::is_capacity_limited_error(output)
        && !super::mission_runner::is_auth_error(output)
        && !is_bare_llm_error_output(output)
    {
        tracing::info!(
            output_len = output.len(),
            reason = ?result.terminal_reason,
            "Recovering from soft error: agent produced valid output, upgrading to TurnComplete"
        );
        result.success = true;
        result.terminal_reason = Some(TerminalReason::TurnComplete);
    }
}

fn completion_evidence_for_agent_result(
    result: &crate::agents::AgentResult,
) -> crate::agents::CompletionEvidence {
    use crate::agents::{CompletionConfidence, CompletionEvidence, CompletionSignal, FailureClass};

    let terminal_reason = result.terminal_reason;
    let data = result.data.as_ref();
    let native_terminal_seen = data
        .and_then(|v| v.get("native_terminal_seen"))
        .and_then(|v| v.as_bool())
        .unwrap_or(matches!(
            terminal_reason,
            Some(TerminalReason::TurnComplete | TerminalReason::Completed)
        ));
    let pending_tools = data.and_then(|v| v.get("pending_tools")).and_then(|value| {
        value
            .as_u64()
            .and_then(|count| usize::try_from(count).ok())
            .or_else(|| value.as_array().map(Vec::len))
    });
    let transport_failure_stage = data
        .and_then(|v| v.get("transport_failure_stage"))
        .or_else(|| data.and_then(|v| v.get("claudecode_transport_failure")))
        .and_then(|v| v.as_str())
        .map(ToString::to_string);
    let provider_error_source = data
        .and_then(|v| v.get("provider_error_source"))
        .or_else(|| data.and_then(|v| v.get("error_source")))
        .and_then(|v| v.as_str())
        .map(ToString::to_string);

    let failure_class_from_data = data
        .and_then(|v| v.get("failure_class"))
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .flatten();
    let failure_class = failure_class_from_data.or(match terminal_reason {
        Some(TerminalReason::AuthError) => Some(FailureClass::AuthError),
        Some(TerminalReason::RateLimited) => Some(FailureClass::RateLimited),
        Some(TerminalReason::CapacityLimited) => Some(FailureClass::CapacityLimited),
        Some(TerminalReason::LlmError) if transport_failure_stage.is_some() => {
            Some(FailureClass::TransportError)
        }
        Some(TerminalReason::LlmError) => Some(FailureClass::ProviderError),
        Some(
            TerminalReason::Stalled | TerminalReason::InfiniteLoop | TerminalReason::MaxIterations,
        ) => Some(FailureClass::AgentError),
        _ => None,
    });

    let completion_signal_from_data = data
        .and_then(|v| v.get("completion_signal"))
        .and_then(|v| serde_json::from_value(v.clone()).ok());
    let completion_signal = completion_signal_from_data.unwrap_or(match terminal_reason {
        Some(TerminalReason::TurnComplete | TerminalReason::Completed) if native_terminal_seen => {
            CompletionSignal::NativeTerminal
        }
        Some(TerminalReason::TurnComplete | TerminalReason::Completed) => {
            CompletionSignal::TextFallback
        }
        Some(_) => CompletionSignal::ProcessExit,
        None => CompletionSignal::Unknown,
    });
    let completion_confidence_from_data = data
        .and_then(|v| v.get("completion_confidence"))
        .and_then(|v| serde_json::from_value(v.clone()).ok());
    let completion_confidence =
        completion_confidence_from_data.unwrap_or(match completion_signal {
            CompletionSignal::NativeTerminal => CompletionConfidence::High,
            CompletionSignal::SessionIdle => CompletionConfidence::Medium,
            CompletionSignal::ProcessExit | CompletionSignal::TextFallback => {
                if result.success {
                    CompletionConfidence::Low
                } else {
                    CompletionConfidence::High
                }
            }
            CompletionSignal::RecoveredSoftError => CompletionConfidence::Low,
            CompletionSignal::Unknown => CompletionConfidence::Low,
        });
    let classification_source = data
        .and_then(|v| v.get("classification_source"))
        .and_then(|v| v.as_str())
        .unwrap_or(match completion_signal {
            CompletionSignal::TextFallback | CompletionSignal::RecoveredSoftError => {
                "text_fallback"
            }
            CompletionSignal::Unknown => "unknown",
            _ => "structured",
        });

    CompletionEvidence {
        terminal_reason,
        completion_signal,
        completion_confidence,
        native_terminal_seen,
        pending_tools,
        transport_failure_stage,
        provider_error_source,
        failure_class,
        classification_source: classification_source.to_string(),
    }
}

fn is_transport_failure_evidence(evidence: &crate::agents::CompletionEvidence) -> bool {
    matches!(
        evidence.failure_class,
        Some(crate::agents::FailureClass::TransportError)
    )
}

fn is_bare_llm_error_output(output: &str) -> bool {
    if looks_like_structured_provider_error(output) {
        return true;
    }
    if super::mission_runner::is_provider_payload_error(output) {
        return true;
    }

    let normalized = output
        .trim()
        .trim_matches(|c: char| matches!(c, '.' | '!' | '"' | '\''))
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_ascii_lowercase();

    if normalized.is_empty() {
        return false;
    }

    matches!(
        normalized.as_str(),
        "internal server error"
            | "invalid authentication credentials"
            | "no claude code credentials detected"
            | "unknown error"
            | "service unavailable"
            | "bad gateway"
            | "gateway timeout"
            | "request timeout"
            | "upstream error"
            | "model error"
    ) || normalized.starts_with("api error:")
        || normalized.starts_with("anthropic api error:")
        || normalized.starts_with("claude code error:")
        // Claude Code's canonical auth-failure surface: the CLI prints
        // `Failed to authenticate. API Error: 401 ...` when Anthropic
        // rejects the request mid-turn. Without this pattern the
        // short auth-error string slipped past
        // `maybe_recover_soft_llm_error` and got fake-promoted to
        // TurnComplete, hiding rotation exhaustion from the UI.
        || normalized.starts_with("failed to authenticate")
        // Any short output whose only substantive content is an auth
        // HTTP status from Anthropic/OpenAI — catches phrasings like
        // `<some prefix>. API Error: 401 ...` without needing to
        // enumerate the prefix.
        || (normalized.len() < 200
            && (normalized.contains("api error: 401")
                || normalized.contains("api error: 403")
                || normalized.contains("api error: 407")))
        // Codex / ChatGPT-OAuth refresh-token reuse surfaces as a short
        // user-visible string. Without these the soft-error recovery
        // fake-promoted the mission to TurnComplete after rotation had
        // already exhausted every configured account, hiding the real
        // failure from the UI.
        || (normalized.len() < 400
            && (normalized.contains("refresh token was already used")
                || normalized.contains("refresh_token_reused")
                || normalized.contains("please log out and sign in again")))
}

fn looks_like_structured_provider_error(output: &str) -> bool {
    let trimmed = output.trim();
    if !(trimmed.starts_with('{') && trimmed.ends_with('}')) {
        return false;
    }

    let lower = trimmed.to_ascii_lowercase();
    let has_error_shape = lower.contains("\"detail\"")
        || lower.contains("\"error\"")
        || lower.contains("\"message\"")
        || lower.contains("\"type\"");
    if !has_error_shape {
        return false;
    }

    lower.contains("invalid_request_error")
        || lower.contains("model is not supported")
        || lower.contains("not supported when using codex")
        || lower.contains("does not exist or you do not have access")
        || lower.contains("invalid authentication credentials")
        || lower.contains("rate limit")
        || lower.contains("capacity")
        || lower.contains("service unavailable")
        || lower.contains("internal server error")
}

#[allow(clippy::too_many_arguments)]
async fn maybe_finalize_terminal_mission(
    mission_store: &Arc<dyn MissionStore>,
    events_tx: &tokio::sync::broadcast::Sender<AgentEvent>,
    mission_id: Uuid,
    terminal_reason: Option<TerminalReason>,
    // What the terminating guard observed, from AgentResult::terminal_evidence.
    terminal_evidence: Option<&str>,
    completion_confidence: Option<crate::agents::CompletionConfidence>,
    complete_turn_without_follow_up: bool,
    // The just-completed turn's assistant output, if available. Used to classify
    // `awaiting_kind` authoritatively — the mission's event-log-derived history
    // can lag behind at finalization time.
    final_output: Option<&str>,
    log_context: &str,
) {
    let Some(reason) = terminal_reason else {
        return;
    };
    let Some((new_status, terminal_reason_str)) =
        mission_status_for_terminal_reason(reason, complete_turn_without_follow_up)
    else {
        tracing::debug!(
            mission_id = %mission_id,
            reason = ?reason,
            context = log_context,
            "Skipping mission finalization for non-terminal turn state"
        );
        return;
    };

    match mission_store.get_mission(mission_id).await {
        Ok(Some(mission)) => {
            if mission.status == MissionStatus::Interrupted {
                // A turn that *succeeds* after the interruption marker was set
                // (deploy restart mid-turn, then the drained turn completes)
                // supersedes it: there is a fresh assistant answer, and leaving
                // the mission "interrupted" makes the dashboard offer a resume
                // that the still-registered runner rejects with "already
                // running". Failure-shaped reasons keep the interrupted status
                // (it is the more accurate cause).
                let successful_turn = matches!(
                    new_status,
                    MissionStatus::AwaitingUser | MissionStatus::Completed
                );
                if !successful_turn {
                    tracing::debug!(
                        mission_id = %mission_id,
                        reason = ?reason,
                        context = log_context,
                        "Skipping mission finalization because mission is already interrupted"
                    );
                    return;
                }
                tracing::info!(
                    mission_id = %mission_id,
                    reason = ?reason,
                    new_status = ?new_status,
                    context = log_context,
                    "Promoting interrupted mission: turn completed successfully after interruption"
                );
            }

            // Interrupted is allowed through: the promotion check above already
            // filtered it down to successful turns only.
            if !matches!(
                mission.status,
                MissionStatus::Active | MissionStatus::Pending | MissionStatus::Interrupted
            ) {
                tracing::debug!(
                    mission_id = %mission_id,
                    status = ?mission.status,
                    context = log_context,
                    "Skipping mission finalization because mission already has terminal status"
                );
                return;
            }

            if new_status == MissionStatus::Completed
                && completion_confidence == Some(crate::agents::CompletionConfidence::Low)
            {
                tracing::info!(
                    mission_id = %mission_id,
                    reason = ?reason,
                    context = log_context,
                    "Skipping mission completion because completion evidence is low confidence"
                );
                return;
            }

            if new_status == MissionStatus::Completed
                && mission_has_active_automation(mission_store, mission_id).await
            {
                tracing::info!(
                    mission_id = %mission_id,
                    context = log_context,
                    "Skipping mission completion because active automations are enabled"
                );
                return;
            }

            // Assistant missions (e.g. Telegram-linked) should stay active
            // after each reply — they are long-lived by design.
            if new_status == MissionStatus::Completed
                && mission.mission_mode == super::mission_store::MissionMode::Assistant
            {
                tracing::debug!(
                    mission_id = %mission_id,
                    context = log_context,
                    "Skipping mission completion for assistant-mode mission"
                );
                return;
            }

            tracing::info!(
                mission_id = %mission_id,
                status = ?new_status,
                reason = ?reason,
                context = log_context,
                "Finalizing mission after terminal turn"
            );
            // Classify the awaiting reason now (uses the in-hand turn output;
            // falls back to history only when the caller didn't supply it, since
            // the event log can lag the turn). Applied *after* a successful
            // status write below so a failed write can't orphan awaiting_kind on
            // a mission that never became AwaitingUser.
            let awaiting_kind = if new_status == MissionStatus::AwaitingUser {
                Some(match final_output {
                    Some(text) if !text.trim().is_empty() => classify_awaiting_kind_text(text),
                    _ => classify_awaiting_kind(&mission.history),
                })
            } else {
                None
            };

            if let Some(evidence) = terminal_evidence.filter(|e| !e.trim().is_empty()) {
                // Best-effort by contract: failing to record evidence must
                // never turn into failing to terminate.
                if let Err(e) = mission_store
                    .set_terminal_evidence(mission_id, evidence)
                    .await
                {
                    tracing::warn!(mission_id = %mission_id, "failed to record terminal evidence: {e}");
                }
            }
            if let Err(e) = mission_store
                .update_mission_status_with_reason(
                    mission_id,
                    new_status,
                    Some(terminal_reason_str),
                )
                .await
            {
                tracing::warn!(
                    mission_id = %mission_id,
                    context = log_context,
                    "Failed to finalize mission after terminal turn: {}",
                    e
                );
            } else {
                // Set awaiting_kind after the status is committed to AwaitingUser
                // and before emitting the event the Paloma webhook keys on, so
                // the webhook sees it without risking an orphan on write failure.
                if let Some(kind) = awaiting_kind {
                    if let Err(e) = mission_store
                        .set_mission_awaiting_kind(mission_id, Some(kind))
                        .await
                    {
                        tracing::warn!(
                            mission_id = %mission_id,
                            context = log_context,
                            "Failed to set awaiting_kind: {}",
                            e
                        );
                    }
                }

                maybe_schedule_mission_metadata_refresh_for_status(
                    mission_store,
                    events_tx,
                    mission_id,
                    new_status,
                );
                let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                    mission_id,
                    status: new_status,
                    summary: mission_status_summary_for_terminal_reason(reason),
                });

                // Stall-guard: orchestrators that park in awaiting_user with no
                // wakeup armed can't resume themselves — arm a bounded fallback.
                if new_status == MissionStatus::AwaitingUser {
                    maybe_arm_stall_guard_wakeup(mission_store, mission_id).await;
                }
            }
        }
        Ok(None) => {
            tracing::warn!(
                mission_id = %mission_id,
                context = log_context,
                "Mission not found for terminal finalization"
            );
        }
        Err(e) => {
            tracing::warn!(
                mission_id = %mission_id,
                context = log_context,
                "Failed to load mission for terminal finalization: {}",
                e
            );
        }
    }
}

fn next_session_id_from_automation_variables(
    automation: &super::mission_store::Automation,
) -> Option<Uuid> {
    let raw = automation.variables.get("nextSessionId")?.trim();
    if raw.is_empty() {
        return None;
    }
    Uuid::parse_str(raw).ok()
}

fn resolve_agent_finished_target_mission(
    source_mission_id: Uuid,
    source_mission_status: MissionStatus,
    automation: &super::mission_store::Automation,
) -> Uuid {
    if source_mission_status == MissionStatus::Completed
        && automation.fresh_session == mission_store::FreshSession::Switch
    {
        if let Some(next_id) = next_session_id_from_automation_variables(automation) {
            return next_id;
        }

        tracing::warn!(
            "Automation {} is in switch mode but has no valid nextSessionId variable; falling back to mission {}",
            automation.id,
            source_mission_id
        );
    }

    source_mission_id
}

async fn agent_finished_automation_messages(
    mission_store: &Arc<dyn MissionStore>,
    mission_id: Uuid,
    library: &SharedLibrary,
    workspaces: &workspace::SharedWorkspaceStore,
) -> Vec<RoutedAutomationMessage> {
    use super::automation_variables::{substitute_variables, SubstitutionContext};
    use super::mission_store::{AutomationExecution, CommandSource, ExecutionStatus, TriggerType};

    let automations = match mission_store.get_mission_automations(mission_id).await {
        Ok(list) => list,
        Err(e) => {
            tracing::warn!(
                "Failed to load automations for mission {} (agent_finished hook): {}",
                mission_id,
                e
            );
            return Vec::new();
        }
    };

    let mut active: Vec<super::mission_store::Automation> = automations
        .into_iter()
        .filter(|a| a.active && matches!(a.trigger, TriggerType::AgentFinished))
        .collect();

    if active.is_empty() {
        return Vec::new();
    }

    let mission = match mission_store.get_mission(mission_id).await {
        Ok(Some(m)) => m,
        Ok(None) => return Vec::new(),
        Err(e) => {
            tracing::warn!(
                "Failed to load mission {} for agent_finished automations: {}",
                mission_id,
                e
            );
            return Vec::new();
        }
    };

    let mut eligible = Vec::with_capacity(active.len());
    for automation in active {
        let consecutive_failures =
            consecutive_failure_count_for_automation(mission_store, &automation).await;
        let has_fired = if matches!(
            automation.stop_policy,
            mission_store::StopPolicy::AfterFirstFire
        ) {
            automation_has_fired(mission_store, automation.id).await
        } else {
            false
        };

        if stop_policy_matches_status(
            &automation.stop_policy,
            mission.status,
            consecutive_failures,
            has_fired,
        )
        .await
        {
            tracing::info!(
                "Disabling agent_finished automation {} due to stop policy {:?} (mission {} status {:?})",
                automation.id,
                automation.stop_policy,
                mission.id,
                mission.status
            );
            let mut updated = automation.clone();
            updated.active = false;
            if let Err(e) = mission_store.update_automation(updated).await {
                tracing::warn!(
                    "Failed to disable automation {} after stop policy match: {}",
                    automation.id,
                    e
                );
            }
            continue;
        }
        eligible.push(automation);
    }
    active = eligible;

    if active.is_empty() {
        return Vec::new();
    }

    // Stable ordering to avoid surprising changes in multi-automation setups.
    active.sort_by_key(|a| a.created_at.clone());

    let workspace = workspaces.get(mission.workspace_id).await;

    let mut out = Vec::with_capacity(active.len());

    for automation in active {
        // Fetch the command content based on the command source
        let command_content = match &automation.command_source {
            CommandSource::Library { name } => {
                if let Some(lib) = library.read().await.as_ref() {
                    match lib.get_command(name).await {
                        Ok(command) => automation_library_command_body(&command.content),
                        Err(e) => {
                            tracing::warn!(
                                "Failed to fetch command '{}' for automation {}: {}",
                                name,
                                automation.id,
                                e
                            );
                            continue;
                        }
                    }
                } else {
                    tracing::debug!(
                        "Library not initialized, skipping agent_finished automation trigger"
                    );
                    continue;
                }
            }
            CommandSource::LocalFile { path } => {
                let file_path = if let Some(ws) = workspace.as_ref() {
                    ws.path.join(path)
                } else {
                    tracing::warn!(
                        "Workspace {} not found for automation {}",
                        mission.workspace_id,
                        automation.id
                    );
                    continue;
                };
                match tokio::fs::read_to_string(&file_path).await {
                    Ok(content) => content,
                    Err(e) => {
                        tracing::warn!(
                            "Failed to read file '{}' for automation {}: {}",
                            file_path.display(),
                            automation.id,
                            e
                        );
                        continue;
                    }
                }
            }
            CommandSource::Inline { content } => content.clone(),
            CommandSource::NativeLoop { .. } => {
                // Harness-driven loops iterate via the harness CLI itself.
                // Skip — the native_loop_observer records executions when
                // the harness emits goal events.
                continue;
            }
        };

        // Build substitution context for variable replacement
        let mut context = SubstitutionContext::new(mission.id);
        if let Some(ref title) = mission.title {
            context = context.with_mission_name(title.clone());
        }
        if let Some(ws) = workspace.as_ref() {
            context = context.with_working_directory(ws.path.to_string_lossy().to_string());
        }
        context = context.with_custom_variables(automation.variables.clone());

        let substituted_content = substitute_variables(&command_content, &context);

        let target_mission_id =
            resolve_agent_finished_target_mission(mission.id, mission.status, &automation);

        // Create an execution record in Running status – it will be
        // completed by complete_running_executions_for_mission when the
        // target agent finishes processing.
        let execution_id = Uuid::new_v4();
        let execution = AutomationExecution {
            id: execution_id,
            automation_id: automation.id,
            mission_id: target_mission_id,
            triggered_at: mission_store::now_string(),
            trigger_source: "agent_finished".to_string(),
            status: ExecutionStatus::Running,
            webhook_payload: None,
            variables_used: automation.variables.clone(),
            completed_at: None,
            error: None,
            retry_count: 0,
        };

        if mission_store
            .create_automation_execution(execution)
            .await
            .is_ok()
        {
            // Best-effort: update last_triggered_at for visibility in UI.
            if let Err(e) = mission_store
                .update_automation_last_triggered(automation.id)
                .await
            {
                tracing::warn!("Failed to update automation last triggered time: {}", e);
            }
        } else {
            // If we can't record execution, still trigger the message.
            tracing::warn!(
                "Failed to create execution record for agent_finished automation {}",
                automation.id
            );
        }

        tracing::info!(
            "Triggering agent_finished automation {} (execution {}) from mission {} to mission {}",
            automation.id,
            execution_id,
            mission.id,
            target_mission_id
        );

        out.push(RoutedAutomationMessage {
            content: substituted_content,
            target_mission_id,
        });
    }

    out
}

#[allow(
    clippy::too_many_arguments,
    clippy::collapsible_match,
    clippy::collapsible_else_if
)]
async fn control_actor_loop(
    control_hub: ControlHub,
    config: Config,
    root_agent: AgentRef,
    mcp: Arc<McpRegistry>,
    workspaces: workspace::SharedWorkspaceStore,
    library: SharedLibrary,
    mut cmd_rx: mpsc::Receiver<ControlCommand>,
    mut mission_cmd_rx: mpsc::Receiver<crate::tools::mission::MissionControlCommand>,
    mission_cmd_tx: mpsc::Sender<crate::tools::mission::MissionControlCommand>,
    // Clone of the actor's own command sender, used by the task-board
    // scheduler to spawn workers and deliver digests through the normal
    // message-routing path (always try_send, never await — see board.rs).
    self_cmd_tx: mpsc::Sender<ControlCommand>,
    events_tx: broadcast::Sender<AgentEvent>,
    mut events_rx: broadcast::Receiver<AgentEvent>,
    tool_hub: Arc<FrontendToolHub>,
    status: Arc<RwLock<ControlStatus>>,
    current_mission: Arc<RwLock<Option<Uuid>>>,
    current_tree: Arc<RwLock<Option<AgentTreeNode>>>,
    progress: Arc<RwLock<ExecutionProgress>>,
    mission_store: Arc<dyn MissionStore>,
    secrets: Option<Arc<SecretsStore>>,
    session_user_id: String,
    // Shared registry of in-flight Claude Code background shell tasks. Written
    // here from the `ToolResult` event arm; read by the auto-resume watcher.
    background_tasks: super::mission_runner::BackgroundTaskRegistry,
) {
    // A process-local actor cannot reattach a harness JoinHandle after restart.
    // Close any inherited execution lease before accepting new work; durable
    // workspace/remote jobs remain independently recoverable by job id. Use
    // the established server_shutdown reason so the startup recovery task
    // below re-drives task-mode missions (assistant-mode missions remain idle).
    if let Ok(inherited_runs) = mission_store.list_active_mission_runs().await {
        for run in inherited_runs {
            if run.execution_state == MissionExecutionState::WaitingRemoteJob {
                let mission_status = match mission_store.get_mission(run.mission_id).await {
                    Ok(Some(mission)) => mission.status,
                    Ok(None) => MissionStatus::Interrupted,
                    Err(error) => {
                        // Do not destroy detached work while its presentation
                        // status cannot be read. The remote reconciler will
                        // retry once the store is available.
                        tracing::warn!(
                            mission_id = %run.mission_id,
                            run_id = %run.run_id,
                            %error,
                            "Control actor startup: mission status unavailable; preserving wait lease"
                        );
                        continue;
                    }
                };
                match recoverable_inherited_remote_wait(
                    &config.working_dir,
                    run.mission_id,
                    run.execution_state,
                    mission_status,
                )
                .await
                {
                    Ok(Some(job_id)) => {
                        tracing::info!(
                            mission_id = %run.mission_id,
                            run_id = %run.run_id,
                            generation = run.generation,
                            %job_id,
                            "Control actor startup: preserving recoverable remote-build wait lease"
                        );
                        continue;
                    }
                    Ok(None) => {
                        tracing::warn!(
                            mission_id = %run.mission_id,
                            run_id = %run.run_id,
                            "Control actor startup: remote wait has no accepted ledger handle; interrupting stale lease"
                        );
                    }
                    Err(error) => {
                        // The ledger is execution truth for detached remote
                        // work. Fail closed and let its reconciler retry rather
                        // than destroying a possibly-live lease on a transient
                        // read failure.
                        tracing::warn!(
                            mission_id = %run.mission_id,
                            run_id = %run.run_id,
                            %error,
                            "Control actor startup: remote job ledger unavailable; preserving wait lease"
                        );
                        continue;
                    }
                }
            }
            let _ = mission_store
                .finish_mission_run(run.run_id, run.generation, Some("server_shutdown"))
                .await;
            if let Ok(Some(mission)) = mission_store.get_mission(run.mission_id).await {
                if mission.status == MissionStatus::Active {
                    let _ = mission_store
                        .update_mission_status_with_reason(
                            run.mission_id,
                            MissionStatus::Interrupted,
                            Some("server_shutdown"),
                        )
                        .await;
                }
            }
        }
    }
    // Queue stores (id, content, agent, target_mission_id) for the current/primary mission
    // The target_mission_id tracks which mission each queued message is intended for
    let mut queue: VecDeque<ControlQueueEntry> = VecDeque::new();
    // Re-drive any messages that were queued before the last restart. They are
    // persisted as a JSON snapshot (see `persist_control_queue_if_changed`) so a
    // restart doesn't lose pending work. We re-inject them through the normal
    // command channel rather than pushing straight onto `queue`: an idle actor
    // never dequeues a pre-filled `queue` on its own, so the work would
    // otherwise sit forever. Routing them as commands also de-duplicates against
    // a client retry of the same id via `accept_user_message_id` (whichever
    // arrives first runs; the other is dropped), so nothing executes twice.
    let mut restored_db_snapshot = String::new();
    let mut recovered_consumed_user_messages: HashMap<Uuid, QueuedMessage> = HashMap::new();
    if let Ok(payload) = mission_store.load_control_queue(&session_user_id).await {
        if !payload.trim().is_empty() {
            match serde_json::from_str::<Vec<QueuedMessage>>(&payload) {
                Ok(items) => {
                    let count = items.len();
                    let (pending, consumed) = partition_restored_control_messages(items);
                    let interrupted = consumed.len();
                    recovered_consumed_user_messages
                        .extend(consumed.into_iter().map(|message| (message.id, message)));
                    let mut replayed = 0usize;
                    for it in pending {
                        let (ack_tx, _ack_rx) = tokio::sync::oneshot::channel();
                        if let Err(e) = self_cmd_tx.try_send(ControlCommand::UserMessage {
                            id: it.id,
                            content: it.content,
                            agent: it.agent,
                            target_mission_id: it.mission_id,
                            strict: false,
                            source: it.source,
                            respond: ack_tx,
                        }) {
                            tracing::warn!("Failed to re-queue restored control message: {e}");
                        } else {
                            replayed += 1;
                        }
                    }
                    if count > 0 {
                        // Remember the stale on-disk snapshot so the first
                        // loop-top persist below rewrites the DB to the real
                        // (re-injected) state instead of leaving it stale.
                        restored_db_snapshot = payload;
                        tracing::info!(
                            replayed,
                            interrupted,
                            total = count,
                            "Recovered durable control messages from the previous session"
                        );
                    }
                }
                Err(e) => tracing::warn!("Failed to parse persisted control queue: {e}"),
            }
        }
    }
    // Parallel mission runners - each runs independently. Their pending
    // messages share the durable session queue snapshot with the main queue.
    let mut parallel_runners: std::collections::HashMap<
        Uuid,
        super::mission_runner::MissionRunner,
    > = std::collections::HashMap::new();

    // Snapshot of the queue as last written to the store; used to debounce
    // persistence so we only write to the DB when the queue actually changes.
    // When messages were restored, seed it with the stale on-disk snapshot so
    // the first loop-top persist overwrites it with the live queue.
    let mut last_persisted_queue: String = if restored_db_snapshot.is_empty() {
        serialize_queue_snapshot(&queue, &parallel_runners, &recovered_consumed_user_messages)
    } else {
        restored_db_snapshot
    };
    let mut history: Vec<(String, String)> = Vec::new(); // (role, content) pairs (user/assistant)
    let mut running: Option<tokio::task::JoinHandle<(Uuid, String, crate::agents::AgentResult)>> =
        None;
    let mut running_cancel: Option<CancellationToken> = None;
    // Track which mission the main `running` task is actually working on.
    // This is different from `current_mission` which can change when user creates a new mission.
    let mut running_mission_id: Option<Uuid> = None;
    // Backend captured for the currently executing primary turn. Updating a
    // mission's settings while it runs must not change watchdog semantics for
    // that in-flight process.
    let mut running_backend_id: Option<String> = None;
    let mut running_run: Option<MissionRun> = None;
    let mut execution_heartbeat = tokio::time::interval(std::time::Duration::from_secs(15));
    execution_heartbeat.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
    // Track last activity for the main runner (for stall detection)
    let mut main_runner_last_activity: std::time::Instant = std::time::Instant::now();
    // Track current activity label for the main runner
    let mut main_runner_activity: Option<String> = None;
    // Idempotency guard for user sends. The dashboard may retry a POST if a
    // weak connection drops after the command reached this actor but before the
    // HTTP response got back; since the client provides the UUID, repeated
    // commands with the same id are ignored instead of running twice. Restored
    // messages (re-injected as commands above) rely on this same guard: the
    // first occurrence runs, any later duplicate is dropped.
    let mut accepted_user_message_ids: HashSet<Uuid> = HashSet::new();
    // One bounded same-mission retry for structured transport failures. Auth,
    // quota/capacity, source failures, stalls, and loops are deliberately not
    // eligible. Writer leases are re-acquired by the normal start path.
    let mut transport_auto_resumed_missions: HashSet<Uuid> = HashSet::new();
    // Track subtasks for the main runner
    let mut main_runner_subtasks: Vec<super::mission_runner::SubtaskInfo> = Vec::new();
    // Track number of in-flight tool calls on the main runner so the stall
    // classifier can distinguish "model is hung" from "tool is honestly
    // running" (e.g. a 12-minute `lake build`). See stall_severity().
    let main_runner_active_tool_calls: std::sync::Arc<std::sync::atomic::AtomicUsize> =
        std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    // Deadline for force-reaping a runner whose cancel token was fired
    // but whose JoinHandle never resolved. This handles the "zombie
    // runner" case: the underlying CLI subprocess died (or never reacts
    // to the cancel because it's blocked on a closed pipe / dead
    // child), so the spawned task never returns, `running` stays
    // `Some`, the in-memory running list keeps reporting the mission,
    // and `Stop` becomes a no-op. After this deadline we force-abort
    // the JoinHandle and clean up the in-memory state.
    let mut runner_force_clear_deadline: Option<tokio::time::Instant> = None;
    const RUNNER_FORCE_CLEAR_GRACE: std::time::Duration = std::time::Duration::from_secs(30);

    // Correlate Bash `tool_call_id` -> command string so that when the matching
    // `Bash` ToolResult carries a background-start marker we can record the
    // launched command in the background-task registry. Capped to avoid
    // unbounded growth if a result is ever dropped; entries are removed when
    // the matching result arrives. Only `Bash` calls are tracked.
    let mut pending_bash_commands: std::collections::HashMap<String, String> =
        std::collections::HashMap::new();
    const MAX_PENDING_BASH_COMMANDS: usize = 256;
    let background_autoresume_enabled = super::mission_runner::background_task_autoresume_enabled();

    // Task-board scheduler cadence: the 100ms tick is far too hot for store
    // scans, so passes run every few seconds. Each pass spawns ready workers,
    // sweeps zombies, and wakes idle bosses whose board needs a decision.
    const BOARD_PASS_INTERVAL: std::time::Duration = std::time::Duration::from_secs(3);
    let mut last_board_pass = tokio::time::Instant::now();
    // FLEET-001 scheduling dispatch cadence: same throttling rationale as the
    // board pass — a store scan on every 100ms tick is wasteful. Each pass
    // expires past-deadline scheduled missions and, when the main session is
    // idle, dispatches the highest-priority dispatchable one.
    const SCHEDULER_PASS_INTERVAL: std::time::Duration = std::time::Duration::from_secs(5);
    let mut last_scheduler_pass = tokio::time::Instant::now();
    // Guards against double-dispatch: a scheduled mission stays Pending (with its
    // goal) until the dispatched message is processed and flips it to Active. If
    // the actor is slow or the start is dropped, that window can exceed one pass,
    // so we record each dispatch and skip re-dispatching the same mission until
    // this cooldown elapses (after which a still-Pending mission is retried).
    const SCHEDULER_DISPATCH_COOLDOWN: std::time::Duration = std::time::Duration::from_secs(60);
    let mut scheduler_inflight: std::collections::HashMap<Uuid, tokio::time::Instant> =
        std::collections::HashMap::new();
    // Per-boss "wake outstanding" flags, coalescing board wakes across passes.
    let mut board_wake_state: std::collections::HashMap<Uuid, bool> =
        std::collections::HashMap::new();
    let board_outbox_inflight: board::BoardOutboxInflight =
        Arc::new(std::sync::Mutex::new(std::collections::HashSet::new()));

    // Helper to extract file paths from text (for mission summaries)
    fn extract_file_paths(text: &str) -> Vec<String> {
        let mut paths = Vec::new();
        // Match common file path patterns
        for word in text.split_whitespace() {
            let word =
                word.trim_matches(|c| c == '`' || c == '\'' || c == '"' || c == ',' || c == ':');
            if (word.starts_with('/') || word.starts_with("./"))
                && word.len() > 3
                && !word.contains("http")
                && word.chars().filter(|c| *c == '/').count() >= 1
            {
                // Likely a file path
                paths.push(word.to_string());
            }
        }
        paths
    }

    // Helper to persist history to a specific mission ID
    async fn persist_mission_history_to(
        mission_store: &Arc<dyn MissionStore>,
        events_tx: &broadcast::Sender<AgentEvent>,
        mission_id: Option<Uuid>,
        history: &[(String, String)],
    ) {
        if let Some(mid) = mission_id {
            let entries: Vec<MissionHistoryEntry> = history
                .iter()
                .map(|(role, content)| MissionHistoryEntry {
                    role: role.clone(),
                    content: content.clone(),
                })
                .collect();
            persist_mission_history_and_schedule_metadata_refresh(
                mission_store,
                events_tx,
                mid,
                &entries,
            )
            .await;
        }
    }

    // Helper to persist history to current mission (wrapper for backwards compatibility)
    async fn persist_mission_history(
        mission_store: &Arc<dyn MissionStore>,
        events_tx: &broadcast::Sender<AgentEvent>,
        current_mission: &Arc<RwLock<Option<Uuid>>>,
        history: &[(String, String)],
    ) {
        let mission_id = *current_mission.read().await;
        persist_mission_history_to(mission_store, events_tx, mission_id, history).await;
    }

    fn parse_tool_result_object(result: &serde_json::Value) -> Option<serde_json::Value> {
        if result.is_object() {
            return Some(result.clone());
        }
        if let Some(raw) = result.as_str() {
            if let Ok(parsed) = serde_json::from_str::<serde_json::Value>(raw) {
                return Some(parsed);
            }
        }
        None
    }

    /// Extract the human-readable text from a tool result `Value`.
    ///
    /// The Claude Code runner emits either a plain string or an object of the
    /// form `{ "content": ..., "stdout": ..., "stderr": ..., "is_error": ... }`
    /// (see `runners::claudecode`). We prefer `content`, falling back to
    /// `stdout`, then the whole string. Returns `None` when no text is present.
    fn tool_result_text(result: &serde_json::Value) -> Option<String> {
        if let Some(s) = result.as_str() {
            return Some(s.to_string());
        }
        if let Some(obj) = result.as_object() {
            for key in ["content", "stdout"] {
                if let Some(s) = obj.get(key).and_then(|v| v.as_str()) {
                    if !s.is_empty() {
                        return Some(s.to_string());
                    }
                }
            }
        }
        None
    }

    // Helper to load a mission and return a Mission struct
    async fn load_mission_record(
        mission_store: &Arc<dyn MissionStore>,
        id: Uuid,
    ) -> Result<Mission, String> {
        mission_store
            .get_mission(id)
            .await?
            .ok_or_else(|| format!("Mission {} not found", id))
    }

    // Helper to create a new mission
    async fn create_new_mission(mission_store: &Arc<dyn MissionStore>) -> Result<Mission, String> {
        create_new_mission_with_title(
            mission_store,
            None,
            None,
            None,
            None,
            None,
            false,
            None,
            None,
            None,
            None,
            crate::api::mission_store::MissionScheduling::default(),
        )
        .await
    }

    // Helper to create a new mission with title
    #[allow(clippy::too_many_arguments)]
    async fn create_new_mission_with_title(
        mission_store: &Arc<dyn MissionStore>,
        title: Option<&str>,
        workspace_id: Option<Uuid>,
        agent: Option<&str>,
        model_override: Option<&str>,
        model_effort: Option<&str>,
        fast_mode: bool,
        backend: Option<&str>,
        config_profile: Option<&str>,
        parent_mission_id: Option<Uuid>,
        working_directory: Option<&str>,
        scheduling: crate::api::mission_store::MissionScheduling,
    ) -> Result<Mission, String> {
        let mut mission = mission_store
            .create_mission_with_parent(
                title,
                workspace_id,
                agent,
                model_override,
                model_effort,
                fast_mode,
                backend,
                config_profile,
                parent_mission_id,
                working_directory,
            )
            .await?;
        // FLEET-001: persist scheduling metadata as a focused follow-up write so
        // the wide `create_mission_with_parent` signature stays untouched.
        if scheduling != crate::api::mission_store::MissionScheduling::default() {
            mission_store
                .set_mission_scheduling(mission.id, &scheduling)
                .await?;
            mission.scheduling = scheduling;
        }
        Ok(mission)
    }

    // Helper to validate and prepare an interrupted or blocked mission for resume.
    async fn resume_mission_impl(
        mission_store: &Arc<dyn MissionStore>,
        config: &Config,
        mission_id: Uuid,
        clean_workspace: bool,
    ) -> Result<(Mission, String), String> {
        let mission = load_mission_record(mission_store, mission_id).await?;

        // Check if mission can be resumed. Paused remains Paused until the
        // actor has acquired the durable writer lock and accepted the resume.
        // Failed missions can be resumed to retry after transient errors (e.g., 529 overloaded)
        if !matches!(
            mission.status,
            MissionStatus::Interrupted
                | MissionStatus::Blocked
                | MissionStatus::Failed
                | MissionStatus::Paused
        ) {
            return Err(format!(
                "Mission {} cannot be resumed (status: {})",
                mission_id, mission.status
            ));
        }

        // Clean mission context if requested.
        // Missions share the workspace directory, so we avoid deleting project files.
        if clean_workspace {
            let context_root = config.working_dir.join(&config.context.context_dir_name);
            let mission_context_dir = context_root.join(mission_id.to_string());
            tracing::info!(
                mission_id = %mission_id,
                path = %mission_context_dir.display(),
                "Cleaning mission context directory (shared workspace mode)"
            );
            if mission_context_dir.exists() {
                if let Err(e) = std::fs::remove_dir_all(&mission_context_dir) {
                    tracing::warn!("Failed to clean mission context: {}", e);
                }
            }
            let _ = std::fs::create_dir_all(&mission_context_dir);

            let runtime_file =
                workspace::runtime_workspace_file_path(&config.working_dir, Some(mission_id));
            let _ = std::fs::remove_file(runtime_file);
        }

        Ok((mission, INTERRUPTED_RESUME_PROMPT.to_string()))
    }

    loop {
        // Persist the pending queue whenever it changes so a restart doesn't
        // lose queued messages. Debounced by snapshot comparison — the DB is
        // written only when the queue actually changed (no per-iteration churn
        // during streaming, where the queue is usually unchanged). Each dequeue
        // site below also persists immediately so a popped message can't be
        // re-run after a crash (see `persist_control_queue_if_changed`).
        let _ = persist_control_queue_if_changed(
            &mission_store,
            &session_user_id,
            &queue,
            &parallel_runners,
            &recovered_consumed_user_messages,
            &mut last_persisted_queue,
        )
        .await;
        tokio::select! {
            _ = execution_heartbeat.tick() => {
                let mut leases = Vec::new();
                if let Some(run) = running_run.clone() {
                    leases.push((
                        run,
                        running_backend_id.clone(),
                        main_runner_active_tool_calls
                            .load(std::sync::atomic::Ordering::Relaxed),
                        main_runner_last_activity.elapsed().as_secs(),
                    ));
                }
                leases.extend(parallel_runners.values().filter_map(|runner| {
                    runner.durable_run.clone().map(|run| {
                        (
                            run,
                            Some(runner.backend_id.clone()),
                            runner
                                .active_tool_calls
                                .load(std::sync::atomic::Ordering::Relaxed),
                            runner.last_activity.elapsed().as_secs(),
                        )
                    })
                }));
                let remote_jobs_by_mission = if leases.is_empty() {
                    HashSet::new()
                } else {
                    match crate::remote_node::job_ledger::load(&config.working_dir).await {
                        Ok(handles) => {
                            let now = chrono::Utc::now();
                            handles
                                .into_iter()
                                .filter(|handle| remote_build_handle_proves_liveness(handle, now))
                                .map(|handle| handle.mission_id)
                                .collect()
                        }
                        Err(error) => {
                            tracing::warn!(?error, "Failed to inspect durable remote jobs for execution heartbeat");
                            HashSet::new()
                        }
                    }
                };
                for (run, backend_id, active_tool_calls, idle_secs) in leases {
                    let mut live_registered_tools = 0usize;
                    let mut has_registered_user_wait = false;
                    let has_durable_remote_job = remote_jobs_by_mission.contains(&run.mission_id);
                    if has_durable_remote_job {
                        live_registered_tools += 1;
                    }
                    if let Ok(tools) = mission_store
                        .list_active_tool_executions(run.run_id)
                        .await
                    {
                        for tool in tools {
                            if is_user_wait_tool(&tool.tool_kind) {
                                // User-input tools remain live until their
                                // matching result arrives. The generic 120s
                                // provisional deadline must never reap a
                                // mission merely because a human took longer
                                // than two minutes to answer.
                                has_registered_user_wait = true;
                                live_registered_tools += 1;
                                continue;
                            }
                            let expired = chrono::DateTime::parse_from_rfc3339(
                                &tool.deadline_at,
                            )
                            .map(|deadline| {
                                deadline.with_timezone(&chrono::Utc) <= chrono::Utc::now()
                            })
                            .unwrap_or(true);
                            if expired && tool.state == MissionToolExecutionState::Provisional {
                                let _ = mission_store
                                    .finish_tool_execution(
                                        run.run_id,
                                        &tool.tool_call_id,
                                        MissionToolExecutionState::Stale,
                                        None,
                                        Some("unmatched_tool_call_deadline"),
                                    )
                                    .await;
                            } else {
                                live_registered_tools += 1;
                            }
                        }
                    }
                    let state = mission_heartbeat_state(
                        active_tool_calls,
                        has_registered_user_wait,
                        has_durable_remote_job,
                    );
                    match mission_store
                        .heartbeat_mission_run(run.run_id, run.generation, state, None)
                        .await
                    {
                        Ok(true) => {}
                        Ok(false) => tracing::warn!(
                            mission_id = %run.mission_id,
                            run_id = %run.run_id,
                            generation = run.generation,
                            "Ignored heartbeat for stale mission run generation"
                        ),
                        Err(error) => tracing::warn!(
                            mission_id = %run.mission_id,
                            run_id = %run.run_id,
                            "Failed to persist mission run heartbeat: {error}"
                        ),
                    }
                    if idle_secs >= 15 * 60
                        && state != MissionExecutionState::WaitingUser
                        && state != MissionExecutionState::WaitingRemoteJob
                        && live_registered_tools == 0
                    {
                        let owned = match mission_store.get_mission(run.mission_id).await {
                            Ok(Some(mission)) => skip_idle_registered_liveness_interrupt(
                                backend_id.as_deref(),
                                mission.origin.as_deref(),
                                mission.origin_session_id.as_deref(),
                                &mission.project.tags,
                            ),
                            _ => skip_idle_registered_liveness_interrupt(
                                backend_id.as_deref(),
                                None,
                                None,
                                &[],
                            ),
                        };
                        if owned {
                            tracing::warn!(
                                mission_id = %run.mission_id,
                                run_id = %run.run_id,
                                idle_secs,
                                "Registered-liveness interrupt: control-owned mission idle — NOT interrupting"
                            );
                            continue;
                        }
                        tracing::warn!(
                            mission_id = %run.mission_id,
                            run_id = %run.run_id,
                            idle_secs,
                            "Interrupting mission after 15 minutes without registered liveness evidence"
                        );
                        let _ = mission_store
                            .heartbeat_mission_run(
                                run.run_id,
                                run.generation,
                                MissionExecutionState::Stopping,
                                None,
                            )
                            .await;
                        if running_mission_id == Some(run.mission_id) {
                            if let Some(token) = &running_cancel {
                                token.cancel();
                                runner_force_clear_deadline = Some(
                                    tokio::time::Instant::now() + RUNNER_FORCE_CLEAR_GRACE,
                                );
                            }
                        } else if let Some(runner) = parallel_runners.get_mut(&run.mission_id) {
                            runner.cancel();
                        }
                    }
                }
            }
            cmd = cmd_rx.recv() => {
                let Some(cmd) = cmd else { break };
                match cmd {
                    ControlCommand::UserMessage { id, content, agent: msg_agent, target_mission_id, strict, source, respond } => {
                        if recovered_consumed_user_messages.contains_key(&id) {
                            // The previous actor had already started this exact
                            // deterministic delivery. Its run was interrupted
                            // during startup recovery, so acknowledge the retry
                            // without repeating side effects; the mission now
                            // requires an explicit resume.
                            let _ = respond.send(UserMessageAck::Delivered);
                            continue;
                        }
                        if !accept_user_message_id(&mut accepted_user_message_ids, id) {
                            let status_snapshot = status.read().await;
                            let _ = respond.send(if status_snapshot.state != ControlRunState::Idle {
                                UserMessageAck::Queued
                            } else {
                                UserMessageAck::Delivered
                            });
                            continue;
                        }

                        // Smart routing: decide where to send this message based on target_mission_id
                        // and what's currently running.

                        let current_mission_id = *current_mission.read().await;
                        let running_mid = running_mission_id;
                        let main_mission_id = if running_mid.is_some() {
                            running_mid
                        } else {
                            current_mission_id
                        };
                        let main_is_running = running.is_some();

                        // If no explicit target but current_mission differs from the
                        // running mission (i.e., CreateMission switched the pointer),
                        // No inference: a message without an explicit mission_id used to be
                        // silently re-targeted to the actor's "current" mission when it
                        // differed from the running one. In practice every legitimate caller
                        // (dashboard, MCP) sends mission_id explicitly, and the fallback
                        // mis-delivered API messages twice in one night (a worker diagnosis
                        // and an oracle priming both landed in unrelated missions). Messages
                        // without a target now follow the plain default-mission path —
                        // and when even that is ambiguous (a runner busy on one mission
                        // while the session pointer is on another), the message is
                        // DROPPED LOUDLY instead of delivered somewhere surprising.
                        let effective_target = target_mission_id;
                        if effective_target.is_none() && main_is_running {
                            if let Some(cid) = current_mission_id {
                                if running_mid != Some(cid) {
                                    tracing::warn!(
                                        running = ?running_mid,
                                        current = %cid,
                                        "Untargeted message rejected: ambiguous target; pass mission_id explicitly"
                                    );
                                    let _ = events_tx.send(AgentEvent::Error {
                                        message: format!(
                                            "Untargeted message rejected: running mission {:?} differs from current {}; pass mission_id explicitly",
                                            running_mid, cid
                                        ),
                                        mission_id: Some(cid),
                                        resumable: false,
                                    });
                                    let _ = respond.send(UserMessageAck::Dropped);
                                    continue;
                                }
                            }
                        }

                        // Determine if target is already running somewhere
                        let target_in_parallel = effective_target
                            .map(|tid| parallel_runners.contains_key(&tid))
                            .unwrap_or(false);
                        let target_is_main = effective_target
                            .map(|tid| main_mission_id == Some(tid))
                            .unwrap_or(true); // No target = use main

                        // Grok `/goal <objective>` kickoff: rewrite the message
                        // to the wrapped first-turn prompt and create the
                        // AgentFinished automation row that will drive the
                        // loop. Non-grok backends and non-/goal messages fall
                        // through unchanged. See `api/grok_goal.rs`.
                        let goal_target_mission = effective_target.or(main_mission_id);
                        let mut content = content;
                        // Canonicalise `/goal\n…` to the space form at the single
                        // entry point, so every downstream space-only parser (the
                        // grok kickoff below, the mission_runner dispatch paths,
                        // the codex/opencode goal drivers) sees the same goal
                        // command. Strict (control-plane) messages are never goal
                        // commands and stay byte-exact.
                        if !strict {
                            if let Some(canonical) = canonical_goal_message(&content) {
                                content = canonical;
                            }
                        }
                        // Strict (control-plane) messages are system-generated and must
                        // never be reinterpreted as a `/goal` kickoff — skip the rewrite.
                        if !strict {
                            match maybe_begin_grok_goal(
                                &mission_store,
                                &events_tx,
                                goal_target_mission,
                                &content,
                            )
                            .await
                            {
                                GrokGoalKickoff::Passthrough => {}
                                GrokGoalKickoff::Rewritten { prompt } => {
                                    content = prompt;
                                }
                                GrokGoalKickoff::Rejected { reason } => {
                                    let _ = events_tx.send(AgentEvent::Error {
                                        message: reason,
                                        mission_id: goal_target_mission,
                                        resumable: true,
                                    });
                                    let _ = respond.send(UserMessageAck::Dropped);
                                    continue;
                                }
                            }
                        }

                        // Reject paused targets before writer capability is
                        // acquired. Retagging a paused read-only audit for a
                        // message that cannot run would create a phantom lease.
                        if let Some(tid) = effective_target {
                            if let Ok(Some(mission)) = mission_store.get_mission(tid).await {
                                if mission.status == MissionStatus::Paused {
                                    let _ = events_tx.send(AgentEvent::Error {
                                        message: format!(
                                            "Mission {} is paused; resume it before sending messages",
                                            tid
                                        ),
                                        mission_id: Some(tid),
                                        resumable: true,
                                    });
                                    let _ = respond.send(UserMessageAck::Dropped);
                                    continue;
                                }
                            }
                        }

                        // FLEET-001 scheduled-mission deferral: if the target is a
                        // Pending mission whose `not_before` is still in the future
                        // and it isn't already running, stash the goal and leave it
                        // Pending. The scheduler tick re-injects it as a normal user
                        // message once the dispatch window opens. Strict control-plane
                        // messages are operational and never deferred.
                        if !strict {
                            if let Some(tid) = effective_target {
                                let target_running =
                                    target_in_parallel || running_mid == Some(tid);
                                if !target_running {
                                    if let Ok(Some(m)) = mission_store.get_mission(tid).await {
                                        let now = chrono::Utc::now();
                                        if m.status == MissionStatus::Pending
                                            && !m.is_dispatchable_at(now)
                                        {
                                            let writer_lease = match acquire_pr_writer_lease_for_message(
                                                &control_hub,
                                                &mission_store,
                                                &m,
                                                &content,
                                            )
                                            .await
                                            {
                                                Ok(lease) => lease,
                                                Err(error) => {
                                                    let _ = events_tx.send(AgentEvent::Error {
                                                        message: format!(
                                                            "Cannot reserve writer lease for mission {}: {}",
                                                            tid, error
                                                        ),
                                                        mission_id: Some(tid),
                                                        resumable: true,
                                                    });
                                                    let _ = respond.send(UserMessageAck::Rejected(error));
                                                    continue;
                                                }
                                            };
                                            // Append to any previously-stashed goal so
                                            // multiple pre-dispatch messages aren't lost.
                                            let previous_goal = mission_store
                                                .get_deferred_goal(tid)
                                                .await
                                                .ok()
                                                .flatten();
                                            let combined = match previous_goal.as_deref() {
                                                Some(prev) if !prev.is_empty() => {
                                                    format!("{prev}\n{content}")
                                                }
                                                _ => content.clone(),
                                            };
                                            if let Err(e) = mission_store
                                                .set_deferred_goal(tid, Some(combined))
                                                .await
                                            {
                                                rollback_message_writer_tag(
                                                    &mission_store,
                                                    &m,
                                                    &writer_lease,
                                                )
                                                .await;
                                                tracing::warn!(
                                                    mission_id = %tid,
                                                    "Failed to stash deferred goal: {e}"
                                                );
                                                let _ = respond.send(UserMessageAck::Dropped);
                                                continue;
                                            }
                                            // Surface the queued goal so the UI shows it
                                            // as pending until dispatch.
                                            let _ = events_tx.send(AgentEvent::UserMessage {
                                                id,
                                                content: content.clone(),
                                                queued: true,
                                                mission_id: Some(tid),
                                                source: source.clone(),
                                            });
                                            tracing::info!(
                                                mission_id = %tid,
                                                not_before = ?m.scheduling.not_before,
                                                "Deferred scheduled mission: goal stashed until dispatch window"
                                            );
                                            let _ = respond.send(UserMessageAck::Queued);
                                            continue;
                                        }
                                    }
                                }
                            }
                        }

                        // Case 1: Target is already running in parallel_runners - queue to it
                        if let Some(tid) = effective_target {
                            if target_in_parallel {
                                if let Ok(Some(mission)) = mission_store.get_mission(tid).await {
                                    if let Err(error) = activate_mission_for_message(
                                        &control_hub,
                                        &mission_store,
                                        &events_tx,
                                        &mission,
                                        &content,
                                    )
                                    .await
                                    {
                                        let _ = events_tx.send(AgentEvent::Error {
                                            message: format!(
                                                "Cannot apply writer lease for mission {}: {}",
                                                tid, error
                                            ),
                                            mission_id: Some(tid),
                                            resumable: true,
                                        });
                                        let _ = respond.send(UserMessageAck::Rejected(error));
                                        continue;
                                    }
                                }
                                let Some(runner) = parallel_runners.get_mut(&tid) else {
                                    accepted_user_message_ids.remove(&id);
                                    let _ = respond.send(UserMessageAck::Rejected(format!(
                                        "mission {tid} runner disappeared before queueing"
                                    )));
                                    continue;
                                };
                                if runner.cancellation_requested() {
                                    accepted_user_message_ids.remove(&id);
                                    let _ = respond.send(UserMessageAck::Rejected(format!(
                                        "mission {tid} is stopping"
                                    )));
                                    continue;
                                }
                                let was_running = runner.is_running();
                                runner.queue_message(id, content.clone(), msg_agent, source.clone());
                                // For an idle runner, reserve its prepared slot. Queue
                                // serialization deliberately keeps this replayable until
                                // acquire_durable_run succeeds.
                                if !was_running && runner.take_next_message_for_start().is_none() {
                                    accepted_user_message_ids.remove(&id);
                                    let _ = respond.send(UserMessageAck::Rejected(format!(
                                        "mission {tid} delivery disappeared before persistence"
                                    )));
                                    continue;
                                }
                                let _ = events_tx.send(AgentEvent::UserMessage {
                                    id,
                                    content: content.clone(),
                                    queued: was_running,
                                    mission_id: Some(tid),
                                    source: source.clone(),
                                });
                                // Surface the parallel queue growth to all
                                // clients (Status events otherwise only
                                // carry the main queue length). Only when
                                // the message actually stays queued —
                                // otherwise start_next pops it right away.
                                if was_running {
                                    let _ = events_tx.send(AgentEvent::Status {
                                        state: ControlRunState::Running,
                                        queue_len: runner.queue.len(),
                                        mission_id: Some(tid),
                                    });
                                }
                                // Persist queued and prepared parallel deliveries before
                                // they can be acknowledged. Prepared work remains marked
                                // pending until its durable run lease exists.
                                if let Err(error) = persist_control_queue_if_changed(
                                    &mission_store,
                                    &session_user_id,
                                    &queue,
                                    &parallel_runners,
                                    &recovered_consumed_user_messages,
                                    &mut last_persisted_queue,
                                )
                                .await
                                {
                                    if let Some(runner) = parallel_runners.get_mut(&tid) {
                                        runner.remove_from_queue(id);
                                        runner.remove_inflight_message(id);
                                    }
                                    accepted_user_message_ids.remove(&id);
                                    let _ = respond.send(UserMessageAck::Rejected(format!(
                                        "failed to persist parallel delivery: {error}"
                                    )));
                                    continue;
                                }
                                if !was_running {
                                    let Some(runner) = parallel_runners.get_mut(&tid) else {
                                        accepted_user_message_ids.remove(&id);
                                        let _ = respond.send(UserMessageAck::Rejected(format!(
                                            "mission {tid} runner disappeared before start"
                                        )));
                                        continue;
                                    };
                                    if let Err(error) = runner
                                        .acquire_durable_run(
                                            &mission_store,
                                            &format!("control:{session_user_id}"),
                                        )
                                        .await
                                    {
                                        let _ = events_tx.send(AgentEvent::Error {
                                            message: format!("Mission run lease rejected: {error}"),
                                            mission_id: Some(tid),
                                            resumable: true,
                                        });
                                        runner.remove_from_queue(id);
                                        runner.remove_inflight_message(id);
                                        let _ = persist_control_queue_if_changed(
                                            &mission_store,
                                            &session_user_id,
                                            &queue,
                                            &parallel_runners,
                                            &recovered_consumed_user_messages,
                                            &mut last_persisted_queue,
                                        )
                                        .await;
                                        accepted_user_message_ids.remove(&id);
                                        let _ = respond.send(UserMessageAck::Rejected(error));
                                        continue;
                                    }
                                    if let Err(error) = persist_control_queue_if_changed(
                                        &mission_store,
                                        &session_user_id,
                                        &queue,
                                        &parallel_runners,
                                        &recovered_consumed_user_messages,
                                        &mut last_persisted_queue,
                                    )
                                    .await
                                    {
                                        if let Some(runner) = parallel_runners.get_mut(&tid) {
                                            runner
                                                .finish_durable_run(
                                                    &mission_store,
                                                    Some("consumed_snapshot_persist_failed"),
                                                )
                                                .await;
                                            runner.remove_inflight_message(id);
                                        }
                                        accepted_user_message_ids.remove(&id);
                                        let _ = respond.send(UserMessageAck::Rejected(format!(
                                            "failed to persist consumed parallel delivery: {error}"
                                        )));
                                        continue;
                                    }
                                    let Some(runner) = parallel_runners.get_mut(&tid) else {
                                        accepted_user_message_ids.remove(&id);
                                        let _ = respond.send(UserMessageAck::Rejected(format!(
                                            "mission {tid} runner disappeared before start"
                                        )));
                                        continue;
                                    };
                                    runner.start_next(
                                        config.clone(),
                                        Arc::clone(&root_agent),
                                        Arc::clone(&mcp),
                                        Arc::clone(&workspaces),
                                        library.clone(),
                                        events_tx.clone(),
                                        Arc::clone(&tool_hub),
                                        Arc::clone(&status),
                                        mission_cmd_tx.clone(),
                                        Arc::new(RwLock::new(Some(tid))),
                                        secrets.clone(),
                                    );
                                }
                                // The durable snapshot, not process creation,
                                // is the acceptance boundary. Report Queued even
                                // when execution started immediately so outbox
                                // retirement never depends on a volatile handle.
                                let _ = respond.send(UserMessageAck::Queued);
                                continue;
                            }
                        }

                        // Case 2: Target differs from main → start parallel
                        // When target_mission_id is explicitly set (e.g. from Telegram),
                        // always use parallel execution to avoid hijacking the main session.
                        // When the target is merely inferred (current differs from running),
                        // only start parallel when main is busy.
                        let force_parallel = target_mission_id.is_some(); // explicit target (e.g. Telegram)
                        if let Some(tid) = effective_target {
                            if !target_is_main && (main_is_running || force_parallel) {
                                // Check capacity
                                let parallel_running = parallel_runners.values().filter(|r| r.is_running()).count();
                                let total_running = parallel_running + if main_is_running { 1 } else { 0 };
                                let max_parallel = crate::settings::max_parallel_missions_cached_or(config.max_parallel_missions);

                                if total_running >= max_parallel {
                                    // At capacity, dropping the message would orphan the
                                    // mission: it stays Pending with no deferred_goal, so
                                    // the FLEET-001 scheduler never dispatches it and the
                                    // HTTP response (`queued: false`) is indistinguishable
                                    // from a successful delivery. Stash the content as the
                                    // deferred goal instead — the scheduler pass re-injects
                                    // it as a normal targeted message once a slot frees.
                                    let mission = match mission_store.get_mission(tid).await {
                                        Ok(Some(mission)) => mission,
                                        Ok(None) => {
                                            let _ = respond.send(UserMessageAck::Dropped);
                                            continue;
                                        }
                                        Err(error) => {
                                            let _ = events_tx.send(AgentEvent::Error {
                                                message: format!(
                                                    "Cannot load mission {} before deferral: {}",
                                                    tid, error
                                                ),
                                                mission_id: Some(tid),
                                                resumable: true,
                                            });
                                            let _ = respond.send(UserMessageAck::Dropped);
                                            continue;
                                        }
                                    };
                                    let writer_lease = match acquire_pr_writer_lease_for_message(
                                        &control_hub,
                                        &mission_store,
                                        &mission,
                                        &content,
                                    )
                                    .await
                                    {
                                        Ok(lease) => lease,
                                        Err(error) => {
                                            let _ = events_tx.send(AgentEvent::Error {
                                                message: format!(
                                                    "Cannot reserve writer lease for mission {}: {}",
                                                    tid, error
                                                ),
                                                mission_id: Some(tid),
                                                resumable: true,
                                            });
                                            let _ = respond.send(UserMessageAck::Rejected(error));
                                            continue;
                                        }
                                    };
                                    let previous_goal = mission_store
                                        .get_deferred_goal(tid)
                                        .await
                                        .ok()
                                        .flatten();
                                    let combined = match previous_goal.as_deref() {
                                        Some(prev) if !prev.is_empty() => {
                                            format!("{prev}\n{content}")
                                        }
                                        _ => content.clone(),
                                    };
                                    match mission_store.set_deferred_goal(tid, Some(combined)).await
                                    {
                                        Ok(()) => {
                                            tracing::info!(
                                                mission_id = %tid,
                                                max_parallel,
                                                "At capacity: deferring targeted message as scheduled goal"
                                            );
                                            let _ = events_tx.send(AgentEvent::UserMessage {
                                                id,
                                                content: content.clone(),
                                                queued: true,
                                                mission_id: Some(tid),
                                                source: source.clone(),
                                            });
                                            let _ = respond.send(UserMessageAck::Queued);
                                        }
                                        Err(e) => {
                                            rollback_message_writer_tag(
                                                &mission_store,
                                                &mission,
                                                &writer_lease,
                                            )
                                            .await;
                                            tracing::warn!(
                                                mission_id = %tid,
                                                "Cannot start parallel mission (max {} reached) and \
                                                 failed to stash deferred goal: {e}",
                                                max_parallel
                                            );
                                            let _ = events_tx.send(AgentEvent::Error {
                                                message: format!(
                                                    "Cannot start mission {}: max parallel missions ({}) reached",
                                                    tid, max_parallel
                                                ),
                                                mission_id: Some(tid),
                                                resumable: true,
                                            });
                                            let _ = respond.send(UserMessageAck::Dropped);
                                        }
                                    }
                                    continue;
                                } else {
                                    // Load mission and start in parallel
                                    match load_mission_record(&mission_store, tid).await {
                                        Ok(mission) => {
                                            // A paused mission must not be auto-started by an
                                            // incoming message — respect the pause. The user
                                            // resumes it explicitly via the resume API.
                                            if mission.status == MissionStatus::Paused {
                                                let _ = events_tx.send(AgentEvent::Error {
                                                    message: format!(
                                                        "Mission {} is paused; resume it before sending messages",
                                                        tid
                                                    ),
                                                    mission_id: Some(tid),
                                                    resumable: true,
                                                });
                                                let _ = respond.send(UserMessageAck::Dropped);
                                                continue;
                                            }
                                            if let Err(error) = activate_mission_for_message(
                                                &control_hub,
                                                &mission_store,
                                                &events_tx,
                                                &mission,
                                                &content,
                                            )
                                            .await
                                            {
                                                let _ = events_tx.send(AgentEvent::Error {
                                                    message: format!(
                                                        "Cannot activate mission {}: {}",
                                                        tid, error
                                                    ),
                                                    mission_id: Some(tid),
                                                    resumable: true,
                                                });
                                                let _ = respond.send(UserMessageAck::Rejected(error));
                                                continue;
                                            }
                                            let mut runner = super::mission_runner::MissionRunner::new(
                                                tid,
                                                mission.workspace_id,
                                                mission.agent.clone(),
                                                Some(mission.backend.clone()),
                                                mission.session_id.clone(),
                                                mission.config_profile.clone(),
                                                mission.model_override.clone(),
                                                mission.model_effort.clone(),
                                                mission.fast_mode,
                                            );
                                            runner.pr_readonly = mission.project.tags.iter().any(|tag| tag == "pr-readonly");
                                            runner.working_directory = mission.working_directory.clone();
                                            runner.user_id = Some(session_user_id.clone());
                                            // Load existing history
                                            for entry in &mission.history {
                                                runner.history.push((entry.role.clone(), entry.content.clone()));
                                            }
                                            // Queue the message
                                            runner.queue_message(id, content.clone(), msg_agent, source.clone());
                                            // Reserve the prepared slot before its first
                                            // snapshot. Serialization keeps it replayable until
                                            // a durable run exists; start_next consumes this slot.
                                            if runner.take_next_message_for_start().is_none() {
                                                accepted_user_message_ids.remove(&id);
                                                let _ = respond.send(UserMessageAck::Rejected(
                                                    format!(
                                                        "mission {tid} delivery disappeared before persistence"
                                                    ),
                                                ));
                                                continue;
                                            }
                                            // Emit user message event
                                            let _ = events_tx.send(AgentEvent::UserMessage {
                                                id,
                                                content: content.clone(),
                                                queued: false,
                                                mission_id: Some(tid),
                                                source: source.clone(),
                                            });
                                            // Journal the prepared delivery as replayable pending
                                            // before acquiring the run or starting a process.
                                            parallel_runners.insert(tid, runner);
                                            if let Err(error) = persist_control_queue_if_changed(
                                                &mission_store,
                                                &session_user_id,
                                                &queue,
                                                &parallel_runners,
                                                &recovered_consumed_user_messages,
                                                &mut last_persisted_queue,
                                            )
                                            .await
                                            {
                                                parallel_runners.remove(&tid);
                                                accepted_user_message_ids.remove(&id);
                                                let _ = respond.send(UserMessageAck::Rejected(
                                                    format!(
                                                        "failed to persist parallel delivery: {error}"
                                                    ),
                                                ));
                                                continue;
                                            }
                                            let runner = parallel_runners
                                                .get_mut(&tid)
                                                .expect("parallel runner inserted above");
                                            if let Err(error) = runner
                                                .acquire_durable_run(
                                                    &mission_store,
                                                    &format!("control:{session_user_id}"),
                                                )
                                                .await
                                            {
                                                let _ = events_tx.send(AgentEvent::Error {
                                                    message: format!("Mission run lease rejected: {error}"),
                                                    mission_id: Some(tid),
                                                    resumable: true,
                                                });
                                                parallel_runners.remove(&tid);
                                                let _ = persist_control_queue_if_changed(
                                                    &mission_store,
                                                    &session_user_id,
                                                    &queue,
                                                    &parallel_runners,
                                                    &recovered_consumed_user_messages,
                                                    &mut last_persisted_queue,
                                                )
                                                .await;
                                                accepted_user_message_ids.remove(&id);
                                                let _ = respond.send(UserMessageAck::Rejected(error));
                                                continue;
                                            }
                                            if let Err(error) = persist_control_queue_if_changed(
                                                &mission_store,
                                                &session_user_id,
                                                &queue,
                                                &parallel_runners,
                                                &recovered_consumed_user_messages,
                                                &mut last_persisted_queue,
                                            )
                                            .await
                                            {
                                                if let Some(runner) = parallel_runners.get_mut(&tid) {
                                                    runner
                                                        .finish_durable_run(
                                                            &mission_store,
                                                            Some("consumed_snapshot_persist_failed"),
                                                        )
                                                        .await;
                                                }
                                                parallel_runners.remove(&tid);
                                                accepted_user_message_ids.remove(&id);
                                                let _ = respond.send(UserMessageAck::Rejected(
                                                    format!(
                                                        "failed to persist consumed parallel delivery: {error}"
                                                    ),
                                                ));
                                                continue;
                                            }
                                            let runner = parallel_runners
                                                .get_mut(&tid)
                                                .expect("parallel runner persisted above");
                                            runner.start_next(
                                                config.clone(),
                                                Arc::clone(&root_agent),
                                                Arc::clone(&mcp),
                                                Arc::clone(&workspaces),
                                                library.clone(),
                                                events_tx.clone(),
                                                Arc::clone(&tool_hub),
                                                Arc::clone(&status),
                                                mission_cmd_tx.clone(),
                                                Arc::new(RwLock::new(Some(tid))),
                                                secrets.clone(),
                                            );
                                            tracing::info!("Auto-started mission {} in parallel", tid);
                                            let _ = respond.send(UserMessageAck::Queued);
                                            continue;
                                        }
                                        Err(e) => {
                                            tracing::error!(
                                                "Failed to load mission {} for parallel: {}. \
                                                 Dropping targeted message to avoid sending to wrong mission.",
                                                tid, e
                                            );
                                            let _ = events_tx.send(AgentEvent::Error {
                                                message: format!(
                                                    "Failed to load mission {}: {}",
                                                    tid, e
                                                ),
                                                mission_id: Some(tid),
                                                resumable: true,
                                            });
                                            let _ = respond.send(UserMessageAck::Dropped);
                                            continue;
                                        }
                                    }
                                }
                            }
                        }

                        // Strict (control-plane) messages must never leak into an
                        // *unrelated* mission. If the target is some OTHER mission
                        // than the main session's and we got here, Case 1/2 (queue
                        // to / start a parallel runner) didn't fire — drop rather
                        // than fall through to the main session, which would land a
                        // board wake / bg-autoresume / worker dispatch in the wrong
                        // mission. The scheduler re-issues on its next pass.
                        //
                        // When the target IS the main session's mission, there is
                        // no leak: Case 3 below is exactly where we want it — it
                        // activates an idle/AwaitingUser main mission and starts a
                        // fresh turn (e.g. the bg-task auto-resume waking a mission
                        // that parked on the user while a background job ran).
                        if strict && !target_is_main {
                            tracing::warn!(
                                target = ?effective_target,
                                "Dropping strict control-plane message: non-main target not deliverable this pass"
                            );
                            let _ = respond.send(UserMessageAck::Dropped);
                            continue;
                        }

                        // Case 3: Queue to main session (default behavior)
                        // Auto-create mission on first message if none exists
                        {
                            let mission_id = *current_mission.read().await;
                            if mission_id.is_none() {
                                // Use effective_target if available, otherwise create new
                                if let Some(tid) = effective_target {
                                    // Load mission history from DB so continuation detection
                                    // works correctly (e.g., after server restart when
                                    // current_mission is None but the mission has prior turns).
                                    if let Ok(mission) = load_mission_record(&mission_store, tid).await {
                                        if !mission.history.is_empty() {
                                            history.clear();
                                            for entry in &mission.history {
                                                history.push((entry.role.clone(), entry.content.clone()));
                                            }
                                            tracing::info!(
                                                "Loaded {} history entries for target mission {} (first message after session start)",
                                                mission.history.len(), tid
                                            );
                                        }
                                        if let Err(error) = activate_mission_for_message(
                                            &control_hub,
                                            &mission_store,
                                            &events_tx,
                                            &mission,
                                            &content,
                                        )
                                        .await
                                        {
                                            let _ = events_tx.send(AgentEvent::Error {
                                                message: format!(
                                                    "Cannot activate mission {}: {}",
                                                    tid, error
                                                ),
                                                mission_id: Some(tid),
                                                resumable: true,
                                            });
                                            let _ = respond.send(UserMessageAck::Rejected(error));
                                            continue;
                                        }
                                    }
                                    *current_mission.write().await = Some(tid);
                                    tracing::info!("Set current mission to target: {}", tid);
                                } else if let Ok(new_mission) = create_new_mission(&mission_store).await {
                                    *current_mission.write().await = Some(new_mission.id);
                                    tracing::info!("Auto-created mission: {}", new_mission.id);
                                }
                            } else if let Some(tid) = effective_target {
                                if !main_is_running {
                                    if mission_id != Some(tid) {
                                        // Switch main session to target mission
                                        persist_mission_history(
                                            &mission_store,
                                            &events_tx,
                                            &current_mission,
                                            &history,
                                        )
                                        .await;
                                        if let Ok(mission) = load_mission_record(&mission_store, tid).await {
                                            history.clear();
                                            for entry in &mission.history {
                                                history.push((entry.role.clone(), entry.content.clone()));
                                            }
                                            if let Err(error) = activate_mission_for_message(
                                                &control_hub,
                                                &mission_store,
                                                &events_tx,
                                                &mission,
                                                &content,
                                            )
                                            .await
                                            {
                                                let _ = events_tx.send(AgentEvent::Error {
                                                    message: format!(
                                                        "Cannot activate mission {}: {}",
                                                        tid, error
                                                    ),
                                                    mission_id: Some(tid),
                                                    resumable: true,
                                                });
                                                let _ = respond.send(UserMessageAck::Rejected(error));
                                                continue;
                                            }
                                        }
                                        *current_mission.write().await = Some(tid);
                                        tracing::info!("Switched main session to mission: {}", tid);
                                    } else if !history.iter().any(|(role, _)| role == "assistant") {
                                        // Same mission but no assistant history in memory
                                        // (e.g., after server restart). Reload from database
                                        // so Claude Code continuation detection works correctly.
                                        if let Ok(mission) = load_mission_record(&mission_store, tid).await {
                                            if !mission.history.is_empty() {
                                                history.clear();
                                                for entry in &mission.history {
                                                    history.push((entry.role.clone(), entry.content.clone()));
                                                }
                                                tracing::info!(
                                                    "Reloaded {} history entries for mission {} (session continuity)",
                                                    mission.history.len(), tid
                                                );
                                            }
                                            if let Err(error) = activate_mission_for_message(
                                                &control_hub,
                                                &mission_store,
                                                &events_tx,
                                                &mission,
                                                &content,
                                            )
                                            .await
                                            {
                                                let _ = events_tx.send(AgentEvent::Error {
                                                    message: format!(
                                                        "Cannot activate mission {}: {}",
                                                        tid, error
                                                    ),
                                                    mission_id: Some(tid),
                                                    resumable: true,
                                                });
                                                let _ = respond.send(UserMessageAck::Rejected(error));
                                                continue;
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        let was_running = running.is_some();
                        let content_clone = content.clone();
                        // Capture the target mission ID once, before queuing.
                        // This ensures we use the same mission_id for events and execution.
                        //
                        // Honor the message's EXPLICIT target; fall back to the session
                        // `current_mission` pointer only for untargeted messages. We only
                        // reach Case 3 when the target is absent or equals the main mission
                        // (`target_is_main`), so an explicit `effective_target` here is the
                        // main mission the runner is on — and its history is already what
                        // the next turn will use. Previously this read `*current_mission`
                        // unconditionally: when the runner was busy on one mission
                        // (`running_mission_id`) while the session pointer had drifted to
                        // another (e.g. the dashboard/MCP moved it), an explicitly-targeted
                        // follow-up got silently re-pinned to the drifted mission and
                        // executed there. (Prod 2026-06-23: a Hermes follow-up for mission
                        // 91f7… ran in the unrelated 4f3f… instead.)
                        let target_mission_id = match effective_target {
                            Some(tid) => Some(tid),
                            None => *current_mission.read().await,
                        };
                        if was_running {
                            if let Some(tid) = target_mission_id {
                                if let Ok(Some(mission)) = mission_store.get_mission(tid).await {
                                    if let Err(error) = activate_mission_for_message(
                                        &control_hub,
                                        &mission_store,
                                        &events_tx,
                                        &mission,
                                        &content,
                                    )
                                    .await
                                    {
                                        let _ = events_tx.send(AgentEvent::Error {
                                            message: format!(
                                                "Cannot apply writer lease for mission {}: {}",
                                                tid, error
                                            ),
                                            mission_id: Some(tid),
                                            resumable: true,
                                        });
                                        let _ = respond.send(UserMessageAck::Rejected(error));
                                        continue;
                                    }
                                }
                            }
                        }
                        enqueue_control_message(
                            &mut queue,
                            (id, content, msg_agent, target_mission_id, source.clone()),
                        );
                        // `Queued` is an acceptance acknowledgement. Persist the
                        // message before sending it so a crash cannot lose an
                        // outbox delivery that its producer has already retired.
                        if let Err(error) = persist_control_queue_if_changed(
                            &mission_store,
                            &session_user_id,
                            &queue,
                            &parallel_runners,
                            &recovered_consumed_user_messages,
                            &mut last_persisted_queue,
                        )
                        .await
                        {
                            queue.retain(|(queued_id, ..)| *queued_id != id);
                            accepted_user_message_ids.remove(&id);
                            let _ = respond.send(UserMessageAck::Rejected(format!(
                                "failed to persist queued delivery: {error}"
                            )));
                            continue;
                        }
                        let status_mission_id = if running.is_some() {
                            running_mission_id
                        } else {
                            target_mission_id
                        };
                        set_and_emit_status(
                            &status,
                            &events_tx,
                            if running.is_some() { ControlRunState::Running } else { ControlRunState::Idle },
                            queue.len(),
                            status_mission_id,
                        ).await;
                        if was_running {
                            let _ = events_tx.send(AgentEvent::UserMessage {
                                id,
                                content: content_clone,
                                queued: true,
                                mission_id: target_mission_id,
                                source: source.clone(),
                            });
                        }
                        if running.is_none() {
                            if let Some((mid, msg, per_msg_agent, msg_target_mid, msg_source)) = pop_next_runnable_control_queue(&mut queue, &mission_store).await {
                                // Persist the dequeue before the awaits that start
                                // the run, so a crash here can't restore + re-run it.
                                if let Err(error) = persist_control_queue_if_changed(
                                    &mission_store,
                                    &session_user_id,
                                    &queue,
                                    &parallel_runners,
                                    &recovered_consumed_user_messages,
                                    &mut last_persisted_queue,
                                )
                                .await
                                {
                                    queue.push_front((
                                        mid,
                                        msg,
                                        per_msg_agent,
                                        msg_target_mid,
                                        msg_source,
                                    ));
                                    let _ = respond.send(UserMessageAck::Queued);
                                    tracing::warn!(
                                        "Queued delivery retained because dequeue persistence failed: {error}"
                                    );
                                    continue;
                                }
                                set_and_emit_status(
                                    &status,
                                    &events_tx,
                                    ControlRunState::Running,
                                    queue.len(),
                                    msg_target_mid,
                                ).await;
                                let _ = events_tx.send(AgentEvent::UserMessage { id: mid, content: msg.clone(), queued: false, mission_id: msg_target_mid, source: msg_source.clone() });

                                // Immediately persist user message so it's visible when loading mission
                                history.push(("user".to_string(), msg.clone()));
                                persist_mission_history_to(
                                    &mission_store,
                                    &events_tx,
                                    msg_target_mid,
                                    &history,
                                )
                                    .await;

                                let cfg = config.clone();
                                let agent = Arc::clone(&root_agent);
                                let mcp_ref = Arc::clone(&mcp);
                                let workspaces_ref = Arc::clone(&workspaces);
                                let library_ref = Arc::clone(&library);
                                let events = events_tx.clone();
                                let tools_hub = Arc::clone(&tool_hub);
                                let status_ref = Arc::clone(&status);
                                let cancel = CancellationToken::new();
                                let hist_snapshot = history.clone();
                                let mission_ctrl = crate::tools::mission::MissionControl {
                                    current_mission_id: Arc::clone(&current_mission),
                                    cmd_tx: mission_cmd_tx.clone(),
                                };
                                let tree_ref = Arc::clone(&current_tree);
                                let progress_ref = Arc::clone(&progress);
                                // Use the mission ID that was captured when message was queued
                                // This prevents race conditions where current_mission changes between queueing and execution
                                let mission_id = msg_target_mid;
                                let (workspace_id, model_override, model_effort, fast_mode, mission_agent, backend_id, session_id, mission_config_profile, pr_readonly) = if let Some(mid) = mission_id {
                                    match mission_store.get_mission(mid).await {
                                        Ok(Some(mission)) => {
                                            if let Err(error) = activate_mission_for_message(
                                                &control_hub,
                                                &mission_store,
                                                &events_tx,
                                                &mission,
                                                &msg,
                                            )
                                            .await
                                            {
                                                let _ = events_tx.send(AgentEvent::Error {
                                                    message: format!(
                                                        "Cannot activate mission {}: {}",
                                                        mid, error
                                                    ),
                                                    mission_id: Some(mid),
                                                    resumable: true,
                                                });
                                                let _ = respond.send(UserMessageAck::Rejected(error));
                                                continue;
                                            }
                                            (
                                                Some(mission.workspace_id),
                                                mission.model_override.clone(),
                                                mission.model_effort.clone(),
                                                mission.fast_mode,
                                                mission.agent.clone(),
                                                Some(mission.backend.clone()),
                                                mission.session_id.clone(),
                                                mission.config_profile.clone(),
                                                mission.project.tags.iter().any(|tag| tag == "pr-readonly"),
                                            )
                                        }
                                        Ok(None) => {
                                            tracing::warn!(
                                                "Mission {} not found while resolving workspace",
                                                mid
                                            );
                                            (None, None, None, false, None, None, None, None, false)
                                        }
                                        Err(e) => {
                                            tracing::warn!(
                                                "Failed to load mission {} for workspace: {}",
                                                mid,
                                                e
                                            );
                                            (None, None, None, false, None, None, None, None, false)
                                        }
                                    }
                                } else {
                                    (None, None, None, false, None, None, None, None, false)
                                };
                                // Per-message agent overrides mission agent
                                let agent_override = per_msg_agent.or(mission_agent);
                                running_cancel = Some(cancel.clone());
                                running_mission_id = mission_id;
                                running_backend_id = backend_id.clone();
                                // Reset activity tracking when new task starts
                                main_runner_last_activity = std::time::Instant::now();
                                main_runner_activity = None;
                                main_runner_subtasks.clear();
                                main_runner_active_tool_calls
                                    .store(0, std::sync::atomic::Ordering::Relaxed);
                                let user_id_for_turn = session_user_id.clone();
                                running_run = match acquire_execution_run(
                                    &mission_store,
                                    mission_id,
                                    &format!("control:{session_user_id}"),
                                )
                                .await
                                {
                                    Ok(run) => run,
                                    Err(error) => {
                                        running_cancel = None;
                                        running_mission_id = None;
                                        running_backend_id = None;
                                        // The queue dequeue was already persisted, but no
                                        // run owns this delivery. Roll back the just-appended
                                        // history entry and release the deterministic message
                                        // id so the caller/outbox can retry it safely.
                                        if history.last().is_some_and(|entry| {
                                            entry.0 == "user" && entry.1 == msg
                                        }) {
                                            history.pop();
                                            persist_mission_history_to(
                                                &mission_store,
                                                &events_tx,
                                                msg_target_mid,
                                                &history,
                                            )
                                            .await;
                                        }
                                        accepted_user_message_ids.remove(&mid);
                                        set_and_emit_status(
                                            &status,
                                            &events_tx,
                                            ControlRunState::Idle,
                                            queue.len(),
                                            msg_target_mid,
                                        )
                                        .await;
                                        let _ = respond.send(UserMessageAck::Rejected(error.clone()));
                                        let _ = events_tx.send(AgentEvent::Error {
                                            message: format!("Mission run lease rejected: {error}"),
                                            mission_id,
                                            resumable: true,
                                        });
                                        continue;
                                    }
                                };
                                running = Some(tokio::spawn(async move {
                                    let result = run_single_control_turn(
                                        cfg,
                                        agent,
                                        mcp_ref,
                                        workspaces_ref,
                                        library_ref,
                                        events,
                                        tools_hub,
                                        status_ref,
                                        cancel,
                                        hist_snapshot,
                                        msg.clone(),
                                        Some(mission_ctrl),
                                        tree_ref,
                                        progress_ref,
                                        mission_id,
                                        workspace_id,
                                        backend_id,
                                        model_override,
                                        model_effort,
                                        fast_mode,
                                        agent_override,
                                        session_id,
                                        false, // force_session_resume: regular message, not a resume
                                        mission_config_profile,
                                        Some(user_id_for_turn),
                                        pr_readonly,
                                    )
                                    .await;
                                    (mid, msg, result)
                                }));
                            } else {
                                set_and_emit_status(&status, &events_tx, ControlRunState::Idle, 0, None).await;
                            }
                        }
                        let _ = respond.send(if was_running { UserMessageAck::Queued } else { UserMessageAck::Delivered });
                    }
                    ControlCommand::ReleaseUserMessageId { id } => {
                        accepted_user_message_ids.remove(&id);
                    }
                    ControlCommand::ToolResult { tool_call_id, name, result, respond } => {
                        // Deliver to the tool hub. resolve() caches the result if
                        // no one has registered yet (resolve-before-register), and
                        // reports whether a live waiter actually received it. It
                        // may wait out a short grace window for an imminent
                        // registration, so run it off the control loop to keep
                        // command processing responsive.
                        let hub = Arc::clone(&tool_hub);
                        tokio::spawn(async move {
                            let delivered = hub.resolve(&tool_call_id, result).await;
                            let _ = respond.send(delivered);
                            tracing::debug!(tool_call_id = %tool_call_id, name = %name, delivered, "ToolResult delivered to hub");
                        });
                    }
                    ControlCommand::Cancel => {
                        if let Some(token) = &running_cancel {
                            token.cancel();
                            if let Some(run) = running_run.as_ref() {
                                let _ = mission_store
                                    .heartbeat_mission_run(
                                        run.run_id,
                                        run.generation,
                                        MissionExecutionState::Stopping,
                                        None,
                                    )
                                    .await;
                            }
                            // Don't send Error event here - the task will complete and send
                            // an AssistantMessage with the cancellation result when it finishes.
                            // Sending both causes duplicate UI messages.
                        } else {
                            let _ = events_tx.send(AgentEvent::Error { message: "No running task to cancel".to_string(), mission_id: None, resumable: false });
                        }
                    }
                    ControlCommand::LoadMission { id, respond } => {
                        // First persist current mission history
                        persist_mission_history(
                            &mission_store,
                            &events_tx,
                            &current_mission,
                            &history,
                        )
                        .await;

                        // Load the new mission
                        match load_mission_record(
                            &mission_store,
                            id,
                        )
                        .await {
                            Ok(mission) => {
                                // Update history from loaded mission
                                history = mission.history.iter()
                                    .map(|e| (e.role.clone(), e.content.clone()))
                                    .collect();
                                *current_mission.write().await = Some(id);

                                // Write runtime workspace state so file uploads work immediately
                                // (without needing to send a message first)
                                let ws = workspace::resolve_workspace(
                                    &workspaces,
                                    &config,
                                    Some(mission.workspace_id),
                                ).await;
                                if let Err(e) = workspace::write_runtime_workspace_state(
                                    &config.working_dir,
                                    &ws,
                                    &ws.path,
                                    Some(id),
                                    &config.context.context_dir_name,
                                ).await {
                                    tracing::warn!("Failed to write runtime workspace state on load: {}", e);
                                }

                                let _ = respond.send(Ok(mission));
                            }
                            Err(e) => {
                                let _ = respond.send(Err(e));
                            }
                        }
                    }
                    ControlCommand::CreateMission { title, workspace_id, agent, model_override, model_effort, fast_mode, backend, config_profile, parent_mission_id, working_directory, scheduling, requires_local_disk, respond } => {
                        // Disk preflight: refuse new missions when the root
                        // filesystem is critically full instead of letting
                        // workers die mid-flight on ENOSPC. Actor-level so
                        // the HTTP, Ask and Telegram entrypoints are all
                        // covered by this single gate.
                        if requires_local_disk {
                            if let Some(refusal) = disk_admission_refusal() {
                                let _ = respond.send(Err(refusal));
                                continue;
                            }
                        }
                        // First persist current mission history
                        persist_mission_history(
                            &mission_store,
                            &events_tx,
                            &current_mission,
                            &history,
                        )
                        .await;

                        // Create a new mission with optional title, workspace, agent, and backend
                        match create_new_mission_with_title(
                            &mission_store,
                            title.as_deref(),
                            workspace_id,
                            agent.as_deref(),
                            model_override.as_deref(),
                            model_effort.as_deref(),
                            fast_mode,
                            backend.as_deref(),
                            config_profile.as_deref(),
                            parent_mission_id,
                            working_directory.as_deref(),
                            scheduling,
                        )
                        .await {
                            Ok(mission) => {
                                history.clear();
                                *current_mission.write().await = Some(mission.id);

                                // Write runtime workspace state so file uploads work immediately
                                let ws = workspace::resolve_workspace(
                                    &workspaces,
                                    &config,
                                    Some(mission.workspace_id),
                                ).await;
                                if let Err(e) = workspace::write_runtime_workspace_state(
                                    &config.working_dir,
                                    &ws,
                                    &ws.path,
                                    Some(mission.id),
                                    &config.context.context_dir_name,
                                ).await {
                                    tracing::warn!("Failed to write runtime workspace state on create: {}", e);
                                }

                                let _ = respond.send(Ok(mission));
                            }
                            Err(e) => {
                                let _ = respond.send(Err(e));
                            }
                        }
                    }
                    ControlCommand::SetMissionStatus { id, status: new_status, respond } => {
                        let current_id = *current_mission.read().await;
                        if current_id == Some(id) {
                            if let Some(tree) = current_tree.read().await.clone() {
                                if let Err(e) = mission_store.update_mission_tree(id, &tree).await
                                {
                                    tracing::warn!("Failed to save mission tree: {}", e);
                                }
                            }
                        }

                        let result = mission_store
                            .update_mission_status(id, new_status)
                            .await;
                        if result.is_ok() {
                            maybe_schedule_mission_metadata_refresh_for_status(
                                &mission_store,
                                &events_tx,
                                id,
                                new_status,
                            );
                            let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                mission_id: id,
                                status: new_status,
                                summary: None,
                            });
                        }
                        let _ = respond.send(result);
                    }
                    ControlCommand::SetMissionTitle { id, title, respond } => {
                        let result = mission_store.update_mission_title(id, &title).await;
                        if result.is_ok() {
                            let _ = events_tx.send(AgentEvent::MissionTitleChanged {
                                mission_id: id,
                                title: title.clone(),
                            });
                            match mission_store.get_mission(id).await {
                                Ok(Some(updated)) => {
                                    record_metadata_refresh_baseline_from_mission(id, &updated);
                                    emit_mission_metadata_updated_event(&events_tx, id, &updated);
                                }
                                Ok(None) => {
                                    tracing::warn!(
                                        "Mission {} disappeared after title update",
                                        id
                                    );
                                }
                                Err(err) => {
                                    tracing::warn!(
                                        "Failed to reload mission {} after title update: {}",
                                        id,
                                        err
                                    );
                                }
                            }
                        }
                        let _ = respond.send(result);
                    }
                    ControlCommand::UpdateMissionSettings { id, backend, agent, model_override, model_effort, fast_mode, config_profile, session_id, respond } => {
                        let main_running = running.is_some() && running_mission_id == Some(id);
                        let parallel_running = parallel_runners
                            .get(&id)
                            .is_some_and(|runner| runner.is_running());
                        // Run-settings (backend/model/agent/profile) are read
                        // per turn, so changing them on a RUNNING mission is
                        // safe: the in-flight turn keeps what it loaded and the
                        // next turn picks up the new row (with the backend
                        // handoff context below when the backend changed).
                        // Long-lived missions (orchestrators, /goal loops)
                        // rarely stop, so the previous hard refusal made them
                        // effectively unswitchable. The fresh session id this
                        // writes is also fine mid-run: every backend falls
                        // back to a fresh/continued session when the stored id
                        // is not loadable.
                        if main_running || parallel_running {
                            tracing::info!(
                                mission_id = %id,
                                "Updating run settings while mission is running; they apply from the next turn"
                            );
                        }

                        // Capture the backend before the update so we can detect
                        // a switch and carry reasoning across (see below).
                        let old_backend = load_mission_record(&mission_store, id)
                            .await
                            .ok()
                            .map(|m| m.backend);

                        let result = mission_store
                            .update_mission_run_settings(
                                id,
                                backend.as_deref(),
                                agent.as_ref().map(|value| value.as_deref()),
                                model_override.as_ref().map(|value| value.as_deref()),
                                model_effort.as_ref().map(|value| value.as_deref()),
                                fast_mode,
                                config_profile.as_ref().map(|value| value.as_deref()),
                                &session_id,
                            )
                            .await;

                        if let Ok(updated) = result.as_ref() {
                            let _ = events_tx.send(AgentEvent::MissionSettingsUpdated {
                                mission_id: id,
                                backend: updated.backend.clone(),
                                agent: updated.agent.clone(),
                                model_override: updated.model_override.clone(),
                                model_effort: updated.model_effort.clone(),
                                fast_mode: updated.fast_mode,
                                config_profile: updated.config_profile.clone(),
                                session_id: updated.session_id.clone(),
                                updated_at: updated.updated_at.clone(),
                            });

                            // Backend switch handoff: the new backend starts a
                            // fresh session and can't replay the old backend's
                            // reasoning format, so carry the recent reasoning
                            // forward as a plain-text context message. It lands
                            // in the conversation history and is picked up by
                            // the next turn (resume or message) on either
                            // backend. Workspace + transcript carry over already.
                            let backend_switched = old_backend
                                .as_deref()
                                .map(|prev| prev != updated.backend.as_str())
                                .unwrap_or(false);
                            if backend_switched {
                                let prev = old_backend.as_deref().unwrap_or("the previous backend");
                                if let Some(handoff) = build_backend_handoff_context(
                                    &mission_store,
                                    id,
                                    prev,
                                    &updated.backend,
                                )
                                .await
                                {
                                    let event = AgentEvent::UserMessage {
                                        id: Uuid::new_v4(),
                                        content: handoff,
                                        queued: false,
                                        mission_id: Some(id),
                                        source: None,
                                    };
                                    if let Err(e) = mission_store.log_event(id, &event).await {
                                        tracing::warn!(
                                            mission_id = %id,
                                            error = %e,
                                            "Failed to persist backend handoff context"
                                        );
                                    }
                                    let _ = events_tx.send(event);
                                    tracing::info!(
                                        mission_id = %id,
                                        old_backend = ?old_backend,
                                        new_backend = %updated.backend,
                                        "Injected backend-switch handoff context to preserve reasoning"
                                    );
                                }
                            }
                        }

                        let _ = respond.send(result);
                    }
                    ControlCommand::StartParallel { mission_id, content, respond } => {
                        tracing::info!("StartParallel requested for mission {}", mission_id);

                        // Count currently running parallel missions
                        let parallel_running = parallel_runners.values().filter(|r| r.is_running()).count();
                        let main_running = if running.is_some() { 1 } else { 0 };
                        let total_running = parallel_running + main_running;
                        let max_parallel = crate::settings::max_parallel_missions_cached_or(config.max_parallel_missions);

                        if total_running >= max_parallel {
                            let _ = respond.send(Err(format!(
                                "Maximum parallel missions ({}) reached. {} running.",
                                max_parallel, total_running
                            )));
                        } else if let std::collections::hash_map::Entry::Vacant(entry) =
                            parallel_runners.entry(mission_id)
                        {
                            // Load mission to get existing history
                            let mission = match load_mission_record(&mission_store, mission_id).await {
                                Ok(m) => m,
                                Err(e) => {
                                    let _ = respond.send(Err(format!("Failed to load mission: {}", e)));
                                    continue;
                                }
                            };

                            // Don't start a paused mission — resume it explicitly first.
                            if mission.status == MissionStatus::Paused {
                                let _ = respond.send(Err(format!(
                                    "Mission {} is paused; resume it before starting",
                                    mission_id
                                )));
                                continue;
                            }

                            if let Err(error) = activate_mission_for_message(
                                &control_hub,
                                &mission_store,
                                &events_tx,
                                &mission,
                                &content,
                            )
                            .await
                            {
                                let _ = respond.send(Err(format!(
                                    "Failed to activate mission before starting: {error}"
                                )));
                                continue;
                            }

                            // Create a new MissionRunner
                            let mut runner = super::mission_runner::MissionRunner::new(
                                mission_id,
                                mission.workspace_id,
                                mission.agent.clone(),
                                Some(mission.backend.clone()),
                                mission.session_id.clone(),
                                mission.config_profile.clone(),
                                mission.model_override.clone(),
                                mission.model_effort.clone(),
                                mission.fast_mode,
                            );
                            runner.pr_readonly = mission.project.tags.iter().any(|tag| tag == "pr-readonly");
                            runner.working_directory = mission.working_directory.clone();
                            runner.user_id = Some(session_user_id.clone());

                            // Load existing history into runner to preserve conversation context
                            for entry in &mission.history {
                                runner.history.push((entry.role.clone(), entry.content.clone()));
                            }

                            // Queue the initial message (no per-message agent override for parallel start)
                            runner.queue_message(Uuid::new_v4(), content, None, None);

                            // Start execution
                            if let Err(error) = runner
                                .acquire_durable_run(
                                    &mission_store,
                                    &format!("control:{session_user_id}"),
                                )
                                .await
                            {
                                let rollback = restore_mission_after_failed_run_acquisition(
                                    &mission_store,
                                    &events_tx,
                                    &mission,
                                )
                                .await;
                                let _ = respond.send(Err(format!(
                                    "Failed to acquire mission run lease: {error}{}",
                                    rollback
                                        .err()
                                        .map(|rollback_error| format!(
                                            "; failed to restore {} status: {rollback_error}",
                                            mission.status
                                        ))
                                        .unwrap_or_default()
                                )));
                                continue;
                            }
                            let started = runner.start_next(
                                config.clone(),
                                Arc::clone(&root_agent),
                                Arc::clone(&mcp),
                                Arc::clone(&workspaces),
                                library.clone(),
                                events_tx.clone(),
                                Arc::clone(&tool_hub),
                                Arc::clone(&status),
                                mission_cmd_tx.clone(),
                                Arc::new(RwLock::new(Some(mission_id))), // Each runner tracks its own mission
                                secrets.clone(),
                            );

                            if started {
                                tracing::info!("Mission {} started in parallel", mission_id);
                                entry.insert(runner);
                                let _ = respond.send(Ok(()));
                            } else {
                                let _ = respond.send(Err("Failed to start mission execution".to_string()));
                            }
                        } else {
                            let _ = respond.send(Err(format!(
                                "Mission {} is already running in parallel",
                                mission_id
                            )));
                        }
                    }
                    ControlCommand::CancelMission { mission_id, min_idle, respond } => {
                        // Race-protect background cancels (watchdog, stale-cleanup):
                        // if the caller asked us to only cancel when truly idle and the
                        // mission has touched activity in the meantime, skip the cancel.
                        // This catches the case where the watchdog observed N seconds of
                        // silence, sent CancelMission, and a streaming response arrived
                        // before the actor got around to processing the command.
                        if let Some(min_idle) = min_idle {
                            let idle = if let Some(runner) = parallel_runners.get(&mission_id) {
                                Some(runner.last_activity.elapsed())
                            } else if running_mission_id == Some(mission_id) {
                                Some(main_runner_last_activity.elapsed())
                            } else {
                                None
                            };
                            if let Some(idle) = idle {
                                if idle < min_idle {
                                    tracing::info!(
                                        mission_id = %mission_id,
                                        idle_secs = idle.as_secs(),
                                        threshold_secs = min_idle.as_secs(),
                                        "Skipping watchdog/cleanup cancel: mission resumed activity before cancel was processed"
                                    );
                                    let _ = respond.send(Ok(
                                        CancelMissionOutcome::SkippedRecentlyActive,
                                    ));
                                    continue;
                                }
                            }
                        }
                        // Helper: cascade-cancel all child missions of the given parent.
                        async fn cancel_child_missions(
                            parent_id: Uuid,
                            mission_store: &Arc<dyn MissionStore>,
                            parallel_runners: &mut HashMap<Uuid, super::mission_runner::MissionRunner>,
                            events_tx: &tokio::sync::broadcast::Sender<AgentEvent>,
                            working_dir: &std::path::Path,
                        ) {
                            let children = match mission_store.get_child_missions(parent_id).await {
                                Ok(c) => c,
                                Err(e) => {
                                    tracing::warn!("Failed to fetch child missions for cascade cancel: {}", e);
                                    return;
                                }
                            };
                            for child in children {
                                if matches!(child.status, MissionStatus::Completed | MissionStatus::Failed | MissionStatus::Interrupted | MissionStatus::NotFeasible) {
                                    continue;
                                }
                                // Cancel runner if running
                                if let Some(runner) = parallel_runners.get_mut(&child.id) {
                                    runner.cancel();
                                    if let Some(run) = runner.durable_run.as_ref() {
                                        let _ = mission_store
                                            .heartbeat_mission_run(
                                                run.run_id,
                                                run.generation,
                                                MissionExecutionState::Stopping,
                                                None,
                                            )
                                            .await;
                                    }
                                    // Keep the runner registered until its task
                                    // actually exits; dropping the JoinHandle
                                    // here would detach live work.
                                    continue;
                                }
                                if let Err(e) = mission_store
                                    .update_mission_status(child.id, MissionStatus::Interrupted)
                                    .await
                                {
                                    tracing::warn!("Failed to cancel child mission {}: {}", child.id, e);
                                } else {
                                    let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                        mission_id: child.id,
                                        status: MissionStatus::Interrupted,
                                        summary: None,
                                    });
                                }
                                close_mission_desktop_sessions(mission_store, child.id, working_dir).await;
                            }
                        }

                        // First check parallel runners
                        if let Some(runner) = parallel_runners.get_mut(&mission_id) {
                            runner.cancel();
                            if let Some(run) = runner.durable_run.as_ref() {
                                let _ = mission_store
                                    .heartbeat_mission_run(
                                        run.run_id,
                                        run.generation,
                                        MissionExecutionState::Stopping,
                                        None,
                                    )
                                    .await;
                            }
                            let _ = events_tx.send(AgentEvent::Error {
                                message: format!("Parallel mission {} cancellation requested", mission_id),
                                mission_id: Some(mission_id),
                                resumable: true, // Cancelled missions can be resumed
                            });
                            // Cascade cancel child missions
                            cancel_child_missions(mission_id, &mission_store, &mut parallel_runners, &events_tx, &config.working_dir).await;
                            if let Err(error) = persist_control_queue_if_changed(
                                &mission_store,
                                &session_user_id,
                                &queue,
                                &parallel_runners,
                                &recovered_consumed_user_messages,
                                &mut last_persisted_queue,
                            )
                            .await
                            {
                                tracing::warn!(mission_id = %mission_id,
                                    "Failed to persist cleared queues after cancellation: {error}");
                            }
                            let _ = respond.send(Ok(CancelMissionOutcome::Cancelled));
                        } else {
                            // Check if this is the currently executing mission
                            // Use running_mission_id (the actual mission being executed)
                            // instead of current_mission (which can change when user creates a new mission)
                            if running_mission_id == Some(mission_id) {
                                // Cancel the current execution
                                if let Some(token) = &running_cancel {
                                    token.cancel();
                                    if let Some(run) = running_run.as_ref() {
                                        let _ = mission_store
                                            .heartbeat_mission_run(
                                                run.run_id,
                                                run.generation,
                                                MissionExecutionState::Stopping,
                                                None,
                                            )
                                            .await;
                                    }
                                    // Arm the force-clear deadline. Most cancels
                                    // wind down within a few seconds via the
                                    // task's own observation of the cancel
                                    // token; the deadline catches the zombie
                                    // case where the underlying CLI subprocess
                                    // is dead/blocked and the JoinHandle never
                                    // resolves on its own.
                                    runner_force_clear_deadline = Some(
                                        tokio::time::Instant::now()
                                            + RUNNER_FORCE_CLEAR_GRACE,
                                    );
                                    close_mission_desktop_sessions(
                                        &mission_store,
                                        mission_id,
                                        &config.working_dir,
                                    )
                                    .await;
                                    // Don't send Error event here - the task will complete and send
                                    // an AssistantMessage with resumable=true when it finishes.
                                    // Sending both causes duplicate UI messages.
                                    // Cascade cancel child missions
                                    cancel_child_missions(mission_id, &mission_store, &mut parallel_runners, &events_tx, &config.working_dir).await;
                                    let _ = respond.send(Ok(CancelMissionOutcome::Cancelled));
                                } else {
                                    let _ = respond.send(Err("Mission not currently executing".to_string()));
                                }
                            } else {
                                // A mission can exist durably without owning a
                                // runner yet (for example a scheduled/deferred
                                // Pending mission). Cancellation must still
                                // release it, otherwise deferred work and PR
                                // writer leases can become impossible to clear.
                                // Existing terminal rows are an idempotent
                                // success so cleanup loops do not trip their
                                // circuit breaker by cancelling twice.
                                match mission_store.get_mission(mission_id).await {
                                    Ok(Some(mission)) if mission.status == MissionStatus::Interrupted
                                        || mission.status.is_terminal()
                                        || mission.status == MissionStatus::Acknowledged =>
                                    {
                                        if let Err(error) = finish_detached_run_for_cancel(
                                            &mission_store,
                                            mission_id,
                                        )
                                        .await
                                        {
                                            let _ = respond.send(Err(format!(
                                                "Failed to settle detached mission run: {error}"
                                            )));
                                            continue;
                                        }
                                        let _ = respond.send(Ok(CancelMissionOutcome::Cancelled));
                                    }
                                    Ok(Some(_)) => {
                                        if let Err(error) = finish_detached_run_for_cancel(
                                            &mission_store,
                                            mission_id,
                                        )
                                        .await
                                        {
                                            let _ = respond.send(Err(format!(
                                                "Failed to settle detached mission run: {error}"
                                            )));
                                            continue;
                                        }
                                        let update = mission_store
                                            .update_mission_status(
                                                mission_id,
                                                MissionStatus::Interrupted,
                                            )
                                            .await;
                                        if let Err(error) = update {
                                            let _ = respond.send(Err(error));
                                            continue;
                                        }
                                        let _ = mission_store
                                            .set_deferred_goal(mission_id, None)
                                            .await;
                                        let _ = events_tx.send(
                                            AgentEvent::MissionStatusChanged {
                                                mission_id,
                                                status: MissionStatus::Interrupted,
                                                summary: None,
                                            },
                                        );
                                        close_mission_desktop_sessions(
                                            &mission_store,
                                            mission_id,
                                            &config.working_dir,
                                        )
                                        .await;
                                        cancel_child_missions(
                                            mission_id,
                                            &mission_store,
                                            &mut parallel_runners,
                                            &events_tx,
                                            &config.working_dir,
                                        )
                                        .await;
                                        let _ = respond.send(Ok(CancelMissionOutcome::Cancelled));
                                    }
                                    Ok(None) => {
                                        let _ = respond.send(Err(format!(
                                            "Mission {} not found",
                                            mission_id
                                        )));
                                    }
                                    Err(error) => {
                                        let _ = respond.send(Err(error));
                                    }
                                }
                            }
                        }
                    }
                    ControlCommand::PauseMission { mission_id, respond } => {
                        // Stop any in-flight runner before parking the mission so
                        // the agent turn can't keep executing (and overwrite the
                        // paused status on completion). Mirrors CancelMission's
                        // stop logic but lands on `Paused` instead of `Interrupted`.
                        if let Some(runner) = parallel_runners.get_mut(&mission_id) {
                            runner.cancel();
                            if let Some(run) = runner.durable_run.as_ref() {
                                let _ = mission_store
                                    .heartbeat_mission_run(
                                        run.run_id,
                                        run.generation,
                                        MissionExecutionState::Stopping,
                                        None,
                                    )
                                    .await;
                            }
                            close_mission_desktop_sessions(
                                &mission_store,
                                mission_id,
                                &config.working_dir,
                            )
                            .await;
                        } else if running_mission_id == Some(mission_id) {
                            if let Some(token) = &running_cancel {
                                token.cancel();
                                if let Some(run) = running_run.as_ref() {
                                    let _ = mission_store
                                        .heartbeat_mission_run(
                                            run.run_id,
                                            run.generation,
                                            MissionExecutionState::Stopping,
                                            None,
                                        )
                                        .await;
                                }
                                // Arm the force-clear deadline so a zombie runner
                                // that never observes the cancel still gets torn
                                // down (matches CancelMission).
                                runner_force_clear_deadline = Some(
                                    tokio::time::Instant::now() + RUNNER_FORCE_CLEAR_GRACE,
                                );
                            }
                            close_mission_desktop_sessions(
                                &mission_store,
                                mission_id,
                                &config.working_dir,
                            )
                            .await;
                        }

                        // Set Paused last so it survives the runner teardown above.
                        // maybe_finalize_terminal_mission skips non-Active/Pending/
                        // Interrupted statuses, so the cancelled turn's completion
                        // won't promote this back out of Paused.
                        match mission_store
                            .update_mission_status(mission_id, MissionStatus::Paused)
                            .await
                        {
                            Ok(()) => {
                                // FLEET-004: stamp the pause time for UI pause-age.
                                let _ = mission_store
                                    .set_mission_paused_at(
                                        mission_id,
                                        Some(chrono::Utc::now().to_rfc3339()),
                                    )
                                    .await;
                                let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                    mission_id,
                                    status: MissionStatus::Paused,
                                    summary: None,
                                });
                                let _ = respond.send(Ok(()));
                            }
                            Err(e) => {
                                let _ = respond.send(Err(format!(
                                    "Failed to pause mission {}: {}",
                                    mission_id, e
                                )));
                            }
                        }
                    }
                    ControlCommand::ListRunning { respond } => {
                        // Return info about currently running missions
                        let mut running_list = Vec::new();
                        let remote_job_missions = crate::remote_node::job_ledger::load(
                            &config.working_dir,
                        )
                        .await
                        .unwrap_or_default()
                        .into_iter()
                        .filter(|handle| {
                            remote_build_handle_proves_liveness(handle, chrono::Utc::now())
                        })
                        .map(|handle| handle.mission_id)
                        .collect::<HashSet<_>>();

                        // Add main mission if running - use running_mission_id (the actual mission being executed)
                        // instead of current_mission (which can change when user creates a new mission)
                        if running.is_some() {
                            if let Some(mission_id) = running_mission_id {
                                let waiting_remote_job =
                                    remote_job_missions.contains(&mission_id);
                                let seconds_since_activity =
                                    main_runner_last_activity.elapsed().as_secs();
                                let state_label = {
                                    let status_guard = status.read().await;
                                    if waiting_remote_job {
                                        "waiting_remote_job"
                                    } else if status_guard.mission_id == Some(mission_id)
                                        && status_guard.state == ControlRunState::WaitingForTool
                                    {
                                        "waiting_for_tool"
                                    } else {
                                        "running"
                                    }
                                };
                                let mission_state = if state_label == "waiting_for_tool" {
                                    super::mission_runner::MissionRunState::WaitingForTool
                                } else {
                                    super::mission_runner::MissionRunState::Running
                                };
                                let tool_call_in_flight = waiting_remote_job
                                    || main_runner_active_tool_calls
                                        .load(std::sync::atomic::Ordering::Relaxed)
                                        > 0;
                                running_list.push(super::mission_runner::RunningMissionInfo {
                                    mission_id,
                                    backend_id: running_backend_id.clone(),
                                    state: state_label.to_string(),
                                    queue_len: queue.len(),
                                    history_len: history.len(),
                                    seconds_since_activity,
                                    tool_call_in_flight,
                                    health: projected_running_health(
                                        mission_state,
                                        seconds_since_activity,
                                        tool_call_in_flight,
                                        waiting_remote_job,
                                        running_backend_id.as_deref(),
                                    ),
                                    expected_deliverables: 0,
                                    current_activity: main_runner_activity.clone(),
                                    subtask_total: main_runner_subtasks.len(),
                                    subtask_completed: main_runner_subtasks.iter().filter(|s| s.completed).count(),
                                    run_id: running_run.as_ref().map(|run| run.run_id),
                                    generation: running_run.as_ref().map(|run| run.generation),
                                    heartbeat_at: running_run.as_ref().map(|run| run.heartbeat_at.clone()),
                                    scope_unit: running_run.as_ref().and_then(|run| run.scope_unit.clone()),
                                    status_conflict: running_run
                                        .is_none()
                                        .then(|| "actor_without_durable_run".to_string()),
                                });
                            }
                        }

                        // Add all parallel runners
                        for runner in parallel_runners.values() {
                            let mut info = super::mission_runner::RunningMissionInfo::from(runner);
                            if remote_job_missions.contains(&info.mission_id) {
                                info.state = "waiting_remote_job".to_string();
                                info.tool_call_in_flight = true;
                                info.health = super::mission_runner::MissionHealth::Healthy;
                            }
                            running_list.push(info);
                        }

                        let _ = respond.send(running_list);
                    }
                    ControlCommand::GetActorRunLease { mission_id, respond } => {
                        let parallel_runner = parallel_runners.get(&mission_id);
                        let actor_run = select_actor_run_lease(
                            mission_id,
                            running.is_some(),
                            running_mission_id,
                            running_run
                                .as_ref()
                                .map(|run| (run.run_id, run.generation)),
                            parallel_runner.is_some_and(|runner| runner.is_running()),
                            parallel_runner
                                .and_then(|runner| runner.durable_run.as_ref())
                                .map(|run| (run.run_id, run.generation)),
                        );
                        let _ = respond.send(actor_run);
                    }
                    ControlCommand::ResumeMission { mission_id, clean_workspace, skip_message, respond } => {
                        // Resumable terminal writers do not hold a lease, so a replacement
                        // writer may have been created since this mission stopped. Serialize
                        // the availability check with create/project updates and keep the
                        // guard until the resumed mission has been made Active (or the
                        // resume has failed). Otherwise a create can race between the check
                        // and the status transition and start a second branch-changing
                        // runner for the same PR.
                        let _pr_writer_guard = match acquire_durable_pr_writer_lock(&control_hub).await {
                            Ok(guard) => guard,
                            Err(error) => {
                                let _ = respond.send(Err(error));
                                continue;
                            }
                        };
                        // Resume an interrupted mission by building resume context
                        match resume_mission_impl(
                            &mission_store,
                            &config,
                            mission_id,
                            clean_workspace,
                        )
                        .await {
                            Ok((mission, resume_prompt)) => {
                                if let Err(error) = ensure_pr_writer_resume_is_exclusive(
                                    &control_hub,
                                    &mission_store,
                                    &mission,
                                )
                                .await
                                {
                                    let _ = respond.send(Err(error));
                                    continue;
                                }
                                let already_running_main =
                                    running.is_some() && running_mission_id == Some(mission_id);
                                let already_running_parallel = parallel_runners
                                    .get(&mission_id)
                                    .is_some_and(|runner| runner.is_running());
                                if already_running_main || already_running_parallel {
                                    let _ = respond.send(Err(format!(
                                        "Mission {} is already running",
                                        mission_id
                                    )));
                                    continue;
                                }

                                // If another main mission is running, resume this one in a
                                // parallel runner so its history stays isolated. This is
                                // important for startup recovery when several missions were
                                // interrupted by the same service restart.
                                if running.is_some() {
                                    if skip_message {
                                        if mission.status == MissionStatus::Paused {
                                            if let Err(error) = mission_store
                                                .update_mission_status(
                                                    mission_id,
                                                    MissionStatus::Interrupted,
                                                )
                                                .await
                                            {
                                                let _ = respond.send(Err(error));
                                                continue;
                                            }
                                            let _ = mission_store
                                                .set_mission_paused_at(mission_id, None)
                                                .await;
                                            let _ = events_tx.send(
                                                AgentEvent::MissionStatusChanged {
                                                    mission_id,
                                                    status: MissionStatus::Interrupted,
                                                    summary: None,
                                                },
                                            );
                                        }
                                        tracing::info!(
                                            mission_id = %mission_id,
                                            "Deferring parallel resume until the caller sends a custom message"
                                        );
                                        let mut updated_mission = mission;
                                        if updated_mission.status == MissionStatus::Paused {
                                            updated_mission.status = MissionStatus::Interrupted;
                                            updated_mission.paused_at = None;
                                        }
                                        let _ = respond.send(Ok(updated_mission));
                                        continue;
                                    }

                                    let parallel_running = parallel_runners
                                        .values()
                                        .filter(|runner| runner.is_running())
                                        .count();
                                    let total_running = parallel_running + 1;
                                    let max_parallel =
                                        crate::settings::max_parallel_missions_cached_or(
                                            config.max_parallel_missions,
                                        );

                                    if total_running >= max_parallel {
                                        let _ = respond.send(Err(format!(
                                            "Maximum parallel missions ({}) reached. {} running.",
                                            max_parallel, total_running
                                        )));
                                        continue;
                                    }

                                    // Explicit resume is the authority to clear
                                    // a paused/interrupted presentation row.
                                    // Persist it before acquiring the run so the
                                    // store can reject any stale-state race.
                                    if let Err(error) = mission_store
                                        .update_mission_status(mission_id, MissionStatus::Active)
                                        .await
                                    {
                                        let _ = respond.send(Err(format!(
                                            "Failed to activate mission before resume: {error}"
                                        )));
                                        continue;
                                    }
                                    let mut runner = super::mission_runner::MissionRunner::new(
                                        mission_id,
                                        mission.workspace_id,
                                        mission.agent.clone(),
                                        Some(mission.backend.clone()),
                                        mission.session_id.clone(),
                                        mission.config_profile.clone(),
                                        mission.model_override.clone(),
                                        mission.model_effort.clone(),
                                        mission.fast_mode,
                                    );
                                    runner.pr_readonly = mission.project.tags.iter().any(|tag| tag == "pr-readonly");
                                    runner.working_directory = mission.working_directory.clone();
                                    runner.user_id = Some(session_user_id.clone());
                                    for entry in &mission.history {
                                        runner
                                            .history
                                            .push((entry.role.clone(), entry.content.clone()));
                                    }
                                    runner.queue_message(Uuid::new_v4(), resume_prompt, None, None);

                                    if let Err(error) = runner
                                        .acquire_durable_run(
                                            &mission_store,
                                            &format!("control:{session_user_id}"),
                                        )
                                        .await
                                    {
                                        let rollback =
                                            restore_mission_after_failed_run_acquisition(
                                                &mission_store,
                                                &events_tx,
                                                &mission,
                                            )
                                            .await;
                                        let _ = respond.send(Err(format!(
                                            "Failed to acquire mission run lease: {error}{}",
                                            rollback
                                                .err()
                                                .map(|rollback_error| format!(
                                                    "; failed to restore {} status: {rollback_error}",
                                                    mission.status
                                                ))
                                                .unwrap_or_default()
                                        )));
                                        continue;
                                    }
                                    if mission.status == MissionStatus::Paused {
                                        let _ = mission_store
                                            .set_mission_paused_at(mission_id, None)
                                            .await;
                                    }
                                    maybe_schedule_mission_metadata_refresh_for_status(
                                        &mission_store,
                                        &events_tx,
                                        mission_id,
                                        MissionStatus::Active,
                                    );
                                    let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                        mission_id,
                                        status: MissionStatus::Active,
                                        summary: None,
                                    });
                                    let started = runner.start_next(
                                        config.clone(),
                                        Arc::clone(&root_agent),
                                        Arc::clone(&mcp),
                                        Arc::clone(&workspaces),
                                        library.clone(),
                                        events_tx.clone(),
                                        Arc::clone(&tool_hub),
                                        Arc::clone(&status),
                                        mission_cmd_tx.clone(),
                                        Arc::new(RwLock::new(Some(mission_id))),
                                        secrets.clone(),
                                    );

                                    if !started {
                                        let _ = respond.send(Err(
                                            "Failed to start mission execution".to_string(),
                                        ));
                                        continue;
                                    }

                                    parallel_runners.insert(mission_id, runner);
                                    let mut updated_mission = mission;
                                    updated_mission.status = MissionStatus::Active;
                                    updated_mission.resumable = false;
                                    updated_mission.interrupted_at = None;
                                    let _ = respond.send(Ok(updated_mission));
                                    continue;
                                }

                                // First persist current mission history (if any)
                                persist_mission_history(
                                    &mission_store,
                                    &events_tx,
                                    &current_mission,
                                    &history,
                                )
                                .await;

                                // Load the mission's history into current state
                                history = mission.history.iter()
                                    .map(|e| (e.role.clone(), e.content.clone()))
                                    .collect();
                                *current_mission.write().await = Some(mission_id);

                                // Update mission status back to active
                                if let Err(e) = mission_store
                                    .update_mission_status(mission_id, MissionStatus::Active)
                                    .await
                                {
                                    tracing::warn!("Failed to resume mission {}: {}", mission_id, e);
                                } else {
                                    if mission.status == MissionStatus::Paused {
                                        let _ = mission_store
                                            .set_mission_paused_at(mission_id, None)
                                            .await;
                                    }
                                    maybe_schedule_mission_metadata_refresh_for_status(
                                        &mission_store,
                                        &events_tx,
                                        mission_id,
                                        MissionStatus::Active,
                                    );
                                    // Send status changed event so UI updates
                                    let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                        mission_id,
                                        status: MissionStatus::Active,
                                        summary: None,
                                    });
                                }

                                // Queue the resume prompt as a message (no per-message agent override)
                                // Skip if the caller just wants to update the status (e.g., before sending a custom message)
                                if !skip_message {
                                    let msg_id = Uuid::new_v4();
                                    queue.push_back((
                                        msg_id,
                                        resume_prompt,
                                        None,
                                        Some(mission_id),
                                        Some("system:resume".to_string()),
                                    ));
                                }

                                // Start execution if not already running
                                if running.is_none() {
                                    if let Some((mid, msg, per_msg_agent, msg_target_mid, msg_source)) = pop_next_runnable_control_queue(&mut queue, &mission_store).await {
                                        // Persist the dequeue before the awaits that
                                        // start the run, so a crash here can't
                                        // restore + re-run it.
                                        if let Err(error) = persist_control_queue_if_changed(
                                            &mission_store,
                                            &session_user_id,
                                            &queue,
                                            &parallel_runners,
                                            &recovered_consumed_user_messages,
                                            &mut last_persisted_queue,
                                        )
                                        .await
                                        {
                                            queue.push_front((
                                                mid,
                                                msg,
                                                per_msg_agent,
                                                msg_target_mid,
                                                msg_source,
                                            ));
                                            let _ = respond.send(Err(format!(
                                                "Failed to persist resumed mission queue: {error}"
                                            )));
                                            continue;
                                        }
                                        let target_mid = msg_target_mid.unwrap_or(mission_id);
                                        set_and_emit_status(
                                            &status,
                                            &events_tx,
                                            ControlRunState::Running,
                                            queue.len(),
                                            Some(target_mid),
                                        ).await;
                                        let _ = events_tx.send(AgentEvent::UserMessage { id: mid, content: msg.clone(), queued: false, mission_id: Some(target_mid), source: msg_source.clone() });
                                        let cfg = config.clone();
                                        let agent = Arc::clone(&root_agent);
                                        let mcp_ref = Arc::clone(&mcp);
                                        let workspaces_ref = Arc::clone(&workspaces);
                                        let library_ref = Arc::clone(&library);
                                        let events = events_tx.clone();
                                        let tools_hub = Arc::clone(&tool_hub);
                                        let status_ref = Arc::clone(&status);
                                        let cancel = CancellationToken::new();
                                        let hist_snapshot = history.clone();
                                        let mission_ctrl = crate::tools::mission::MissionControl {
                                            current_mission_id: Arc::clone(&current_mission),
                                            cmd_tx: mission_cmd_tx.clone(),
                                        };
                                        let tree_ref = Arc::clone(&current_tree);
                                        let progress_ref = Arc::clone(&progress);
                                        let workspace_id = Some(mission.workspace_id);
                                        let backend_id = Some(mission.backend.clone());
                                        let model_override = mission.model_override.clone();
                                        let model_effort = mission.model_effort.clone();
                                        let fast_mode = mission.fast_mode;
                                        // Resume uses mission agent (no per-message override for resumes)
                                        let agent_override = mission.agent.clone();
                                        let session_id = mission.session_id.clone();
                                        let mission_config_profile = mission.config_profile.clone();
                                        let pr_readonly = mission.project.tags.iter().any(|tag| tag == "pr-readonly");
                                        running_cancel = Some(cancel.clone());
                                        // Capture which mission this task is working on (the resumed mission)
                                        running_mission_id = Some(mission_id);
                                        running_backend_id = backend_id.clone();
                                        // Reset activity tracking so stall detection starts fresh
                                        main_runner_last_activity = std::time::Instant::now();
                                        main_runner_activity = None;
                                        main_runner_subtasks.clear();
                                        main_runner_active_tool_calls
                                            .store(0, std::sync::atomic::Ordering::Relaxed);
                                        let user_id_for_turn = session_user_id.clone();
                                        running_run = match acquire_execution_run(
                                            &mission_store,
                                            Some(mission_id),
                                            &format!("control:{session_user_id}"),
                                        )
                                        .await
                                        {
                                            Ok(run) => run,
                                            Err(error) => {
                                                running_cancel = None;
                                                running_mission_id = None;
                                                running_backend_id = None;
                                                let _ = respond.send(Err(format!(
                                                    "Failed to acquire mission run lease: {error}"
                                                )));
                                                continue;
                                            }
                                        };
                                        running = Some(tokio::spawn(async move {
                                            let result = run_single_control_turn(
                                                cfg,
                                                agent,
                                                mcp_ref,
                                                workspaces_ref,
                                                library_ref,
                                                events,
                                                tools_hub,
                                                status_ref,
                                                cancel,
                                                hist_snapshot,
                                                msg.clone(),
                                                Some(mission_ctrl),
                                                tree_ref,
                                                progress_ref,
                                                Some(mission_id),
                                                workspace_id,
                                                backend_id,
                                                model_override,
                                                model_effort,
                                                fast_mode,
                                                agent_override,
                                                session_id,
                                                true, // force_session_resume: this is a resume operation
                                                mission_config_profile,
                                                Some(user_id_for_turn),
                                                pr_readonly,
                                            )
                                            .await;
                                            (mid, msg, result)
                                        }));
                                    }
                                }

                                // Return the updated mission
                                let mut updated_mission = mission;
                                updated_mission.status = MissionStatus::Active;
                                updated_mission.resumable = false;
                                updated_mission.interrupted_at = None;
                                let _ = respond.send(Ok(updated_mission));
                            }
                            Err(e) => {
                                let _ = respond.send(Err(e));
                            }
                        }
                    }
                    ControlCommand::GracefulShutdown { respond } => {
                        // Mark all running missions as interrupted
                        let mut interrupted_ids = Vec::new();

                        // Handle main mission - use running_mission_id (the actual mission being executed)
                        // Note: We DON'T persist history here because:
                        // 1. If current_mission == running_mission_id, history is correct
                        // 2. If current_mission != running_mission_id (user created new mission),
                        //    history was cleared and doesn't belong to running_mission_id
                        // The running mission's history is already in DB from previous exchanges,
                        // and any in-progress exchange will be lost (acceptable for shutdown).
                        if running.is_some() {
                            if let Some(mission_id) = running_mission_id {
                                // Only persist if the running mission is still current mission
                                // (i.e., user didn't create a new mission while this one was running)
                                let current_mid = *current_mission.read().await;
                                if current_mid == Some(mission_id) {
                                    persist_mission_history(
                                        &mission_store,
                                        &events_tx,
                                        &current_mission,
                                        &history,
                                    )
                                    .await;
                                }
                                // Note: If missions differ, don't persist - the local history
                                // belongs to current_mission, not running_mission_id

                                let preserve_remote_wait =
                                    preserve_remote_wait_during_shutdown(
                                        &mission_store,
                                        &config.working_dir,
                                        mission_id,
                                    )
                                    .await;
                                if !preserve_remote_wait
                                    && mission_store
                                        .update_mission_status_with_reason(
                                            mission_id,
                                            MissionStatus::Interrupted,
                                            Some("server_shutdown"),
                                        )
                                        .await
                                        .is_ok()
                                {
                                    maybe_schedule_mission_metadata_refresh_for_status(
                                        &mission_store,
                                        &events_tx,
                                        mission_id,
                                        MissionStatus::Interrupted,
                                    );
                                    interrupted_ids.push(mission_id);
                                    tracing::info!("Marked mission {} as interrupted", mission_id);
                                }

                                // Cancel execution
                                if let Some(token) = &running_cancel {
                                    token.cancel();
                                }
                            }
                        }

                        // Handle parallel missions
                        for (mission_id, runner) in parallel_runners.iter_mut() {
                            // Persist history for parallel mission
                            let entries: Vec<MissionHistoryEntry> = runner
                                .history
                                .iter()
                                .map(|(role, content)| MissionHistoryEntry {
                                    role: role.clone(),
                                    content: content.clone(),
                                })
                                .collect();
                            persist_mission_history_and_schedule_metadata_refresh(
                                &mission_store,
                                &events_tx,
                                *mission_id,
                                &entries,
                            )
                            .await;
                            let preserve_remote_wait =
                                preserve_remote_wait_during_shutdown(
                                    &mission_store,
                                    &config.working_dir,
                                    *mission_id,
                                )
                                .await;
                            if !preserve_remote_wait
                                && mission_store
                                    .update_mission_status_with_reason(
                                        *mission_id,
                                        MissionStatus::Interrupted,
                                        Some("server_shutdown"),
                                    )
                                    .await
                                    .is_ok()
                            {
                                maybe_schedule_mission_metadata_refresh_for_status(
                                    &mission_store,
                                    &events_tx,
                                    *mission_id,
                                    MissionStatus::Interrupted,
                                );
                                interrupted_ids.push(*mission_id);
                                tracing::info!("Marked parallel mission {} as interrupted", mission_id);
                            }

                            runner.cancel();
                        }

                        let _ = respond.send(interrupted_ids);
                    }
                    ControlCommand::GetQueue { respond } => {
                        // Collect queued messages from main runner with their target mission IDs
                        let mut queued: Vec<QueuedMessage> = queue
                            .iter()
                            .map(|(id, content, agent, target_mid, source)| QueuedMessage {
                                id: *id,
                                content: content.clone(),
                                agent: agent.clone(),
                                mission_id: *target_mid,
                                source: source.clone(),
                                inflight: false,
                            })
                            .collect();
                        // Also collect queued messages from parallel runners
                        for (mid, runner) in parallel_runners.iter() {
                            for qm in runner.queue.iter() {
                                queued.push(QueuedMessage {
                                    id: qm.id,
                                    content: qm.content.clone(),
                                    agent: qm.agent.clone(),
                                    mission_id: Some(*mid),
                                    source: qm.source.clone(),
                                    inflight: false,
                                });
                            }
                        }
                        let _ = respond.send(queued);
                    }
                    ControlCommand::RemoveFromQueue { message_id, respond } => {
                        let mut removed = false;

                        // Try to remove from main queue
                        let before_len = queue.len();
                        queue.retain(|(id, _, _, _, _)| *id != message_id);
                        if queue.len() < before_len {
                            removed = true;
                            // Emit event for main queue change
                            let _ = events_tx.send(AgentEvent::Status {
                                state: if running.is_some() {
                                    ControlRunState::Running
                                } else {
                                    ControlRunState::Idle
                                },
                                queue_len: queue.len(),
                                mission_id: if running.is_some() {
                                    running_mission_id
                                } else {
                                    *current_mission.read().await
                                },
                            });
                        }

                        // Also try to remove from parallel runner queues.
                        // Emit a Status event for each affected mission so
                        // every client (other tabs, iOS) learns the queue
                        // changed — without this, only the deleting client
                        // ever updates its UI.
                        for (mid, runner) in parallel_runners.iter_mut() {
                            if runner.remove_from_queue(message_id) {
                                removed = true;
                                tracing::info!("Removed message {} from parallel mission {}", message_id, mid);
                                let _ = events_tx.send(AgentEvent::Status {
                                    state: if runner.is_running() {
                                        ControlRunState::Running
                                    } else {
                                        ControlRunState::Idle
                                    },
                                    queue_len: runner.queue.len(),
                                    mission_id: Some(*mid),
                                });
                            }
                        }

                        let _ = respond.send(removed);
                    }
                    ControlCommand::ClearQueue { mission_id, respond } => {
                        let main_mission_id = if running.is_some() {
                            running_mission_id
                        } else {
                            *current_mission.read().await
                        };

                        let mut cleared = 0usize;
                        match mission_id {
                            Some(target) => {
                                // Scoped clear: only drop messages targeting
                                // this mission (main queue entries + that
                                // mission's parallel-runner queue). Clearing
                                // from one mission's view must not wipe other
                                // missions' queues.
                                let before_len = queue.len();
                                queue.retain(|(_, _, _, target_mid, _)| *target_mid != Some(target));
                                let main_removed = before_len - queue.len();
                                cleared += main_removed;
                                if main_removed > 0 {
                                    let _ = events_tx.send(AgentEvent::Status {
                                        state: if running.is_some() {
                                            ControlRunState::Running
                                        } else {
                                            ControlRunState::Idle
                                        },
                                        queue_len: queue.len(),
                                        mission_id: main_mission_id,
                                    });
                                }
                                // Clients filter Status events by the mission
                                // they are viewing, so the main-queue event
                                // above is invisible to a client focused on
                                // `target` (unless target IS the main
                                // mission). Emit a target-scoped Status
                                // whenever anything was cleared for it.
                                let mut target_status_sent = false;
                                if let Some(runner) = parallel_runners.get_mut(&target) {
                                    let runner_cleared = runner.clear_queue();
                                    cleared += runner_cleared;
                                    if runner_cleared > 0 || main_removed > 0 {
                                        let _ = events_tx.send(AgentEvent::Status {
                                            state: if runner.is_running() {
                                                ControlRunState::Running
                                            } else {
                                                ControlRunState::Idle
                                            },
                                            queue_len: runner.queue.len(),
                                            mission_id: Some(target),
                                        });
                                        target_status_sent = true;
                                    }
                                }
                                if main_removed > 0
                                    && !target_status_sent
                                    && main_mission_id != Some(target)
                                {
                                    // No parallel runner for `target` and it
                                    // is not the main mission: it cannot be
                                    // running, but its viewers still need a
                                    // scoped event to refresh their queue.
                                    let _ = events_tx.send(AgentEvent::Status {
                                        state: ControlRunState::Idle,
                                        queue_len: 0,
                                        mission_id: Some(target),
                                    });
                                }
                                tracing::info!(
                                    "Cleared {} queued messages for mission {}",
                                    cleared, target
                                );
                            }
                            None => {
                                cleared = queue.len();
                                queue.clear();

                                // Also clear parallel runner queues, notifying
                                // each affected mission's viewers.
                                for (mid, runner) in parallel_runners.iter_mut() {
                                    let runner_cleared = runner.clear_queue();
                                    if runner_cleared > 0 {
                                        cleared += runner_cleared;
                                        let _ = events_tx.send(AgentEvent::Status {
                                            state: if runner.is_running() {
                                                ControlRunState::Running
                                            } else {
                                                ControlRunState::Idle
                                            },
                                            queue_len: 0,
                                            mission_id: Some(*mid),
                                        });
                                    }
                                }

                                // Emit event to notify frontend (main queue)
                                let _ = events_tx.send(AgentEvent::Status {
                                    state: if running.is_some() {
                                        ControlRunState::Running
                                    } else {
                                        ControlRunState::Idle
                                    },
                                    queue_len: 0,
                                    mission_id: main_mission_id,
                                });

                                tracing::info!("Cleared {} total queued messages (main + parallel)", cleared);
                            }
                        }
                        let _ = respond.send(cleared);
                    }
                }
            }
            // Handle agent-initiated mission status changes (from complete_mission tool)
            mission_cmd = mission_cmd_rx.recv() => {
                if let Some(cmd) = mission_cmd {
                    match cmd {
                        crate::tools::mission::MissionControlCommand::SetStatus { mission_id: id, status, summary } => {
                            let new_status = match status {
                                crate::tools::mission::MissionStatusValue::Completed => MissionStatus::Completed,
                                crate::tools::mission::MissionStatusValue::Failed => MissionStatus::Failed,
                                crate::tools::mission::MissionStatusValue::Blocked => MissionStatus::Blocked,
                                crate::tools::mission::MissionStatusValue::NotFeasible => MissionStatus::NotFeasible,
                            };
                            let success = matches!(status, crate::tools::mission::MissionStatusValue::Completed);
                            if new_status == MissionStatus::Completed
                                && mission_has_active_automation(&mission_store, id).await
                            {
                                tracing::info!(
                                    "Skipping completion for mission {} because active automations are enabled",
                                    id
                                );
                                continue;
                            }
                            // Save the final tree before updating status
                            if let Some(tree) = current_tree.read().await.clone() {
                                if let Err(e) = mission_store.update_mission_tree(id, &tree).await {
                                    tracing::warn!("Failed to save mission tree: {}", e);
                                } else {
                                    tracing::info!("Saved final tree for mission {}", id);
                                }
                            }

                            if mission_store
                                .update_mission_status(id, new_status)
                                .await
                                .is_ok()
                            {
                                maybe_schedule_mission_metadata_refresh_for_status(
                                    &mission_store,
                                    &events_tx,
                                    id,
                                    new_status,
                                );
                                // Generate and store mission summary
                                if let Some(ref summary_text) = summary {
                                    // Extract key files from conversation (look for paths in assistant messages)
                                    let key_files: Vec<String> = history
                                        .iter()
                                        .filter(|(role, _)| role == "assistant")
                                        .flat_map(|(_, content)| extract_file_paths(content))
                                        .take(10)
                                        .collect();

                                    if let Err(e) = mission_store
                                        .insert_mission_summary(id, summary_text, &key_files, success)
                                        .await
                                    {
                                        tracing::warn!("Failed to store mission summary: {}", e);
                                    } else {
                                        tracing::info!("Stored mission summary for {}", id);
                                    }
                                }

                                let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                    mission_id: id,
                                    status: new_status,
                                    summary,
                                });
                                tracing::info!("Mission {} marked as {} by agent", id, new_status);
                            }
                        }
                    }
                }
            }
            finished = async {
                match &mut running {
                    Some(handle) => Some(handle.await),
                    None => None
                }
            }, if running.is_some() => {
                if let Some(res) = finished {
                    // Save the running mission ID before clearing it - we need it for persist and auto-complete
                    // (current_mission can change if user clicks "New Mission" while task was running)
                    let completed_mission_id = running_mission_id;
                    running = None;
                    running_cancel = None;
                    running_mission_id = None;
                    running_backend_id = None;
                    main_runner_activity = None;
                    main_runner_active_tool_calls
                        .store(0, std::sync::atomic::Ordering::Relaxed);
                    // Runner cleared itself; cancel the force-clear watchdog.
                    runner_force_clear_deadline = None;
                    let mut completed_terminal_reason = None;
                    let mut completed_completion_confidence = None;
                    let mut completed_transport_failure = false;
                    let mut completed_waiting_remote_job = false;
                    // Captured for the post-turn `grok_goal` sentinel hook (see
                    // `post_turn_handle_grok_goal`), which runs after this
                    // `match` closes — `agent_result` itself is out of scope
                    // by then. Empty string when the join errored.
                    let mut completed_agent_output = String::new();
                    match res {
                        Ok((_mid, _user_msg, mut agent_result)) => {
                            maybe_recover_soft_llm_error(&mut agent_result);
                            let completion_evidence =
                                completion_evidence_for_agent_result(&agent_result);
                            completed_terminal_reason = agent_result.terminal_reason;
                            completed_completion_confidence =
                                Some(completion_evidence.completion_confidence);
                            completed_transport_failure =
                                is_transport_failure_evidence(&completion_evidence);
                            completed_agent_output = agent_result.output.clone();
                            if let Some(run) = running_run.take() {
                                completed_waiting_remote_job =
                                    mission_should_park_on_remote_build(
                                        &mission_store,
                                        &config.working_dir,
                                        run.mission_id,
                                    )
                                    .await;
                                let run_update = if completed_waiting_remote_job {
                                    mission_store
                                        .heartbeat_mission_run(
                                            run.run_id,
                                            run.generation,
                                            MissionExecutionState::WaitingRemoteJob,
                                            None,
                                        )
                                        .await
                                } else {
                                    let reason = agent_result
                                        .terminal_reason
                                        .map(|value| format!("{value:?}"));
                                    mission_store
                                        .finish_mission_run(
                                        run.run_id,
                                        run.generation,
                                        reason.as_deref(),
                                    )
                                        .await
                                };
                                if let Err(error) = run_update {
                                    tracing::warn!(
                                        mission_id = %run.mission_id,
                                        run_id = %run.run_id,
                                        waiting_remote_job = completed_waiting_remote_job,
                                        "Failed to settle main mission run: {error}"
                                    );
                                }
                                if completed_waiting_remote_job {
                                    if let Err(error) = mission_store
                                        .update_mission_status(run.mission_id, MissionStatus::Active)
                                        .await
                                    {
                                        tracing::warn!(mission_id = %run.mission_id, %error, "Failed to keep remote-wait mission active");
                                    } else {
                                        let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                            mission_id: run.mission_id,
                                            status: MissionStatus::Active,
                                            summary: Some("Waiting for durable remote validation".to_string()),
                                        });
                                    }
                                }
                            }
                            // Only append assistant to local history if this mission is still the current mission.
                            // Note: User message was already added before execution started.
                            // If the user created a new mission mid-execution, history was cleared for that new mission,
                            // and we don't want to contaminate it with the old mission's exchange.
                            let current_mid = *current_mission.read().await;
                            if completed_mission_id == current_mid {
                                history.push(("assistant".to_string(), agent_result.output.clone()));
                            }

                            // Persist to mission using the actual completed mission ID
                            // (not current_mission, which could have changed)
                            //
                            // IMPORTANT: We fetch existing history from DB and append, rather than
                            // using the local `history` variable, because CreateMission may have
                            // cleared `history` while this task was running. This prevents data loss.
                            // Note: User message was already persisted before execution started.
                            if let Some(mid) = completed_mission_id {
                                match mission_store.get_mission(mid).await {
                                    Ok(Some(mission)) => {
                                        let mut entries = mission.history.clone();
                                        entries.push(MissionHistoryEntry {
                                            role: "assistant".to_string(),
                                            content: agent_result.output.clone(),
                                        });
                                        if let Err(e) =
                                            mission_store.update_mission_history(mid, &entries).await
                                        {
                                            tracing::warn!("Failed to persist mission history: {}", e);
                                        } else {
                                            schedule_mission_metadata_refresh(
                                                &mission_store,
                                                &events_tx,
                                                mid,
                                                false,
                                            );
                                        }
                                    }
                                    Ok(None) => {
                                        tracing::warn!("Mission {} not found for history append", mid);
                                    }
                                    Err(e) => {
                                        tracing::warn!(
                                            "Failed to load mission {} for history append: {}",
                                            mid,
                                            e
                                        );
                                    }
                                }
                            }

                            // P1 FIX: Auto-complete mission if agent execution ended in a terminal state
                            // without an explicit complete_mission call.
                            // This prevents missions from staying "active" forever after max iterations, stalls, etc.
                            //
                            // We use terminal_reason (structured enum) instead of substring matching to avoid
                            // false positives when agent output legitimately contains words like "infinite loop".
                            // We also check the current mission status from DB to handle:
                            // - Explicit complete_mission calls (which update DB status)
                            // - Parallel missions (each has its own DB status)
                            if !completed_waiting_remote_job {
                                if let Some(mission_id) = completed_mission_id {
                                maybe_finalize_terminal_mission(
                                    &mission_store,
                                    &events_tx,
                                    mission_id,
                                    agent_result.terminal_reason,
                                    agent_result.terminal_evidence.as_deref(),
                                    Some(completion_evidence.completion_confidence),
                                    false,
                                    Some(agent_result.output.as_str()),
                                    "turn finished before follow-up enqueue",
                                )
                                .await;
                                }
                            }

                            // Parse rich tags and validate referenced files
                            let rich_tags = parse_rich_tags(&agent_result.output);
                            let shared_files = if rich_tags.is_empty() {
                                None
                            } else {
                                // Get workspace_id from mission for download URLs
                                let ws_id = if let Some(mid) = completed_mission_id {
                                    mission_store
                                        .get_mission(mid)
                                        .await
                                        .ok()
                                        .flatten()
                                        .map(|m| m.workspace_id)
                                } else {
                                    None
                                };
                                // Validate against the per-mission workspace directory, not the global
                                // server working_dir. Agent-relative paths (./foo.png) should resolve
                                // to the mission workspace.
                                let validate_root = if let (Some(mid), Some(wsid)) =
                                    (completed_mission_id, ws_id)
                                {
                                    workspaces
                                        .get(wsid)
                                        .await
                                        .map(|w| crate::workspace::mission_workspace_dir_for_root(&w.path, mid))
                                        .unwrap_or_else(|| config.working_dir.clone())
                                } else {
                                    config.working_dir.clone()
                                };
                                let files = validate_rich_tags(
                                    &rich_tags,
                                    &validate_root,
                                    ws_id,
                                    completed_mission_id,
                                )
                                .await;
                                if files.is_empty() { None } else { Some(files) }
                            };

                            // Mark failures as resumable so UI can show a resume button
                            let resumable = !agent_result.success && completed_mission_id.is_some();
                            let model_used = agent_result.model_used.clone();
                            let _ = events_tx.send(AgentEvent::AssistantMessage {
                                id: Uuid::new_v4(),
                                content: agent_result.output.clone(),
                                success: agent_result.success,
                                cost_cents: agent_result.cost_cents,
                                cost_source: agent_result.cost_source,
                                usage: agent_result.usage.clone(),
                                model: model_used.clone(),
                                model_normalized: model_used
                                    .as_deref()
                                    .map(crate::cost::normalized_model),
                                mission_id: completed_mission_id,
                                shared_files,
                                resumable,
                                completion_evidence: Some(completion_evidence),
                            });
                            if !completed_waiting_remote_job {
                                if let Some(mission_id) = completed_mission_id {
                                // Update automation executions based on agent outcome
                                let error_msg = if agent_result.success {
                                    None
                                } else {
                                    Some(
                                        agent_result.terminal_reason
                                            .map(|r| format!("{:?}", r))
                                            .unwrap_or_else(|| "Agent execution failed".to_string()),
                                    )
                                };
                                if let Err(e) = mission_store
                                    .complete_running_executions_for_mission(
                                        mission_id,
                                        agent_result.success,
                                        error_msg,
                                    )
                                    .await
                                {
                                    tracing::warn!(
                                        "Failed to complete running executions for mission {}: {}",
                                        mission_id,
                                        e
                                    );
                                }

                                close_mission_desktop_sessions(
                                    &mission_store,
                                    mission_id,
                                    &config.working_dir,
                                )
                                .await;
                                }
                            }
                        }
                        Err(e) => {
                            if let Some(run) = running_run.take() {
                                let _ = mission_store
                                    .finish_mission_run(
                                        run.run_id,
                                        run.generation,
                                        Some("runner_join_failed"),
                                    )
                                    .await;
                            }
                            let _ = events_tx.send(AgentEvent::Error {
                                message: format!("Control session task join failed: {}", e),
                                mission_id: completed_mission_id,
                                resumable: completed_mission_id.is_some(), // Can resume if mission exists
                            });
                            if let Some(mission_id) = completed_mission_id {
                                // Mark running automation executions as failed
                                if let Err(e2) = mission_store
                                    .complete_running_executions_for_mission(
                                        mission_id,
                                        false,
                                        Some(format!("Task join failed: {}", e)),
                                    )
                                    .await
                                {
                                    tracing::warn!(
                                        "Failed to complete running executions for mission {}: {}",
                                        mission_id,
                                        e2
                                    );
                                }

                                // Update mission status so it doesn't stay Active forever.
                                // Mark as Failed (resumable) so the user can retry.
                                if let Err(e) = mission_store
                                    .update_mission_status(mission_id, MissionStatus::Failed)
                                    .await
                                {
                                    tracing::warn!("Failed to update mission status after join error: {}", e);
                                } else {
                                    maybe_schedule_mission_metadata_refresh_for_status(
                                        &mission_store,
                                        &events_tx,
                                        mission_id,
                                        MissionStatus::Failed,
                                    );
                                    let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                        mission_id,
                                        status: MissionStatus::Failed,
                                        summary: Some("Task execution failed unexpectedly".to_string()),
                                    });
                                }
                                close_mission_desktop_sessions(
                                    &mission_store,
                                    mission_id,
                                    &config.working_dir,
                                )
                                .await;
                            }
                        }
                    }

                    // If the mission is idle now, enqueue any agent_finished automations after a short delay.
                    // Skip automations for transient infrastructure failures (auth errors,
                    // rate limits, capacity limits) — these aren't "the agent finished work",
                    // they're transient failures that the retry/recovery logic handles.
                    // Firing automations on these creates noisy retry loops.
                    if !completed_waiting_remote_job {
                        if let Some(mission_id) = completed_mission_id {
                        if completed_transport_failure
                            && transport_auto_resumed_missions.insert(mission_id)
                            && !queue_has_pending_target_mission(&queue, mission_id)
                        {
                            let resume_message = "The previous turn ended because its provider transport disconnected. Reconcile the current workspace, remote jobs, and repository head, then resume the same task. Do not duplicate an accepted job or create a replacement writer.".to_string();
                            let activation = activate_mission_id_for_message(
                                &control_hub,
                                &mission_store,
                                &events_tx,
                                mission_id,
                                &resume_message,
                            )
                            .await;
                            match activation {
                                Ok(()) => {
                                    tracing::info!(
                                        %mission_id,
                                        "Auto-resuming mission once after structured transport failure"
                                    );
                                    queue.push_back((
                                        Uuid::new_v4(),
                                        resume_message,
                                        None,
                                        Some(mission_id),
                                        Some("transport_auto_resume".to_string()),
                                    ));
                                }
                                Err(error) => {
                                    tracing::warn!(
                                        %mission_id,
                                        "Structured transport auto-resume could not reactivate mission: {error}"
                                    );
                                    let _ = events_tx.send(AgentEvent::Error {
                                        message: format!(
                                            "Transport recovery could not reactivate mission {mission_id}: {error}"
                                        ),
                                        mission_id: Some(mission_id),
                                        resumable: true,
                                    });
                                }
                            }
                        }
                        let is_transient_infra_failure = matches!(
                            completed_terminal_reason,
                            Some(TerminalReason::AuthError)
                                | Some(TerminalReason::RateLimited)
                                | Some(TerminalReason::CapacityLimited)
                        ) || completed_transport_failure;
                        let already_queued_for_mission = queue
                            .iter()
                            .any(|(_id, _msg, _agent, target_mid, _source)| *target_mid == Some(mission_id));

                        // Grok `/goal` post-turn: parse the sentinel from the
                        // assistant's last text and either disable the goal
                        // automation (terminal sentinel / budget exhausted /
                        // sentinel-missing streak) or bump the iteration
                        // counter. Must run BEFORE
                        // `agent_finished_automation_messages` so a Complete /
                        // Aborted disable takes effect on this very turn —
                        // otherwise the existing hook would still fire the
                        // continuation. Skipped on transient infra failures
                        // for the same reason regular automations are.
                        if !is_transient_infra_failure {
                            post_turn_handle_grok_goal(
                                &mission_store,
                                &events_tx,
                                mission_id,
                                &completed_agent_output,
                                completed_terminal_reason,
                            )
                            .await;
                        }
                        if !already_queued_for_mission && !is_transient_infra_failure {
                            // Small delay so the UI can display the completion before restarting.
                            tokio::time::sleep(tokio::time::Duration::from_millis(500)).await;
                            let messages = agent_finished_automation_messages(
                                &mission_store,
                                mission_id,
                                &library,
                                &workspaces,
                            )
                            .await;
                            enqueue_agent_finished_messages(&mut queue, messages);
                        }

                        if !queue_has_pending_target_mission(&queue, mission_id) {
                            maybe_finalize_terminal_mission(
                                &mission_store,
                                &events_tx,
                                mission_id,
                                completed_terminal_reason,
                                None,
                                completed_completion_confidence,
                                true,
                                Some(completed_agent_output.as_str()),
                                "turn finished with no same-mission follow-up queued",
                            )
                            .await;
                        }
                        }
                    }
                }

                // Start next queued message, if any.
                if let Some((mid, msg, per_msg_agent, msg_target_mid, msg_source)) = pop_next_runnable_control_queue(&mut queue, &mission_store).await {
                    // Persist the dequeue before the awaits that start the run, so
                    // a crash here can't restore + re-run it.
                    if let Err(error) = persist_control_queue_if_changed(
                        &mission_store,
                        &session_user_id,
                        &queue,
                        &parallel_runners,
                        &recovered_consumed_user_messages,
                        &mut last_persisted_queue,
                    )
                    .await
                    {
                        queue.push_front((
                            mid,
                            msg,
                            per_msg_agent,
                            msg_target_mid,
                            msg_source,
                        ));
                        tracing::warn!(
                            "Queued delivery retained because dequeue persistence failed: {error}"
                        );
                        continue;
                    }
                    // Re-assert activation for every targeted delivery at
                    // dequeue. A message may have waited behind another turn
                    // while cancellation, acknowledgement, a background wait,
                    // or a controller restart changed the presentation row.
                    // Acquiring a new run without this check can produce an
                    // interrupted/acknowledged mission with a live run lease.
                    if queued_delivery_requires_activation(
                        msg_target_mid,
                        msg_source.as_deref(),
                    ) {
                        let activation = match msg_target_mid {
                            Some(mission_id) => {
                                activate_mission_id_for_message(
                                    &control_hub,
                                    &mission_store,
                                    &events_tx,
                                    mission_id,
                                    &msg,
                                )
                                .await
                            }
                            None => Err("transport auto-resume is missing mission_id".to_string()),
                        };
                        if let Err(error) = activation {
                            queue.push_front((
                                mid,
                                msg,
                                per_msg_agent,
                                msg_target_mid,
                                msg_source,
                            ));
                            if let Err(persist_error) = persist_control_queue_if_changed(
                                &mission_store,
                                &session_user_id,
                                &queue,
                                &parallel_runners,
                                &recovered_consumed_user_messages,
                                &mut last_persisted_queue,
                            )
                            .await
                            {
                                tracing::warn!(
                                    "Failed to restore queued delivery after activation rejection: {persist_error}"
                                );
                            }
                            let _ = events_tx.send(AgentEvent::Error {
                                message: format!(
                                    "Queued delivery could not activate its mission: {error}"
                                ),
                                mission_id: msg_target_mid,
                                resumable: true,
                            });
                            tokio::time::sleep(tokio::time::Duration::from_millis(250)).await;
                            continue;
                        }
                    }
                    // Acquire the durable run before publishing the message as
                    // started or appending it to history. If a stale run lease
                    // rejects acquisition, retain the exact queued delivery so
                    // an idempotent retry cannot be acknowledged without ever
                    // executing its turn.
                    let mission_id = msg_target_mid;
                    running_run = match acquire_execution_run(
                        &mission_store,
                        mission_id,
                        &format!("control:{session_user_id}"),
                    )
                    .await
                    {
                        Ok(run) => run,
                        Err(error) => {
                            queue.push_front((
                                mid,
                                msg,
                                per_msg_agent,
                                msg_target_mid,
                                msg_source,
                            ));
                            if let Err(persist_error) = persist_control_queue_if_changed(
                                &mission_store,
                                &session_user_id,
                                &queue,
                                &parallel_runners,
                                &recovered_consumed_user_messages,
                                &mut last_persisted_queue,
                            )
                            .await
                            {
                                tracing::warn!(
                                    "Failed to persist queued delivery after run lease rejection: {persist_error}"
                                );
                            }
                            let _ = events_tx.send(AgentEvent::Error {
                                message: format!("Mission run lease rejected: {error}"),
                                mission_id,
                                resumable: true,
                            });
                            set_and_emit_status(
                                &status,
                                &events_tx,
                                ControlRunState::Idle,
                                queue.len(),
                                mission_id,
                            )
                            .await;
                            tokio::time::sleep(tokio::time::Duration::from_millis(250)).await;
                            continue;
                        }
                    };
                    set_and_emit_status(
                        &status,
                        &events_tx,
                        ControlRunState::Running,
                        queue.len(),
                        msg_target_mid,
                    ).await;
                    let _ = events_tx.send(AgentEvent::UserMessage { id: mid, content: msg.clone(), queued: false, mission_id: msg_target_mid, source: msg_source.clone() });

                    // Immediately persist user message so it's visible when loading mission
                    history.push(("user".to_string(), msg.clone()));
                    persist_mission_history_to(
                        &mission_store,
                        &events_tx,
                        msg_target_mid,
                        &history,
                    )
                        .await;

                    let cfg = config.clone();
                    let agent = Arc::clone(&root_agent);
                    let mcp_ref = Arc::clone(&mcp);
                    let workspaces_ref = Arc::clone(&workspaces);
                    let library_ref = Arc::clone(&library);
                    let events = events_tx.clone();
                    let tools_hub = Arc::clone(&tool_hub);
                    let status_ref = Arc::clone(&status);
                    let cancel = CancellationToken::new();
                    let hist_snapshot = history.clone();
                    let mission_ctrl = crate::tools::mission::MissionControl {
                        current_mission_id: Arc::clone(&current_mission),
                        cmd_tx: mission_cmd_tx.clone(),
                    };
                    let tree_ref = Arc::clone(&current_tree);
                    let progress_ref = Arc::clone(&progress);
                    running_cancel = Some(cancel.clone());
                    // Use the mission ID that was captured when message was queued.
                    // This prevents races where current_mission changes between
                    // queueing and execution.
                    let (workspace_id, model_override, model_effort, fast_mode, mission_agent, backend_id, session_id, mission_config_profile, pr_readonly) = if let Some(mid) = mission_id {
                        match mission_store.get_mission(mid).await {
                            Ok(Some(mission)) => (
                                Some(mission.workspace_id),
                                mission.model_override.clone(),
                                mission.model_effort.clone(),
                                mission.fast_mode,
                                mission.agent.clone(),
                                Some(mission.backend.clone()),
                                mission.session_id.clone(),
                                mission.config_profile.clone(),
                                mission.project.tags.iter().any(|tag| tag == "pr-readonly"),
                            ),
                            Ok(None) => {
                                tracing::warn!(
                                    "Mission {} not found while resolving workspace",
                                    mid
                                );
                                (None, None, None, false, None, None, None, None, false)
                            }
                            Err(e) => {
                                tracing::warn!(
                                    "Failed to load mission {} for workspace: {}",
                                    mid,
                                    e
                                );
                                (None, None, None, false, None, None, None, None, false)
                            }
                        }
                    } else {
                        (None, None, None, false, None, None, None, None, false)
                    };
                    // Per-message agent overrides mission agent
                    let agent_override = per_msg_agent.or(mission_agent);
                    running_mission_id = mission_id;
                    running_backend_id = backend_id.clone();
                    // Reset activity tracking when new task starts
                    main_runner_last_activity = std::time::Instant::now();
                    main_runner_activity = None;
                    main_runner_subtasks.clear();
                    main_runner_active_tool_calls
                        .store(0, std::sync::atomic::Ordering::Relaxed);
                    let user_id_for_turn = session_user_id.clone();
                    running = Some(tokio::spawn(async move {
                        let result = run_single_control_turn(
                            cfg,
                            agent,
                            mcp_ref,
                            workspaces_ref,
                            library_ref,
                            events,
                            tools_hub,
                            status_ref,
                            cancel,
                            hist_snapshot,
                            msg.clone(),
                            Some(mission_ctrl),
                            tree_ref,
                            progress_ref,
                            mission_id,
                            workspace_id,
                            backend_id,
                            model_override,
                            model_effort,
                            fast_mode,
                            agent_override,
                            session_id,
                            false, // force_session_resume: continuation turn, not a resume
                            mission_config_profile,
                            Some(user_id_for_turn),
                            pr_readonly,
                        )
                        .await;
                        (mid, msg, result)
                    }));
                } else {
                    set_and_emit_status(&status, &events_tx, ControlRunState::Idle, 0, None).await;
                }
            }
            // Poll parallel runners for completion
            _ = tokio::time::sleep(std::time::Duration::from_millis(100)) => {
                let mut completed_missions = Vec::new();

                for (mission_id, runner) in parallel_runners.iter_mut() {
                    if runner.force_clear_cancelled_if_due() {
                        tracing::warn!(
                            mission_id = %mission_id,
                            "Force-aborting stuck parallel runner after cancellation grace period"
                        );
                        let kill_reason = cancel_timeout_interrupt_reason();
                        runner
                            .finish_durable_run(
                                &mission_store,
                                Some(kill_reason),
                            )
                            .await;
                        if let Err(error) = mission_store
                            .update_mission_status_with_reason(
                                *mission_id,
                                MissionStatus::Interrupted,
                                Some(kill_reason),
                            )
                            .await
                        {
                            tracing::warn!(
                                mission_id = %mission_id,
                                "Failed to mark force-cleared parallel mission interrupted: {error}"
                            );
                        } else {
                            maybe_schedule_mission_metadata_refresh_for_status(
                                &mission_store,
                                &events_tx,
                                *mission_id,
                                MissionStatus::Interrupted,
                            );
                            let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                mission_id: *mission_id,
                                status: MissionStatus::Interrupted,
                                summary: Some(
                                    "Cancel timed out; force-aborted stuck parallel runner."
                                        .to_string(),
                                ),
                            });
                        }
                        if let Err(error) = mission_store
                            .complete_running_executions_for_mission(
                                *mission_id,
                                false,
                                Some(
                                    "Force-aborted stuck parallel runner after cancel timed out"
                                        .to_string(),
                                ),
                            )
                            .await
                        {
                            tracing::warn!(
                                mission_id = %mission_id,
                                "Failed to complete parallel executions on force-clear: {error}"
                            );
                        }
                        completed_missions.push(*mission_id);
                        continue;
                    }
                    if runner.check_finished() {
                        if let Some((_msg_id, _user_msg, mut result)) = runner.poll_completion().await {
                            maybe_recover_soft_llm_error(&mut result);
                            let durable_terminal_reason = result
                                .terminal_reason
                                .map(|reason| format!("{reason:?}"));
                            let waiting_remote_job = mission_should_park_on_remote_build(
                                &mission_store,
                                &config.working_dir,
                                *mission_id,
                            )
                            .await;
                            if waiting_remote_job {
                                if let Some(run) = runner.durable_run.as_ref() {
                                    if let Err(error) = mission_store
                                        .heartbeat_mission_run(
                                            run.run_id,
                                            run.generation,
                                            MissionExecutionState::WaitingRemoteJob,
                                            None,
                                        )
                                        .await
                                    {
                                        tracing::warn!(mission_id = %mission_id, run_id = %run.run_id, %error, "Failed to park parallel mission on remote build");
                                    }
                                }
                                if let Err(error) = mission_store
                                    .update_mission_status(*mission_id, MissionStatus::Active)
                                    .await
                                {
                                    tracing::warn!(mission_id = %mission_id, %error, "Failed to keep parallel remote-wait mission active");
                                } else {
                                    let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                        mission_id: *mission_id,
                                        status: MissionStatus::Active,
                                        summary: Some("Waiting for durable remote validation".to_string()),
                                    });
                                }
                            } else {
                                runner
                                    .finish_durable_run(
                                        &mission_store,
                                        durable_terminal_reason.as_deref(),
                                    )
                                    .await;
                            }
                            let completion_evidence = completion_evidence_for_agent_result(&result);
                            tracing::info!(
                                "Parallel mission {} completed (success: {}, cost: {} cents)",
                                mission_id, result.success, result.cost_cents
                            );

                            // Parse rich tags and validate referenced files
                            let rich_tags = parse_rich_tags(&result.output);
                            let shared_files = if rich_tags.is_empty() {
                                None
                            } else {
                                let ws_id = mission_store
                                    .get_mission(*mission_id)
                                    .await
                                    .ok()
                                    .flatten()
                                    .map(|m| m.workspace_id);
                                let validate_root = if let Some(wsid) = ws_id {
                                    workspaces
                                        .get(wsid)
                                        .await
                                        .map(|w| crate::workspace::mission_workspace_dir_for_root(&w.path, *mission_id))
                                        .unwrap_or_else(|| config.working_dir.clone())
                                } else {
                                    config.working_dir.clone()
                                };
                                let files = validate_rich_tags(
                                    &rich_tags,
                                    &validate_root,
                                    ws_id,
                                    Some(*mission_id),
                                )
                                .await;
                                if files.is_empty() { None } else { Some(files) }
                            };

                            // Emit completion event with mission_id
                            // Mark failures as resumable
                            let resumable = !result.success;
                            let _ = events_tx.send(AgentEvent::AssistantMessage {
                                // Use a unique id so we don't overwrite the user_message event
                                // (event_id is used for de-dupe in the SQLite event logger).
                                id: Uuid::new_v4(),
                                content: result.output.clone(),
                                success: result.success,
                                cost_cents: result.cost_cents,
                                cost_source: result.cost_source,
                                usage: result.usage.clone(),
                                model: result.model_used.clone(),
                                model_normalized: result
                                    .model_used
                                    .as_deref()
                                    .map(crate::cost::normalized_model),
                                mission_id: Some(*mission_id),
                                shared_files,
                                resumable,
                                completion_evidence: Some(completion_evidence.clone()),
                            });

                            // Update automation executions based on agent outcome
                            if !waiting_remote_job {
                                let error_msg = if result.success {
                                    None
                                } else {
                                    Some(
                                        result.terminal_reason
                                            .map(|r| format!("{:?}", r))
                                            .unwrap_or_else(|| "Agent execution failed".to_string()),
                                    )
                                };
                                if let Err(e) = mission_store
                                    .complete_running_executions_for_mission(
                                        *mission_id,
                                        result.success,
                                        error_msg,
                                    )
                                    .await
                                {
                                    tracing::warn!(
                                        "Failed to complete running executions for parallel mission {}: {}",
                                        mission_id,
                                        e
                                    );
                                }
                            }

                            // Persist history for this mission
                            let entries: Vec<MissionHistoryEntry> = runner
                                .history
                                .iter()
                                .map(|(role, content)| MissionHistoryEntry {
                                    role: role.clone(),
                                    content: content.clone(),
                                })
                                .collect();
                            persist_mission_history_and_schedule_metadata_refresh(
                                &mission_store,
                                &events_tx,
                                *mission_id,
                                &entries,
                            )
                            .await;

                            if waiting_remote_job {
                                tracing::info!(
                                    mission_id = %mission_id,
                                    "Parallel mission turn parked on durable remote validation"
                                );
                                continue;
                            }

                            // Check if we should enqueue agent_finished automations.
                            // Skip for transient infrastructure failures (auth, rate limit,
                            // capacity) to avoid noisy retry loops.
                            let is_transient_infra_failure = matches!(
                                result.terminal_reason,
                                Some(TerminalReason::AuthError)
                                    | Some(TerminalReason::RateLimited)
                                    | Some(TerminalReason::CapacityLimited)
                            ) || is_transport_failure_evidence(&completion_evidence);
                            let cancellation_requested = runner.cancellation_requested();
                            let was_queue_empty = runner.queue.is_empty();
                            if is_transient_infra_failure
                                && is_transport_failure_evidence(&completion_evidence)
                                && !cancellation_requested
                                && was_queue_empty
                                && transport_auto_resumed_missions.insert(*mission_id)
                            {
                                tracing::info!(
                                    mission_id = %mission_id,
                                    "Auto-resuming parallel mission once after structured transport failure"
                                );
                                runner.queue_message(
                                    Uuid::new_v4(),
                                    "The previous turn ended because its provider transport disconnected. Reconcile the current workspace, remote jobs, and repository head, then resume the same task. Do not duplicate an accepted job or create a replacement writer.".to_string(),
                                    None,
                                    Some("transport_auto_resume".to_string()),
                                );
                            }
                            // Grok /goal sentinel hook for the parallel-runner
                            // path. Same contract as the main-session hook
                            // above: runs before the AgentFinished automations
                            // so a terminal sentinel disables the loop on this
                            // turn rather than after one extra continuation
                            // fire. (See `post_turn_handle_grok_goal`.)
                            if !is_transient_infra_failure {
                                post_turn_handle_grok_goal(
                                    &mission_store,
                                    &events_tx,
                                    *mission_id,
                                    &result.output,
                                    result.terminal_reason,
                                )
                                .await;
                            }
                            if was_queue_empty
                                && !is_transient_infra_failure
                                && !cancellation_requested
                            {
                                // Small delay so the UI can display the completion before restarting.
                                tokio::time::sleep(tokio::time::Duration::from_millis(500)).await;
                                let messages = agent_finished_automation_messages(
                                    &mission_store,
                                    *mission_id,
                                    &library,
                                    &workspaces,
                                )
                                .await;
                                for message in messages {
                                    if message.target_mission_id == *mission_id {
                                        runner.queue_message(Uuid::new_v4(), message.content, None, None);
                                        continue;
                                    }

                                    // Queue for targeted mission on the main runner if it is not
                                    // the current parallel mission.
                                    queue.push_back((
                                        Uuid::new_v4(),
                                        message.content,
                                        None,
                                        Some(message.target_mission_id),
                                        Some("automation".to_string()),
                                    ));
                                }
                            }

                            // Always try to start next queued message (if any)
                            if !runner.is_running() {
                                // Refresh session_id from the store in case a
                                // SessionIdUpdate event hasn't been processed yet
                                // (race between the events_rx and sleep poll arms).
                                if let Ok(Some(m)) = mission_store.get_mission(*mission_id).await {
                                    if m.session_id != runner.session_id {
                                        tracing::debug!(
                                            mission_id = %mission_id,
                                            old = ?runner.session_id,
                                            new = ?m.session_id,
                                            "Refreshed runner session_id from store"
                                        );
                                        runner.session_id = m.session_id;
                                    }
                                }
                                let next_content = runner
                                    .inflight_message()
                                    .or_else(|| runner.queue.front())
                                    .map(|message| message.content.clone());
                                if let Some(next_content) = next_content {
                                    if let Err(error) = activate_mission_id_for_message(
                                        &control_hub,
                                        &mission_store,
                                        &events_tx,
                                        *mission_id,
                                        &next_content,
                                    )
                                    .await
                                    {
                                        tracing::warn!(
                                            mission_id = %mission_id,
                                            "Failed to activate mission for its next queued turn: {error}"
                                        );
                                        let _ = events_tx.send(AgentEvent::Error {
                                            message: format!(
                                                "Queued delivery could not activate its mission: {error}"
                                            ),
                                            mission_id: Some(*mission_id),
                                            resumable: true,
                                        });
                                        completed_missions.push(*mission_id);
                                        continue;
                                    }
                                }
                                if let Err(error) = runner
                                    .acquire_durable_run(
                                        &mission_store,
                                        &format!("control:{session_user_id}"),
                                    )
                                    .await
                                {
                                    tracing::warn!(
                                        mission_id = %mission_id,
                                        "Failed to acquire next mission run lease: {error}"
                                    );
                                    let _ = events_tx.send(AgentEvent::Error {
                                        message: format!("Mission run lease rejected: {error}"),
                                        mission_id: Some(*mission_id),
                                        resumable: true,
                                    });
                                    completed_missions.push(*mission_id);
                                    continue;
                                }
                                let started = runner.start_next(
                                    config.clone(),
                                    Arc::clone(&root_agent),
                                    Arc::clone(&mcp),
                                    Arc::clone(&workspaces),
                                    library.clone(),
                                    events_tx.clone(),
                                    Arc::clone(&tool_hub),
                                    Arc::clone(&status),
                                    mission_cmd_tx.clone(),
                                    Arc::new(RwLock::new(Some(*mission_id))),
                                    secrets.clone(),
                                );

                                // If no queued messages, update status and mark for cleanup
                                if !started {
                                    maybe_finalize_terminal_mission(
                                        &mission_store,
                                        &events_tx,
                                        *mission_id,
                                        result.terminal_reason,
                                        result.terminal_evidence.as_deref(),
                                        Some(completion_evidence.completion_confidence),
                                        true,
                                        Some(result.output.as_str()),
                                        "parallel turn finished with no follow-up queued",
                                    )
                                    .await;
                                    // Task-board settle hook: if this mission is a
                                    // board worker, persist the outcome and notify
                                    // the boss. No-op otherwise.
                                    board::on_worker_settled(
                                        &mission_store,
                                        *mission_id,
                                        &result.output,
                                        result.terminal_reason,
                                        result.success,
                                    )
                                    .await;
                                    completed_missions.push(*mission_id);
                                }
                            }
                        }
                    }
                }

                // Remove completed runners and clean up their desktop sessions
                for mid in completed_missions {
                    parallel_runners.remove(&mid);
                    close_mission_desktop_sessions(
                        &mission_store,
                        mid,
                        &config.working_dir,
                    )
                    .await;
                    tracing::info!("Parallel mission {} removed from runners", mid);
                }

                // Task-board scheduler: spawn workers for ready tasks and
                // sweep zombies. Throttled — store scans on every 100ms tick
                // would hammer sqlite for nothing.
                if last_board_pass.elapsed() >= BOARD_PASS_INTERVAL {
                    last_board_pass = tokio::time::Instant::now();
                    // Missions actively executing a turn (parallel runners +
                    // the main session), so the scheduler won't wake a busy boss.
                    let mut running_ids: std::collections::HashSet<Uuid> = parallel_runners
                        .iter()
                        .filter(|(_, r)| r.is_running())
                        .map(|(id, _)| *id)
                        .collect();
                    if running.is_some() {
                        if let Some(mid) = running_mission_id {
                            running_ids.insert(mid);
                        }
                    }
                    let snapshot = board::RunnerSnapshot {
                        present: parallel_runners.keys().copied().collect(),
                        running_ids,
                        running_count: parallel_runners
                            .values()
                            .filter(|r| r.is_running())
                            .count(),
                        main_running: running.is_some(),
                    };
                    let max_parallel = crate::settings::max_parallel_missions_cached_or(
                        config.max_parallel_missions,
                    );
                    board::scheduler_pass(
                        &mission_store,
                        &self_cmd_tx,
                        &snapshot,
                        max_parallel,
                        &mut board_wake_state,
                        &board_outbox_inflight,
                    )
                    .await;
                }

                // FLEET-001 scheduling dispatch: expire past-deadline scheduled
                // missions, then start the highest-priority dispatchable one when
                // the main session is idle. Throttled like the board pass.
                if last_scheduler_pass.elapsed() >= SCHEDULER_PASS_INTERVAL {
                    last_scheduler_pass = tokio::time::Instant::now();
                    // Drop cooldown records that have aged out so a still-Pending
                    // (dropped) mission becomes eligible for retry.
                    scheduler_inflight
                        .retain(|_, at| at.elapsed() < SCHEDULER_DISPATCH_COOLDOWN);
                    match mission_store.get_scheduled_pending_missions().await {
                        Ok(pending) => {
                            let now = chrono::Utc::now();
                            // 1. Expire any scheduled mission whose deadline elapsed
                            //    before it ever dispatched. Missions still within the
                            //    dispatch cooldown are skipped (not added to `live`) so
                            //    a slow/lost start can't trigger a duplicate dispatch.
                            let mut live: Vec<Mission> = Vec::with_capacity(pending.len());
                            for m in pending {
                                if m.is_past_deadline(now) {
                                    tracing::info!(
                                        mission_id = %m.id,
                                        deadline = ?m.scheduling.deadline,
                                        "Scheduler: expiring scheduled mission past deadline"
                                    );
                                    let _ = mission_store.set_deferred_goal(m.id, None).await;
                                    if let Err(e) = mission_store
                                        .update_mission_status_with_reason(
                                            m.id,
                                            MissionStatus::Failed,
                                            Some("deadline_exceeded"),
                                        )
                                        .await
                                    {
                                        tracing::warn!(
                                            mission_id = %m.id,
                                            "Scheduler: failed to expire mission: {e}"
                                        );
                                    } else {
                                        maybe_schedule_mission_metadata_refresh_for_status(
                                            &mission_store,
                                            &events_tx,
                                            m.id,
                                            MissionStatus::Failed,
                                        );
                                        let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                                            mission_id: m.id,
                                            status: MissionStatus::Failed,
                                            summary: Some(
                                                "Scheduled mission expired: deadline passed before dispatch"
                                                    .to_string(),
                                            ),
                                        });
                                    }
                                } else if scheduler_inflight.contains_key(&m.id) {
                                    // A dispatch for this mission is still settling;
                                    // skip until the cooldown record ages out.
                                } else {
                                    live.push(m);
                                }
                            }
                            // 2. Dispatch the next runnable mission when there is spare
                            //    concurrency. The targeted scheduler message starts a
                            //    parallel runner (Case 2, explicit target => force
                            //    parallel), which DROPS at capacity — so mirror its check
                            //    (main + parallel < max_parallel) rather than requiring the
                            //    main session to be idle, otherwise eligible scheduled
                            //    missions stall behind a busy main runner.
                            let parallel_running = parallel_runners
                                .values()
                                .filter(|r| r.is_running())
                                .count();
                            let total_running =
                                parallel_running + if running.is_some() { 1 } else { 0 };
                            let max_parallel = crate::settings::max_parallel_missions_cached_or(
                                config.max_parallel_missions,
                            );
                            if total_running < max_parallel {
                                if let Some(next) =
                                    super::mission_store::select_next_runnable_mission(&live, now)
                                {
                                    let mission_id = next.id;
                                    let priority = next.scheduling.priority;
                                    if let Ok(Some(goal)) =
                                        mission_store.get_deferred_goal(mission_id).await
                                    {
                                        // Deliberately do NOT clear the goal here. The
                                        // Pending->Active transition that the dispatched
                                        // message triggers is what removes the mission from
                                        // `get_scheduled_pending_missions` (status filter),
                                        // so it can't be re-dispatched. Leaving the goal in
                                        // place means a rare dispatch drop (capacity race)
                                        // simply retries on the next pass instead of losing
                                        // the scheduled work.
                                        let (ack_tx, _ack_rx) = tokio::sync::oneshot::channel();
                                        match self_cmd_tx.try_send(ControlCommand::UserMessage {
                                            id: Uuid::new_v4(),
                                            content: goal,
                                            agent: None,
                                            target_mission_id: Some(mission_id),
                                            strict: false,
                                            source: Some("scheduler".to_string()),
                                            respond: ack_tx,
                                        }) {
                                            Ok(()) => {
                                                // Record the dispatch so the next passes
                                                // skip this mission until it flips to
                                                // Active (or the cooldown lets a dropped
                                                // start retry).
                                                scheduler_inflight.insert(
                                                    mission_id,
                                                    tokio::time::Instant::now(),
                                                );
                                                tracing::info!(
                                                    mission_id = %mission_id,
                                                    priority,
                                                    "Scheduler: dispatching scheduled mission"
                                                );
                                            }
                                            Err(e) => tracing::warn!(
                                                mission_id = %mission_id,
                                                "Scheduler: dispatch enqueue failed; will retry: {e}"
                                            ),
                                        }
                                    }
                                }
                            }
                        }
                        Err(e) => {
                            tracing::warn!(
                                "Scheduler: failed to list scheduled pending missions: {e}"
                            );
                        }
                    }
                }
            }
            // Force-reap a runner whose cancel was fired but whose
            // JoinHandle never resolved within the grace window. See
            // `runner_force_clear_deadline` for context.
            _ = async {
                match runner_force_clear_deadline {
                    Some(t) => tokio::time::sleep_until(t).await,
                    None => std::future::pending::<()>().await,
                }
            }, if runner_force_clear_deadline.is_some() && running.is_some() => {
                let stuck_mid = running_mission_id;
                let still_progressing = main_runner_active_tool_calls
                    .load(std::sync::atomic::Ordering::Relaxed)
                    > 0
                    || main_runner_last_activity.elapsed()
                        < super::controller_honesty::CANCEL_TIMEOUT_FRESH_PROGRESS;
                if still_progressing {
                    tracing::info!(
                        mission_id = ?stuck_mid,
                        "Deferring cancel-timeout force-clear: runner still has fresh progress"
                    );
                    runner_force_clear_deadline = Some(
                        tokio::time::Instant::now() + RUNNER_FORCE_CLEAR_GRACE,
                    );
                } else {
                tracing::warn!(
                    mission_id = ?stuck_mid,
                    "Force-aborting stuck runner: cancel fired but JoinHandle never resolved within {}s",
                    RUNNER_FORCE_CLEAR_GRACE.as_secs()
                );
                if let Some(handle) = running.take() {
                    handle.abort();
                }
                running_cancel = None;
                running_mission_id = None;
                running_backend_id = None;
                main_runner_activity = None;
                main_runner_active_tool_calls
                    .store(0, std::sync::atomic::Ordering::Relaxed);
                runner_force_clear_deadline = None;
                if let Some(run) = running_run.take() {
                    let _ = mission_store
                        .finish_mission_run(
                            run.run_id,
                            run.generation,
                            Some(cancel_timeout_interrupt_reason()),
                        )
                        .await;
                }
                if let Some(mid) = stuck_mid {
                    // Mark mission as Interrupted so it stays resumable.
                    // During a deploy drain this must stay `server_shutdown`
                    // — overwriting it with force_killed strands the writer
                    // (startup recovery and reconcile only resume restart
                    // reasons).
                    if let Err(e) = mission_store
                        .update_mission_status_with_reason(
                            mid,
                            MissionStatus::Interrupted,
                            Some(cancel_timeout_interrupt_reason()),
                        )
                        .await
                    {
                        tracing::warn!(
                            mission_id = %mid,
                            "Failed to mark force-cleared mission as Interrupted: {}",
                            e
                        );
                    } else {
                        maybe_schedule_mission_metadata_refresh_for_status(
                            &mission_store,
                            &events_tx,
                            mid,
                            MissionStatus::Interrupted,
                        );
                        let _ = events_tx.send(AgentEvent::MissionStatusChanged {
                            mission_id: mid,
                            status: MissionStatus::Interrupted,
                            summary: Some(
                                "Cancel timed out; force-aborted stuck runner.".to_string(),
                            ),
                        });
                    }
                    if let Err(e) = mission_store
                        .complete_running_executions_for_mission(
                            mid,
                            false,
                            Some("Force-aborted stuck runner after cancel timed out".to_string()),
                        )
                        .await
                    {
                        tracing::warn!(
                            mission_id = %mid,
                            "Failed to complete running executions on force-clear: {}",
                            e
                        );
                    }
                    close_mission_desktop_sessions(
                        &mission_store,
                        mid,
                        &config.working_dir,
                    )
                    .await;
                }
                }
            }
            // Update last_activity for runners when we receive events for them
            event = events_rx.recv() => {
                if let Ok(event) = event {
                    // Extract mission_id from event if present
                    let mission_id = match &event {
                        AgentEvent::ToolCall { mission_id, .. } => *mission_id,
                        AgentEvent::ToolResult { mission_id, .. } => *mission_id,
                        AgentEvent::Thinking { mission_id, .. } => *mission_id,
                        AgentEvent::TextDelta { mission_id, .. } => *mission_id,
                        AgentEvent::UserMessage { mission_id, .. } => *mission_id,
                        AgentEvent::AssistantMessage { mission_id, .. } => *mission_id,
                        AgentEvent::Error { mission_id, .. } => *mission_id,
                        AgentEvent::MissionStatusChanged { mission_id, .. } => Some(*mission_id),
                        AgentEvent::AgentPhase { mission_id, .. } => *mission_id,
                        AgentEvent::AgentTree { mission_id, .. } => *mission_id,
                        AgentEvent::Progress { mission_id, .. } => *mission_id,
                        AgentEvent::MissionActivity { mission_id, .. } => *mission_id,
                        AgentEvent::SessionIdUpdate { mission_id, .. } => Some(*mission_id),
                        AgentEvent::GoalIteration { mission_id, .. } => *mission_id,
                        AgentEvent::GoalStatus { mission_id, .. } => *mission_id,
                        _ => None,
                    };
                    // Update last_activity for matching runner (main or parallel)
                    if let Some(mid) = mission_id {
                        if running_mission_id == Some(mid) {
                            // Update main runner activity
                            main_runner_last_activity = std::time::Instant::now();
                        } else if let Some(runner) = parallel_runners.get_mut(&mid) {
                            // Update parallel runner activity
                            runner.touch();
                        }
                    }

                    // --- Activity tracking & subtask detection ---
                    match &event {
                        AgentEvent::ToolCall { name, args, tool_call_id, mission_id } => {
                            if let Some(mid) = mission_id {
                                let label = activity_label_from_tool_call(name, args);

                                // Update activity on runner
                                if running_mission_id == Some(*mid) {
                                    main_runner_activity = Some(label.clone());
                                    main_runner_active_tool_calls
                                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                } else if let Some(runner) = parallel_runners.get_mut(mid) {
                                    runner.current_activity = Some(label.clone());
                                    runner
                                        .active_tool_calls
                                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                }

                                let durable_run = if running_mission_id == Some(*mid) {
                                    running_run.clone()
                                } else {
                                    parallel_runners
                                        .get(mid)
                                        .and_then(|runner| runner.durable_run.clone())
                                };
                                if let Some(run) = durable_run {
                                    let now = chrono::Utc::now();
                                    let waiting_state = if is_user_wait_tool(name) {
                                        MissionExecutionState::WaitingUser
                                    } else {
                                        MissionExecutionState::WaitingTool
                                    };
                                    let _ = mission_store
                                        .heartbeat_mission_run(
                                            run.run_id,
                                            run.generation,
                                            waiting_state,
                                            None,
                                        )
                                        .await;
                                    let execution = MissionToolExecution {
                                        tool_call_id: tool_call_id.clone(),
                                        run_id: run.run_id,
                                        tool_kind: name.clone(),
                                        state: MissionToolExecutionState::Provisional,
                                        started_at: now.to_rfc3339(),
                                        heartbeat_at: now.to_rfc3339(),
                                        deadline_at: (now
                                            + chrono::Duration::seconds(
                                                tool_execution_deadline_secs(name, args),
                                            ))
                                        .to_rfc3339(),
                                        process_pid: None,
                                        durable_job_id: None,
                                        completed_at: None,
                                        exit_status: None,
                                        failure_class: None,
                                    };
                                    if let Err(error) = mission_store
                                        .register_tool_execution(&execution)
                                        .await
                                    {
                                        tracing::warn!(
                                            mission_id = %mid,
                                            tool_call_id = %tool_call_id,
                                            "Failed to register tool execution: {error}"
                                        );
                                    }
                                }

                                // Background-task auto-resume: stash the command
                                // for any `Bash` call so the matching ToolResult
                                // can attach it to a captured background task.
                                if background_autoresume_enabled
                                    && name == "Bash"
                                    && pending_bash_commands.len() < MAX_PENDING_BASH_COMMANDS
                                {
                                    if let Some(cmd) =
                                        args.get("command").and_then(|v| v.as_str())
                                    {
                                        pending_bash_commands
                                            .insert(tool_call_id.clone(), cmd.to_string());
                                    }
                                }

                                // Emit activity event for real-time SSE
                                let _ = events_tx.send(AgentEvent::MissionActivity {
                                    label,
                                    tool_name: name.clone(),
                                    mission_id: Some(*mid),
                                });

                                // Subtask detection
                                let is_subtask = matches!(name.as_str(),
                                    "Task" | "delegate_task" | "TaskCreate" | "Skill"
                                );
                                if is_subtask {
                                    let desc: String = args.get("description")
                                        .or_else(|| args.get("subject"))
                                        .or_else(|| args.get("prompt"))
                                        .and_then(|v| v.as_str())
                                        .unwrap_or("Subtask")
                                        .chars().take(120).collect();
                                    let info = super::mission_runner::SubtaskInfo {
                                        tool_call_id: tool_call_id.clone(),
                                        description: desc,
                                        completed: false,
                                    };
                                    let (total, completed) = if running_mission_id == Some(*mid) {
                                        main_runner_subtasks.push(info);
                                        (main_runner_subtasks.len(), main_runner_subtasks.iter().filter(|s| s.completed).count())
                                    } else if let Some(runner) = parallel_runners.get_mut(mid) {
                                        runner.subtasks.push(info);
                                        (runner.subtasks.len(), runner.subtasks.iter().filter(|s| s.completed).count())
                                    } else {
                                        (0, 0)
                                    };
                                    if total > 0 {
                                        let _ = events_tx.send(AgentEvent::Progress {
                                            total_subtasks: total,
                                            completed_subtasks: completed,
                                            current_subtask: None,
                                            depth: 0,
                                            mission_id: Some(*mid),
                                        });
                                    }
                                }

                                // Desktop session detection from ToolCall.
                                // Claude Code does not emit ToolResult for MCP tools,
                                // so we detect the session start from the ToolCall and
                                // spawn a background task to attribute Wayland compositor processes.
                                let is_desktop_start = matches!(
                                    name.as_str(),
                                    "desktop_start_session"
                                        | "desktop_desktop_start_session"
                                        | "mcp__desktop__desktop_start_session"
                                );
                                if is_desktop_start {
                                    let store = mission_store.clone();
                                    let mid = *mid;
                                    let working_dir = config.working_dir.clone();
                                    tokio::spawn(async move {
                                        // Wait for the compositor to start.
                                        tokio::time::sleep(std::time::Duration::from_secs(4)).await;

                                        let displays =
                                            super::desktop::get_running_wayland_displays(&working_dir).await;
                                        if displays.is_empty() {
                                            tracing::debug!(
                                                "No Wayland displays found for desktop attribution"
                                            );
                                            return;
                                        }

                                        // Load current mission sessions
                                        let Ok(Some(mission)) = store.get_mission(mid).await
                                        else {
                                            return;
                                        };
                                        let mut sessions = mission.desktop_sessions.clone();
                                        let tracked: std::collections::HashSet<String> =
                                            sessions.iter().map(|s| s.display.clone()).collect();

                                        let mut changed = false;
                                        for disp in displays {
                                            if !tracked.contains(&disp) {
                                                sessions.push(DesktopSessionInfo {
                                                    display: disp.clone(),
                                                    resolution: None,
                                                    display_server: Some("wayland".to_string()),
                                                    compositor: Some("sway-headless".to_string()),
                                                    started_at: now_string(),
                                                    stopped_at: None,
                                                    screenshots_dir: None,
                                                    browser: None,
                                                    url: None,
                                                    mission_id: Some(mid),
                                                    keep_alive_until: None,
                                                });
                                                changed = true;
                                                tracing::info!(
                                                    display_id = %disp,
                                                    mission_id = %mid,
                                                    "Desktop session attributed from ToolCall"
                                                );
                                            }
                                        }

                                        if changed {
                                            if let Err(err) = store
                                                .update_mission_desktop_sessions(mid, &sessions)
                                                .await
                                            {
                                                tracing::warn!(
                                                    "Failed to persist desktop session from ToolCall for mission {}: {}",
                                                    mid,
                                                    err
                                                );
                                            }
                                        }
                                    });
                                }
                            }
                        }
                        AgentEvent::ToolResult { tool_call_id, mission_id, .. } => {
                            if let Some(mid) = mission_id {
                                // Clear activity label (tool finished)
                                if running_mission_id == Some(*mid) {
                                    main_runner_activity = None;
                                    // Saturating decrement: never go below 0
                                    // if we somehow see a stray ToolResult.
                                    let _ = main_runner_active_tool_calls
                                        .fetch_update(
                                            std::sync::atomic::Ordering::Relaxed,
                                            std::sync::atomic::Ordering::Relaxed,
                                            |c| if c > 0 { Some(c - 1) } else { None },
                                        );
                                } else if let Some(runner) = parallel_runners.get_mut(mid) {
                                    runner.current_activity = None;
                                    let _ = runner.active_tool_calls.fetch_update(
                                        std::sync::atomic::Ordering::Relaxed,
                                        std::sync::atomic::Ordering::Relaxed,
                                        |c| if c > 0 { Some(c - 1) } else { None },
                                    );
                                }

                                let durable_run = if running_mission_id == Some(*mid) {
                                    running_run.clone()
                                } else {
                                    parallel_runners
                                        .get(mid)
                                        .and_then(|runner| runner.durable_run.clone())
                                };
                                if let Some(run) = durable_run {
                                    match mission_store
                                        .finish_tool_execution(
                                            run.run_id,
                                            tool_call_id,
                                            MissionToolExecutionState::Completed,
                                            Some(0),
                                            None,
                                        )
                                        .await
                                    {
                                        Ok(true) => {
                                            let _ = mission_store
                                                .heartbeat_mission_run(
                                                    run.run_id,
                                                    run.generation,
                                                    MissionExecutionState::Running,
                                                    None,
                                                )
                                                .await;
                                        }
                                        Ok(false) => tracing::debug!(
                                            mission_id = %mid,
                                            tool_call_id = %tool_call_id,
                                            "Stored late or unmatched tool result without mutating current run"
                                        ),
                                        Err(error) => tracing::warn!(
                                            mission_id = %mid,
                                            tool_call_id = %tool_call_id,
                                            "Failed to finish tool execution: {error}"
                                        ),
                                    }
                                }

                                // Mark subtask complete if applicable
                                let subtasks: Option<&mut Vec<super::mission_runner::SubtaskInfo>> =
                                    if running_mission_id == Some(*mid) {
                                        Some(&mut main_runner_subtasks)
                                    } else {
                                        parallel_runners.get_mut(mid).map(|r| &mut r.subtasks)
                                    };
                                if let Some(subtasks) = subtasks {
                                    let mut changed = false;
                                    for s in subtasks.iter_mut() {
                                        if s.tool_call_id == *tool_call_id && !s.completed {
                                            s.completed = true;
                                            changed = true;
                                            break;
                                        }
                                    }
                                    if changed {
                                        let total = subtasks.len();
                                        let completed = subtasks.iter().filter(|s| s.completed).count();
                                        let _ = events_tx.send(AgentEvent::Progress {
                                            total_subtasks: total,
                                            completed_subtasks: completed,
                                            current_subtask: None,
                                            depth: 0,
                                            mission_id: Some(*mid),
                                        });
                                    }
                                }
                            }
                        }
                        AgentEvent::Thinking { done, mission_id, .. } => {
                            if let Some(mid) = mission_id {
                                let label = if *done { None } else { Some("Thinking…".to_string()) };
                                if running_mission_id == Some(*mid) {
                                    main_runner_activity = label;
                                } else if let Some(runner) = parallel_runners.get_mut(mid) {
                                    runner.current_activity = label;
                                }
                            }
                        }
                        _ => {}
                    }

                    // Background-task auto-resume capture: when a `Bash` tool
                    // result is the CLI's background-launch confirmation, record
                    // the task so the watcher can wake the agent once it finishes.
                    // (Must run before the desktop block below, which `continue`s
                    // past non-desktop tool results.)
                    if background_autoresume_enabled {
                        if let AgentEvent::ToolResult {
                            tool_call_id,
                            name,
                            result,
                            mission_id,
                        } = &event
                        {
                            // Always reclaim the correlated command, even if this
                            // isn't a background start, so the map can't leak.
                            let command = pending_bash_commands.remove(tool_call_id);
                            if name == "Bash" {
                                if let (Some(mid), Some(text)) =
                                    (mission_id, tool_result_text(result))
                                {
                                    if let Some((task_id, output_path)) =
                                        super::runners::claudecode::parse_background_task_start(
                                            &text,
                                        )
                                    {
                                        let task = super::mission_runner::BackgroundTask {
                                            id: task_id.clone(),
                                            output_path: output_path.clone(),
                                            command: command.unwrap_or_default(),
                                            started_at: std::time::Instant::now(),
                                        };
                                        tracing::info!(
                                            mission_id = %mid,
                                            background_task_id = %task_id,
                                            output_path = %output_path,
                                            "Captured Claude Code background task; \
                                             scheduling auto-resume on completion"
                                        );
                                        // Mirror onto the runner (informational).
                                        if let Some(runner) = parallel_runners.get_mut(mid) {
                                            runner
                                                .background_tasks
                                                .insert(task_id.clone(), task.clone());
                                        }
                                        // Source of truth: the shared registry.
                                        background_tasks
                                            .write()
                                            .await
                                            .entry(*mid)
                                            .or_default()
                                            .insert(task_id, task);
                                    }
                                }
                            } else if name.ends_with("durable_job_start") {
                                if let (Some(mid), Some(job)) =
                                    (mission_id, parse_durable_job_result(result))
                                {
                                    let Some(job_id) =
                                        job.get("id").and_then(|value| value.as_str())
                                    else {
                                        continue;
                                    };
                                    let command = job
                                        .get("command")
                                        .and_then(|value| value.as_str())
                                        .unwrap_or_default()
                                        .to_string();
                                    let mut output_path = job
                                        .get("stdout_log")
                                        .and_then(|value| value.as_str())
                                        .unwrap_or_default()
                                        .to_string();
                                    if let Ok(Some(mission)) = mission_store.get_mission(*mid).await {
                                        if let Some(workspace) =
                                            workspaces.get(mission.workspace_id).await
                                        {
                                            output_path = WorkspaceExec::new(workspace)
                                                .translate_path_for_container(
                                                    std::path::Path::new(&output_path),
                                                );
                                        }
                                    }
                                    let task = super::mission_runner::BackgroundTask {
                                        id: format!("durable:{job_id}"),
                                        output_path,
                                        command,
                                        started_at: std::time::Instant::now(),
                                    };
                                    tracing::info!(
                                        mission_id = %mid,
                                        durable_job_id = %job_id,
                                        "Captured durable background job; scheduling auto-resume on completion"
                                    );
                                    if let Some(runner) = parallel_runners.get_mut(mid) {
                                        runner
                                            .background_tasks
                                            .insert(task.id.clone(), task.clone());
                                    }
                                    background_tasks
                                        .write()
                                        .await
                                        .entry(*mid)
                                        .or_default()
                                        .insert(task.id.clone(), task);
                                }
                            }
                        }
                    }

                    // Track desktop sessions for mission reconnect/resume.
                    if let AgentEvent::ToolResult { name, result, mission_id, .. } = &event {
                        let Some(mid) = mission_id else {
                            continue;
                        };

                        let tool_name = name.as_str();
                        let is_start = matches!(
                            tool_name,
                            "desktop_start_session"
                                | "desktop_desktop_start_session"
                                | "mcp__desktop__desktop_start_session"
                        );
                        let is_stop = matches!(
                            tool_name,
                            "desktop_stop_session"
                                | "desktop_close_session"
                                | "desktop_desktop_stop_session"
                                | "desktop_desktop_close_session"
                                | "mcp__desktop__desktop_stop_session"
                                | "mcp__desktop__desktop_close_session"
                        );

                        if !is_start && !is_stop {
                            continue;
                        }

                        let Some(obj) = parse_tool_result_object(result) else {
                            continue;
                        };

                        let Some(display) = obj
                            .get("display")
                            .and_then(|v| v.as_str())
                            .map(|v| v.to_string())
                        else {
                            continue;
                        };

                        let Ok(Some(mission)) = mission_store.get_mission(*mid).await else {
                            continue;
                        };

                        let mut sessions = mission.desktop_sessions.clone();
                        let now = now_string();

                        if is_start {
                            let resolution = obj
                                .get("resolution")
                                .and_then(|v| v.as_str())
                                .map(|v| v.to_string());
                            let screenshots_dir = obj
                                .get("screenshots_dir")
                                .and_then(|v| v.as_str())
                                .map(|v| v.to_string());
                            let display_server = obj
                                .get("display_server")
                                .and_then(|v| v.as_str())
                                .map(|v| v.to_string())
                                .or_else(|| Some("wayland".to_string()));
                            let compositor = obj
                                .get("compositor")
                                .and_then(|v| v.as_str())
                                .map(|v| v.to_string())
                                .or_else(|| Some("sway-headless".to_string()));
                            let browser = obj
                                .get("browser")
                                .and_then(|v| v.as_str())
                                .map(|v| v.to_string());
                            let url = obj
                                .get("url")
                                .and_then(|v| v.as_str())
                                .map(|v| v.to_string());

                            if let Some(existing) = sessions
                                .iter_mut()
                                .rev()
                                .find(|session| session.display == display && session.stopped_at.is_none())
                            {
                                existing.resolution = resolution;
                                existing.display_server = display_server;
                                existing.compositor = compositor;
                                existing.screenshots_dir = screenshots_dir;
                                existing.browser = browser;
                                existing.url = url;
                                existing.started_at = now.clone();
                            } else {
                                sessions.push(DesktopSessionInfo {
                                    display,
                                    resolution,
                                    display_server,
                                    compositor,
                                    started_at: now.clone(),
                                    stopped_at: None,
                                    screenshots_dir,
                                    browser,
                                    url,
                                    mission_id: Some(*mid),
                                    keep_alive_until: None,
                                });
                            }
                        } else if let Some(existing) = sessions
                            .iter_mut()
                            .rev()
                            .find(|session| session.display == display && session.stopped_at.is_none())
                        {
                            existing.stopped_at = Some(now.clone());
                        }

                        if let Err(err) = mission_store
                            .update_mission_desktop_sessions(*mid, &sessions)
                            .await
                        {
                            tracing::warn!(
                                "Failed to persist desktop session info for mission {}: {}",
                                mid,
                                err
                            );
                        }
                    }

                    // Handle session ID updates for backends that generate their own IDs.
                    if let AgentEvent::SessionIdUpdate { mission_id, session_id } = &event {
                        if let Err(err) = mission_store
                            .update_mission_session_id(*mission_id, session_id)
                            .await
                        {
                            tracing::warn!(
                                "Failed to update session ID for mission {}: {}",
                                mission_id,
                                err
                            );
                        } else {
                            tracing::debug!(
                                mission_id = %mission_id,
                                session_id = %session_id,
                                "Updated mission session ID from backend"
                            );
                        }
                        // Also update the parallel runner's cached session_id so the
                        // next turn picks up the new value instead of the stale one.
                        if let Some(runner) = parallel_runners.get_mut(mission_id) {
                            runner.session_id = Some(session_id.clone());
                        }
                    }

                    // Persist `/goal` metadata so refreshes and restart recovery
                    // can continue through codex goal mode instead of a plain turn.
                    if let AgentEvent::UserMessage {
                        content,
                        mission_id: Some(mid),
                        ..
                    } = &event
                    {
                        if let Some(objective) = parse_goal_objective(content) {
                            if let Err(err) = mission_store
                                .update_mission_goal(*mid, true, Some(&objective))
                                .await
                            {
                                tracing::warn!(
                                    mission_id = %mid,
                                    "Failed to persist goal metadata from user message: {}",
                                    err
                                );
                            }
                        }
                    }

                    if let AgentEvent::GoalStatus {
                        status,
                        objective,
                        mission_id: Some(mid),
                    } = &event
                    {
                        let goal_mode = status != "cleared";
                        let objective = goal_mode.then_some(objective.as_str());
                        if let Err(err) = mission_store
                            .update_mission_goal(*mid, goal_mode, objective)
                            .await
                        {
                            tracing::warn!(
                                mission_id = %mid,
                                status = %status,
                                "Failed to persist goal metadata from goal status: {}",
                                err
                            );
                        }
                    }
                }
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn run_single_control_turn(
    mut config: Config,
    _root_agent: AgentRef,
    mcp: Arc<McpRegistry>,
    workspaces: workspace::SharedWorkspaceStore,
    library: SharedLibrary,
    events_tx: broadcast::Sender<AgentEvent>,
    tool_hub: Arc<FrontendToolHub>,
    status: Arc<RwLock<ControlStatus>>,
    cancel: CancellationToken,
    history: Vec<(String, String)>,
    user_message: String,
    mission_control: Option<crate::tools::mission::MissionControl>,
    tree_snapshot: Arc<RwLock<Option<AgentTreeNode>>>,
    progress_snapshot: Arc<RwLock<ExecutionProgress>>,
    mission_id: Option<Uuid>,
    workspace_id: Option<Uuid>,
    backend_id: Option<String>,
    model_override: Option<String>,
    model_effort: Option<String>,
    fast_mode: bool,
    agent_override: Option<String>,
    session_id: Option<String>,
    force_session_resume: bool,
    mission_config_profile: Option<String>,
    boss_user_id: Option<String>,
    pr_readonly: bool,
) -> crate::agents::AgentResult {
    let is_claudecode = backend_id.as_deref() == Some("claudecode");
    let is_codex = backend_id.as_deref() == Some("codex");
    // Get config profile: mission's config_profile takes priority over workspace's
    let workspace_config_profile = if let Some(ws_id) = workspace_id {
        workspaces.get(ws_id).await.and_then(|ws| ws.config_profile)
    } else {
        None
    };
    let effective_config_profile = mission_config_profile.or(workspace_config_profile);
    let requested_model = model_override;
    let requested_model_effort = model_effort;
    if let Some(ref model) = requested_model {
        config.default_model = Some(model.clone());
    } else if is_claudecode && config.default_model.is_some() {
        config.default_model = config
            .default_model
            .take()
            .map(|model| crate::library::normalize_claude_code_default_model(Some(model)));
    } else if is_claudecode && config.default_model.is_none() {
        if let Some(default_model) =
            resolve_claudecode_default_model(&library, effective_config_profile.as_deref()).await
        {
            config.default_model = Some(default_model);
        }
    } else if is_codex {
        // Pin Codex instead of inheriting the global DEFAULT_MODEL, which is
        // usually a Claude/OpenCode slug and invalid for the Codex CLI.
        config.default_model = Some(resolve_codex_default_model());
    } else if (backend_id.as_deref() == Some("opencode")
        && effective_config_profile.is_some()
        && requested_model.is_none())
        || (backend_id.as_deref() == Some("grok") && requested_model.is_none())
    {
        config.default_model = None;
    } else if backend_id.as_deref() == Some("gemini") && requested_model.is_none() {
        config.default_model = Some(resolve_gemini_default_model());
    } else if backend_id.as_deref() == Some("chatgpt_ui") && requested_model.is_none() {
        // Web model labels are account-specific. Never invent or inherit a
        // CLI/API model slug for the browser harness.
        config.default_model =
            super::mission_runner::get_backend_string_setting("chatgpt_ui", "model");
    }
    if let Some(ref agent) = agent_override {
        config.opencode_agent = Some(agent.clone());
    }
    // Ensure a workspace directory for this mission (if applicable).
    let (working_dir_path, runtime_workspace) = if let Some(mid) = mission_id {
        let mut ws = workspace::resolve_workspace(&workspaces, &config, workspace_id).await;
        if let Err(e) =
            workspace::sync_workspace_mcp_binaries_for_workspace(&config.working_dir, &ws).await
        {
            tracing::warn!(
                workspace = %ws.name,
                error = %e,
                "Failed to sync MCP binaries into workspace"
            );
        }
        // Get library for skill syncing
        let lib_guard = library.read().await;
        let lib_ref = lib_guard.as_ref().map(|l| l.as_ref());
        let dir = match Box::pin(workspace::prepare_mission_workspace_with_skills_backend(
            &mut ws,
            &mcp,
            lib_ref,
            mid,
            backend_id.as_deref().unwrap_or("opencode"),
            None, // custom_providers: TODO integrate with provider store
            effective_config_profile.as_deref(),
            boss_user_id.as_deref(),
            Some(&config.working_dir),
            !pr_readonly,
        ))
        .await
        {
            Ok(dir) => dir,
            Err(e) => {
                tracing::warn!("Failed to prepare mission workspace: {}", e);
                ws.path.clone()
            }
        };
        (dir, Some(ws))
    } else {
        (
            config.working_dir.clone(),
            Some(workspace::Workspace::default_host(
                config.working_dir.clone(),
            )),
        )
    };

    if let Some(ws) = runtime_workspace.as_ref() {
        if let Err(e) = Box::pin(workspace::write_runtime_workspace_state(
            &config.working_dir,
            ws,
            &working_dir_path,
            mission_id,
            &config.context.context_dir_name,
        ))
        .await
        {
            tracing::warn!("Failed to write runtime workspace state: {}", e);
        }
    }

    // For Telegram missions, append channel instructions and memory awareness
    // to CLAUDE.md so the backend LLM adopts the bot persona.
    if user_message.contains("[Telegram from ") {
        let claude_md_path = working_dir_path.join("CLAUDE.md");
        tracing::info!(
            mission_id = ?mission_id,
            claude_md_path = %claude_md_path.display(),
            claude_md_exists = claude_md_path.exists(),
            "Telegram message detected in control path, attempting CLAUDE.md injection"
        );
        // Create the file if it doesn't exist so that non-Claude-Code
        // backends (e.g. opencode) also get the identity injection.
        if !claude_md_path.exists() {
            let _ = std::fs::write(&claude_md_path, "");
        }
        let actions_available = mission_id
            .and_then(crate::api::telegram::build_internal_telegram_action_token)
            .is_some()
            && super::mission_runner::localhost_api_base_url_from_env().is_some();
        super::mission_runner::inject_telegram_identity_into_claude_md(
            &claude_md_path,
            &user_message,
            actions_available,
        );
    }

    // Build a task prompt that includes conversation context with size limits.
    let history_for_prompt = match history.last() {
        Some((role, content)) if role == "user" && content == &user_message => {
            &history[..history.len() - 1]
        }
        _ => history.as_slice(),
    };
    let history_context =
        build_history_context(history_for_prompt, config.context.max_history_total_chars);
    let mut convo = String::new();
    convo.push_str(&crate::util::frame_turn_prompt(
        &history_context,
        &user_message,
    ));
    convo.push_str("\n\nInstructions:\n- Respond to the CURRENT user request. The conversation history is context only: do not resume or continue earlier tasks from it unless the current request asks you to.\n- Use available tools as needed.\n- For large data processing tasks (>10KB), prefer executing scripts rather than inline processing.\n");
    if pr_readonly {
        convo.push_str("\nPR READ-ONLY CAPABILITY (server-enforced): inspect and run verification only. Do not edit tracked files, commit, push, comment, resolve threads, approve, close, or merge. End with exactly one explicit terminal line: `VERDICT: CLEAN`, `VERDICT: BLOCKED`, or `VERDICT: INFRA_BLOCKED`. Git/gh mutation commands are disabled.\n");
    }
    let _task = match crate::task::Task::new(convo.clone(), Some(1000)) {
        Ok(t) => t,
        Err(e) => {
            let r = crate::agents::AgentResult::failure(format!("Failed to create task: {}", e), 0);
            return r;
        }
    };

    // Context for agent execution.
    let mut ctx = AgentContext::new(config.clone(), working_dir_path);
    ctx.mission_control = mission_control;
    ctx.control_events = Some(events_tx.clone());
    ctx.frontend_tool_hub = Some(tool_hub.clone());
    ctx.control_status = Some(status.clone());
    ctx.cancel_token = Some(cancel.clone());
    ctx.tree_snapshot = Some(tree_snapshot);
    ctx.progress_snapshot = Some(progress_snapshot);
    ctx.mission_id = mission_id;
    ctx.mcp = Some(mcp);

    let fallback_workspace = workspace::Workspace::default_host(config.working_dir.clone());
    let exec_workspace = runtime_workspace.as_ref().unwrap_or(&fallback_workspace);

    // Execute based on backend
    let result = match backend_id.as_deref() {
        Some("claudecode") => {
            let mid = match require_mission_id(mission_id, "Claude Code", &events_tx) {
                Ok(id) => id,
                Err(r) => return r,
            };
            // Continuation: prior assistant response in history, or an
            // explicit resume request (e.g. mission resume operations where
            // the session exists but history may not have assistant
            // messages yet).
            let is_continuation =
                force_session_resume || history.iter().any(|(role, _)| role == "assistant");
            // Full recovery orchestration (transport retries, SIGKILL OAuth
            // refresh, stale-credential retry, account rotation) is shared
            // with the mission dispatch via the runners layer. This arm
            // previously carried a near-duplicate copy that was missing the
            // SIGKILL refresh and the initial auth retry.
            use crate::api::runners::HarnessRunner as _;
            Box::pin(crate::api::runners::ClaudeCodeRunner.run_turn(
                crate::api::runners::TurnContext {
                    workspace: exec_workspace,
                    work_dir: &ctx.working_dir,
                    message: &user_message,
                    model: config.default_model.as_deref(),
                    model_effort: requested_model_effort.as_deref(),
                    fast_mode,
                    agent: config.opencode_agent.as_deref(),
                    mission_id: mid,
                    events_tx: events_tx.clone(),
                    cancel: cancel.clone(),
                    app_working_dir: &config.working_dir,
                    session_id: session_id.as_deref(),
                    is_continuation,
                    extras: crate::api::runners::TurnExtras::ClaudeCode {
                        secrets: None, // not available in control context
                        tool_hub: Some(tool_hub.clone()),
                        status: Some(status.clone()),
                        history: &history,
                        max_history_total_chars: config.context.max_history_total_chars,
                    },
                },
            ))
            .await
        }
        Some("grok") => {
            let mid = match require_mission_id(mission_id, "Grok Build", &events_tx) {
                Ok(id) => id,
                Err(r) => return r,
            };
            let is_continuation =
                force_session_resume || history.iter().any(|(role, _)| role == "assistant");
            let grok_message_owned: String = match canonical_goal_message(&user_message) {
                Some(goal) => goal,
                None => convo.clone(),
            };
            use crate::api::runners::HarnessRunner as _;
            Box::pin(
                crate::api::runners::GrokRunner.run_turn(crate::api::runners::TurnContext {
                    workspace: exec_workspace,
                    work_dir: &ctx.working_dir,
                    message: &grok_message_owned,
                    model: requested_model
                        .as_deref()
                        .or(config.default_model.as_deref()),
                    model_effort: None,
                    fast_mode: false,
                    agent: None,
                    mission_id: mid,
                    events_tx: events_tx.clone(),
                    cancel,
                    app_working_dir: &config.working_dir,
                    session_id: session_id.as_deref(),
                    is_continuation,
                    extras: crate::api::runners::TurnExtras::None,
                }),
            )
            .await
        }
        Some("codex") => {
            let mid = match require_mission_id(mission_id, "Codex", &events_tx) {
                Ok(id) => id,
                Err(r) => return r,
            };
            let requested_codex_model = requested_model
                .as_deref()
                .or(config.default_model.as_deref());
            // Goal-mode missions need the raw `/goal <objective>` message to
            // reach the codex backend; the wrapped `convo` buries the prefix
            // and breaks `parse_goal_prefix`. Mirror the same routing the
            // mission_runner dispatch uses.
            let codex_message_owned: String = match canonical_goal_message(&user_message) {
                Some(goal) => goal,
                None => convo.clone(),
            };
            let codex_message: &str = codex_message_owned.as_str();
            // Shared rotation wrapper: identical account rotation + usage-cap
            // cooldown behaviour to the initial mission dispatch. Previously
            // this path ran a single bare run_codex_turn with no credential
            // override, so a follow-up/retry on a usage-capped ChatGPT
            // account kept re-hitting the same cap instead of rotating to
            // the next account. Fallback-model and tool-stall retries are
            // handled inside the wrapper per attempted credential.
            use crate::api::runners::HarnessRunner as _;
            Box::pin(
                crate::api::runners::CodexRunner.run_turn(crate::api::runners::TurnContext {
                    workspace: exec_workspace,
                    work_dir: &ctx.working_dir,
                    message: codex_message,
                    model: requested_codex_model,
                    model_effort: requested_model_effort.as_deref(),
                    fast_mode,
                    agent: config.opencode_agent.as_deref(),
                    mission_id: mid,
                    events_tx: events_tx.clone(),
                    cancel: cancel.clone(),
                    app_working_dir: &config.working_dir,
                    session_id: session_id.as_deref(),
                    is_continuation: false,
                    extras: crate::api::runners::TurnExtras::None,
                }),
            )
            .await
        }
        Some("gemini") => {
            let mid = match require_mission_id(mission_id, "Gemini CLI", &events_tx) {
                Ok(id) => id,
                Err(r) => return r,
            };
            use crate::api::runners::HarnessRunner as _;
            Box::pin(
                crate::api::runners::GeminiRunner.run_turn(crate::api::runners::TurnContext {
                    workspace: exec_workspace,
                    work_dir: &ctx.working_dir,
                    message: &convo,
                    model: config.default_model.as_deref(),
                    model_effort: None,
                    fast_mode: false,
                    agent: config.opencode_agent.as_deref(),
                    mission_id: mid,
                    events_tx: events_tx.clone(),
                    cancel,
                    app_working_dir: &config.working_dir,
                    session_id: session_id.as_deref(),
                    is_continuation: false,
                    extras: crate::api::runners::TurnExtras::None,
                }),
            )
            .await
        }
        Some("chatgpt_ui") => {
            let mid = match require_mission_id(mission_id, "ChatGPT UI", &events_tx) {
                Ok(id) => id,
                Err(r) => return r,
            };
            use crate::api::runners::HarnessRunner as _;
            Box::pin(
                crate::api::runners::ChatGptUiRunner.run_turn(crate::api::runners::TurnContext {
                    workspace: exec_workspace,
                    work_dir: &ctx.working_dir,
                    // The browser always starts a fresh chat, so include the
                    // bounded conversation frame on follow-up turns.
                    message: &convo,
                    model: requested_model
                        .as_deref()
                        .or(config.default_model.as_deref()),
                    model_effort: None,
                    fast_mode: false,
                    agent: None,
                    mission_id: mid,
                    events_tx: events_tx.clone(),
                    cancel,
                    app_working_dir: &config.working_dir,
                    session_id: None,
                    is_continuation: false,
                    extras: crate::api::runners::TurnExtras::None,
                }),
            )
            .await
        }
        Some(backend) if backend != "opencode" => {
            let _ = events_tx.send(AgentEvent::Error {
                message: format!("Unsupported backend: {}", backend),
                mission_id,
                resumable: mission_id.is_some(),
            });
            crate::agents::AgentResult::failure(format!("Unsupported backend: {}", backend), 0)
                .with_terminal_reason(TerminalReason::LlmError)
        }
        _ => {
            // Default to opencode using per-workspace CLI execution
            let mid = mission_id.unwrap_or_else(Uuid::nil);
            // A stored OpenCode-format session_id (starts with `ses_`) is
            // itself a strong signal of a continuation even when the
            // in-memory history has no assistant message (e.g. server
            // restart, mission resume, history rebuild). The per-mission
            // XDG storage still has the prior session, and we want
            // --session/--continue to fire so we don't lose context. This
            // mirrors the `mission_runner` arm and fixes Bugbot e8dd69f8.
            //
            // Note: missions also carry a *Claude Code*-style UUID
            // session_id from mission creation, which the opencode CLI
            // does not understand. We ignore that here (treat as no
            // session) and let `is_opencode_session_id` in the runner
            // filter it out as well, so the CLI never receives an invalid
            // `--session <UUID>` and errors with "Session not found".
            let has_opencode_session = session_id
                .as_deref()
                .map(super::mission_runner::is_opencode_session_id)
                .unwrap_or(false);
            let opencode_is_continuation = force_session_resume
                || history.iter().any(|(role, _)| role == "assistant")
                || has_opencode_session;
            // Goal-mode missions drive a /goal <objective> loop and need the
            // raw message preserved verbatim. For normal continuations, when
            // we have a stored OpenCode session_id the opencode CLI will
            // load prior messages from its own storage, so we send the bare
            // user message instead of the history-framed `convo` (which
            // would duplicate the context the session already has). When we
            // don't have an OpenCode session_id (first turn of a brand-new
            // mission, a legacy mission that never persisted one, or a
            // mission that only has the Claude-Code UUID placeholder),
            // keep using `convo` so the model still gets a history-aware
            // prompt.
            let canonical_goal = canonical_goal_message(&user_message);
            let opencode_message_owned: String = if let Some(goal) = canonical_goal {
                goal
            } else if opencode_is_continuation && has_opencode_session {
                user_message.clone()
            } else {
                convo.clone()
            };
            use crate::api::runners::HarnessRunner as _;
            Box::pin(crate::api::runners::OpenCodeRunner.run_turn(
                crate::api::runners::TurnContext {
                    workspace: exec_workspace,
                    work_dir: &ctx.working_dir,
                    message: &opencode_message_owned,
                    model: config.default_model.as_deref(),
                    model_effort: requested_model_effort.as_deref(),
                    fast_mode: false,
                    agent: config.opencode_agent.as_deref(),
                    mission_id: mid,
                    events_tx: events_tx.clone(),
                    cancel,
                    app_working_dir: &config.working_dir,
                    session_id: session_id.as_deref(),
                    is_continuation: opencode_is_continuation,
                    extras: crate::api::runners::TurnExtras::None,
                },
            ))
            .await
        }
    };
    result
}

// === Automation API handlers ===

#[derive(Debug, Deserialize)]
pub struct CreateAutomationRequest {
    pub command_source: mission_store::CommandSource,
    pub trigger: mission_store::TriggerType,
    #[serde(default)]
    pub variables: HashMap<String, String>,
    #[serde(default)]
    pub retry_config: Option<mission_store::RetryConfig>,
    #[serde(default)]
    pub stop_policy: Option<mission_store::StopPolicy>,
    #[serde(default)]
    pub fresh_session: Option<mission_store::FreshSession>,
    /// When true, trigger the first execution immediately after creation.
    #[serde(default)]
    pub start_immediately: bool,
}

#[derive(Debug, Deserialize)]
pub struct UpdateAutomationRequest {
    pub command_source: Option<mission_store::CommandSource>,
    pub trigger: Option<mission_store::TriggerType>,
    pub variables: Option<HashMap<String, String>>,
    pub retry_config: Option<mission_store::RetryConfig>,
    pub stop_policy: Option<mission_store::StopPolicy>,
    pub fresh_session: Option<mission_store::FreshSession>,
    pub active: Option<bool>,
}

/// List all automations for a mission.
pub async fn list_mission_automations(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
) -> Result<Json<Vec<mission_store::Automation>>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;

    let automations = control
        .mission_store
        .get_mission_automations(mission_id)
        .await
        .map_err(internal_error)?;

    Ok(Json(automations))
}

/// List all active automations across missions.
pub async fn list_active_automations(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
) -> Result<Json<Vec<mission_store::Automation>>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;

    let automations = control
        .mission_store
        .list_active_automations()
        .await
        .map_err(internal_error)?;

    Ok(Json(automations))
}

/// Create an automation for a mission.
pub async fn create_automation(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(mission_id): Path<Uuid>,
    Json(req): Json<CreateAutomationRequest>,
) -> Result<Json<mission_store::Automation>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;

    if control
        .mission_store
        .get_mission(mission_id)
        .await
        .map_err(internal_error)?
        .is_none()
    {
        tracing::warn!(
            mission_id = %mission_id,
            user_id = %user.id,
            "Rejecting automation create for missing mission"
        );
        return Err((
            StatusCode::NOT_FOUND,
            format!("Mission {} not found; cannot create automation", mission_id),
        ));
    }

    // Validate the command exists in the library if CommandSource::Library
    if let mission_store::CommandSource::Library { ref name } = req.command_source {
        validate_library_command(&state, name).await?;
    }

    // Generate webhook_id if trigger type is Webhook
    let trigger = match req.trigger {
        mission_store::TriggerType::Webhook { mut config } => {
            // Generate a unique webhook_id if not provided or empty
            if config.webhook_id.is_empty() {
                config.webhook_id = Uuid::new_v4().to_string();
            }
            mission_store::TriggerType::Webhook { config }
        }
        other => other,
    };

    // Validate cron expression before persisting
    if let mission_store::TriggerType::Cron { ref expression, .. } = trigger {
        if croner::Cron::new(expression).parse().is_err() {
            return Err((
                StatusCode::BAD_REQUEST,
                format!("Invalid cron expression: {}", expression),
            ));
        }
    }

    if let mission_store::TriggerType::DurableJobTerminal { job_id } = &trigger {
        super::durable_jobs::terminal_for_mission(&state.config.working_dir, *job_id, mission_id)
            .await
            .map_err(|error| (StatusCode::BAD_REQUEST, error))?;
    }

    let start_immediately = req.start_immediately;

    // For interval/cron triggers, if start_immediately is false, set last_triggered_at
    // to now so the scheduler waits for the next occurrence before the first trigger.
    let last_triggered_at = if !start_immediately
        && matches!(
            trigger,
            mission_store::TriggerType::Interval { .. } | mission_store::TriggerType::Cron { .. }
        ) {
        Some(mission_store::now_string())
    } else {
        None
    };

    // Build the complete Automation struct
    let fresh_session = req
        .fresh_session
        .unwrap_or(mission_store::FreshSession::Keep);
    if fresh_session == mission_store::FreshSession::Switch {
        let has_next_session_id = req
            .variables
            .get("nextSessionId")
            .map(|value| Uuid::parse_str(value.trim()).is_ok())
            .unwrap_or(false);
        if !has_next_session_id {
            return Err((
                StatusCode::BAD_REQUEST,
                "session mode 'switch' requires variables.nextSessionId to be a valid mission UUID"
                    .to_string(),
            ));
        }
    }

    let automation = mission_store::Automation {
        id: Uuid::new_v4(),
        mission_id,
        command_source: req.command_source,
        trigger,
        variables: req.variables,
        active: true,
        stop_policy: req
            .stop_policy
            .unwrap_or(mission_store::StopPolicy::WhenFailingConsecutively { count: 2 }),
        fresh_session,
        created_at: mission_store::now_string(),
        last_triggered_at,
        retry_config: req.retry_config.unwrap_or_default(),
        consecutive_failures: 0,
        driver: mission_store::AutomationDriver::Scheduler,
    };

    let is_one_shot_wakeup = automation.variables.contains_key("__wakeup_source");
    let wakeup_key = wakeup_supersession_key(
        automation
            .variables
            .get("__wakeup_source")
            .map(String::as_str),
        &automation.trigger,
    );

    tracing::info!(
        mission_id = %mission_id,
        automation_id = %automation.id,
        command_source = ?automation.command_source,
        trigger = ?automation.trigger,
        fresh_session = ?automation.fresh_session,
        is_one_shot_wakeup,
        "Creating mission automation"
    );

    let mut automation = control
        .mission_store
        .create_automation(automation)
        .await
        .map_err(internal_error)?;

    // One pending wakeup per mission: a new ScheduleWakeup
    // supersedes any earlier un-fired one. Without this, a turn that starts
    // before the previous wakeup fires (user message, other automation)
    // schedules a second wakeup, and the leftovers pile up into overlapping
    // re-triggers (observed: 5 concurrent pending wakeups on one mission,
    // all firing within two minutes).
    //
    // Ordering: the new wakeup is created *first*, then older ones are
    // deactivated — if creation fails the mission keeps its previous wakeup
    // instead of losing all of them. Only automations strictly older than
    // the new row are deactivated ((created_at, id) tie-break), so two
    // overlapping creates converge on exactly the newest wakeup instead of
    // deactivating each other.
    let mut wakeup_iteration: u32 = 1;
    if let Some(wakeup_key) = wakeup_key {
        if let Ok(existing) = control
            .mission_store
            .get_mission_automations(mission_id)
            .await
        {
            let new_key = (automation.created_at.clone(), automation.id.to_string());
            let priors: Vec<_> = existing
                .into_iter()
                .filter(|a| {
                    a.id != automation.id
                        && wakeup_supersession_key(
                            a.variables.get("__wakeup_source").map(String::as_str),
                            &a.trigger,
                        ) == Some(wakeup_key.clone())
                })
                .collect();
            wakeup_iteration = (priors.len() as u32).saturating_add(1);
            for prior in priors
                .into_iter()
                .filter(|a| a.active && (a.created_at.clone(), a.id.to_string()) < new_key)
            {
                if let Err(e) = control
                    .mission_store
                    .update_automation_active(prior.id, false)
                    .await
                {
                    tracing::warn!(
                        "Failed to deactivate superseded wakeup automation {}: {}",
                        prior.id,
                        e
                    );
                }
            }
        }
    }

    // Persist a goal-iteration marker for self-paced loops so the dashboard
    // and assistant can see loop progress after a reload — previously this
    // state lived only in the (transient) wakeup automations.
    if is_one_shot_wakeup {
        let _ = control.events_tx.send(AgentEvent::GoalIteration {
            iteration: wakeup_iteration,
            objective: automation
                .variables
                .get("__wakeup_reason")
                .cloned()
                .unwrap_or_default(),
            mission_id: Some(mission_id),
        });
    }

    // If start_immediately is requested for agent_finished triggers, fire the
    // first execution right away by resolving the command and sending it as a
    // user message to the control actor.
    if start_immediately
        && matches!(
            automation.trigger,
            mission_store::TriggerType::AgentFinished
        )
    {
        if let Ok(Some(mission)) = control.mission_store.get_mission(mission_id).await {
            // Newly created automation has 0 consecutive failures and has never fired.
            if stop_policy_matches_status(&automation.stop_policy, mission.status, 0, false).await {
                let mut updated = automation.clone();
                updated.active = false;
                if let Err(e) = control.mission_store.update_automation(updated).await {
                    tracing::warn!(
                        "Failed to disable automation {} on create due to stop policy: {}",
                        automation.id,
                        e
                    );
                }
                automation.active = false;
                return Ok(Json(automation));
            }
        }

        let cmd_content =
            resolve_automation_command(&automation, mission_id, &state, &control.mission_store)
                .await;

        if let Some(content) = cmd_content {
            let target_mission_id = match control.mission_store.get_mission(mission_id).await {
                Ok(Some(mission)) => {
                    resolve_agent_finished_target_mission(mission_id, mission.status, &automation)
                }
                Ok(None) => mission_id,
                Err(e) => {
                    tracing::warn!(
                        "Failed to load mission {} while resolving start_immediately target: {}",
                        mission_id,
                        e
                    );
                    mission_id
                }
            };

            // Record the execution in Running status – it will be completed
            // by complete_running_executions_for_mission when the agent
            // finishes processing.
            let execution_id = Uuid::new_v4();
            let execution = mission_store::AutomationExecution {
                id: execution_id,
                automation_id: automation.id,
                mission_id: target_mission_id,
                triggered_at: mission_store::now_string(),
                trigger_source: "start_immediately".to_string(),
                status: mission_store::ExecutionStatus::Running,
                webhook_payload: None,
                variables_used: automation.variables.clone(),
                completed_at: None,
                error: None,
                retry_count: 0,
            };
            let _ = control
                .mission_store
                .create_automation_execution(execution)
                .await;
            let _ = control
                .mission_store
                .update_automation_last_triggered(automation.id)
                .await;

            // Send as a user message to the mission
            let (respond_tx, _respond_rx) = tokio::sync::oneshot::channel();
            let _ = control
                .cmd_tx
                .send(ControlCommand::UserMessage {
                    id: Uuid::new_v4(),
                    content,
                    agent: None,
                    target_mission_id: Some(target_mission_id),
                    strict: false,
                    source: None,
                    respond: respond_tx,
                })
                .await;
        }
    }

    Ok(Json(automation))
}

/// Get an automation by ID.
pub async fn get_automation(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(automation_id): Path<Uuid>,
) -> Result<Json<mission_store::Automation>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;

    let automation = require_automation(&control.mission_store, automation_id).await?;

    Ok(Json(automation))
}

/// Update an automation.
pub async fn update_automation(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(automation_id): Path<Uuid>,
    Json(req): Json<UpdateAutomationRequest>,
) -> Result<Json<mission_store::Automation>, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;

    let mut automation = require_automation(&control.mission_store, automation_id).await?;

    // Validate the command exists in the library if CommandSource::Library is being updated
    if let Some(mission_store::CommandSource::Library { name }) = req.command_source.as_ref() {
        validate_library_command(&state, name).await?;
    }

    // Update fields if provided
    if let Some(command_source) = req.command_source {
        automation.command_source = command_source;
    }

    if let Some(trigger) = req.trigger {
        // Generate webhook_id if trigger type is Webhook and webhook_id is empty
        automation.trigger = match trigger {
            mission_store::TriggerType::Webhook { mut config } => {
                if config.webhook_id.is_empty() {
                    config.webhook_id = Uuid::new_v4().to_string();
                }
                mission_store::TriggerType::Webhook { config }
            }
            other => other,
        };
    }

    if let Some(variables) = req.variables {
        automation.variables = variables;
    }

    if let Some(retry_config) = req.retry_config {
        automation.retry_config = retry_config;
    }

    if let Some(stop_policy) = req.stop_policy {
        automation.stop_policy = stop_policy;
    }

    if let Some(fresh_session) = req.fresh_session {
        automation.fresh_session = fresh_session;
    }

    if let Some(active) = req.active {
        automation.active = active;
    }

    if let mission_store::TriggerType::Cron { expression, .. } = &automation.trigger {
        if croner::Cron::new(expression).parse().is_err() {
            return Err((
                StatusCode::BAD_REQUEST,
                format!("Invalid cron expression: {expression}"),
            ));
        }
    }
    if let mission_store::TriggerType::DurableJobTerminal { job_id } = &automation.trigger {
        super::durable_jobs::terminal_for_mission(
            &state.config.working_dir,
            *job_id,
            automation.mission_id,
        )
        .await
        .map_err(|error| (StatusCode::BAD_REQUEST, error))?;
    }

    if automation.fresh_session == mission_store::FreshSession::Switch {
        let has_next_session_id = automation
            .variables
            .get("nextSessionId")
            .map(|value| Uuid::parse_str(value.trim()).is_ok())
            .unwrap_or(false);
        if !has_next_session_id {
            return Err((
                StatusCode::BAD_REQUEST,
                "session mode 'switch' requires variables.nextSessionId to be a valid mission UUID"
                    .to_string(),
            ));
        }
    }

    // Update automation in the store
    control
        .mission_store
        .update_automation(automation.clone())
        .await
        .map_err(internal_error)?;

    Ok(Json(automation))
}

/// Delete an automation.
pub async fn delete_automation(
    State(state): State<Arc<AppState>>,
    Extension(user): Extension<AuthUser>,
    Path(automation_id): Path<Uuid>,
) -> Result<StatusCode, (StatusCode, String)> {
    let control = control_for_user(&state, &user).await;

    let deleted = control
        .mission_store
        .delete_automation(automation_id)
        .await
        .map_err(internal_error)?;

    if deleted {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err((
            StatusCode::NOT_FOUND,
            format!("Automation {} not found", automation_id),
        ))
    }
}

